/* ホバー判定: 描画時点のマウス位置で決める軽量方式。
 * マウス移動でも再描画が走るため、対象が変われば次の
 * フレームで見た目が切り替わる。 */
static int ui_hover(int x, int y, int w, int h) {
    return mouse_x >= x && mouse_x < x + w &&
           mouse_y >= y && mouse_y < y + h;
}

static uint64_t taskbar_y(void) {
    return desk_settings.taskbar_top ? 0 : fb_height() - TASKBAR_H;
}
static int taskbar_vertical(void) {
    return desk_settings.taskbar_side != 0;
}
static uint64_t dock_y(void) {
    if (taskbar_vertical()) {
        return fb_height() - DOCK_H;
    }
    return desk_settings.taskbar_top ? TASKBAR_H
                                     : fb_height() - TASKBAR_H - DOCK_H;
}
/* Dock geometry, shared by the drawing and the click hit
 * test so the two can never disagree (they once did below
 * 1280 px). Position: 0 = bottom strip (above the taskbar),
 * 1 = left edge (vertical). Size scales the buttons.
 * When autohide is on, the Dock is only drawn while the
 * mouse is near its edge (or a panel is open). */
static int dock_strip_h(void) {
    return desk_settings.dock_size ? DOCK_H + 12 : DOCK_H;
}
static int dock_btn_w(void) {
    int want = desk_settings.dock_size ? 92 : 76;
    /* アプリが増えて画面幅に収まらないときは、ボタン幅を
     * 縮めて全アプリが画面内に収まるようにする。 */
    int count = desk_visible_count();
    if (count > 0 && desk_settings.dock_pos != 1) {
        int fit = ((int)fb_width() - 16 - (count - 1) * 4) / count;
        if (fit < want) {
            want = fit < 40 ? 40 : fit;
        }
    }
    return want;
}
static int dock_btn_h(void) {
    return desk_settings.dock_size ? 40 : 32;
}
static int dock_visible_now(void) {
    if (!desk_settings.dock_show) {
        return 0;
    }
    if (!desk_settings.dock_autohide) {
        return 1;
    }
    if (launcher_active || menu_active) {
        return 1;
    }
    if (desk_settings.dock_pos == 1) {
        return mouse_x < dock_btn_w() + 14;
    }
    return mouse_y > (int)dock_y() - 14;
}
/* Fills in the Dock button layout: for the bottom strip,
 * buttons run left to right starting at (start, cross);
 * for the left strip they run top to bottom starting at
 * (cross, start). Returns the visible app count. */
static int dock_layout(int64_t *start, int64_t *cross) {
    int count = desk_visible_count();
    int gap = 4;
    if (desk_settings.dock_pos == 1) {
        *cross = desk_settings.taskbar_side == 1 ? TASKBAR_W + 6 : 6;
        *start = (int64_t)(desk_settings.taskbar_top ? TASKBAR_H : 0) + 8;
    } else {
        int bw = dock_btn_w();
        int total = count * bw + (count - 1) * gap;
        *start = ((int64_t)fb_width() - total) / 2;
        *cross = (int64_t)dock_y() +
                 (dock_strip_h() - dock_btn_h()) / 2;
    }
    return count;
}
/* タイトルバーのボタンで切り替える主ウィンドウの状態。
 * 最大化 = 作業領域いっぱい、最小化 = 描画を休止。 */
static int desk_win_max;
static int desk_win_min;

/* 画面キーボード表示中に下端で予約する高さ (E2)。
 * 実体は OSK 節で定義する。 */
static int osk_reserved_h(void);

/* The app window covers about 78% of the width and 72% of the
 * height, centred in the space between the taskbar and the
 * Dock, so the wallpaper (gradient, rays, prism) stays visible
 * around it instead of being hidden behind the window. */
/* ---- 動き (第2ラウンド stage 4) ----
 * 167ms のフェード+スライドを駆動する時計。PIT IRQ0 は
 * サンドボックスのウォッチドッグが使うので、初期化時に
 * PIT カウンタで約 50ms を測って TSC を較正し、以後は
 * rdtsc だけで時刻を読む。較正できなければ動きは無効。 */
#define UI_ANIM_MS 167
static uint64_t tsc_per_ms;
static uint64_t launcher_anim_t0;
static uint64_t launcher_close_t0;
static int launcher_closing;
static uint64_t win_anim_t0;

static uint64_t rdtsc_now(void) {
    uint32_t lo, hi;
    __asm__ volatile("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

static void ui_clock_init(void) {
    uint16_t prev = speaker_pit0_count();
    uint64_t t0 = rdtsc_now();
    uint32_t waited = 0;
    uint32_t guard = 0;
    while (waited < 60000 && guard < 200000000u) {
        uint16_t cur = speaker_pit0_count();
        waited += (uint16_t)(prev - cur);
        prev = cur;
        guard++;
    }
    uint64_t dt = rdtsc_now() - t0;
    /* 60000 カウント = 約 50.3ms。 */
    tsc_per_ms = dt / 50;
    if (tsc_per_ms == 0) {
        tsc_per_ms = 1;
    }
}

static uint64_t ui_now_ms(void) {
    if (tsc_per_ms == 0) {
        return 0;
    }
    return rdtsc_now() / tsc_per_ms;
}

static int ui_motion_on(void) {
    return desk_settings.ui_motion && tsc_per_ms != 0;
}

/* 開き具合 f (0..256) に対するイーズアウト済みの値。 */
static int ui_ease_out(int f) {
    int u = 256 - f;
    return 256 - u * u * u / 65536;
}

/* ランチャーのスライド量 (px)。描画と当たり判定の両方が
 * launcher_geometry 経由でこれを使うのでずれない。 */
static int launcher_anim_dy(void) {
    if (!launcher_active || !ui_motion_on()) {
        return 0;
    }
    uint64_t now = ui_now_ms();
    int f;
    if (launcher_closing) {
        uint64_t e = now - launcher_close_t0;
        if (e >= UI_ANIM_MS) {
            return 26;
        }
        f = 256 - (int)(e * 256 / UI_ANIM_MS);
    } else {
        uint64_t e = now - launcher_anim_t0;
        if (e >= UI_ANIM_MS) {
            return 0;
        }
        f = (int)(e * 256 / UI_ANIM_MS);
    }
    return (256 - ui_ease_out(f)) * 26 / 256;
}

static int launcher_panel_alpha(void) {
    int dy = launcher_anim_dy();
    return 234 - dy * (234 - 120) / 26;
}

/* 閉じアニメーションの開始 (動きが無効なら即閉じ)。 */
static void launcher_request_close(void) {
    if (!launcher_active || launcher_closing) {
        return;
    }
    if (ui_motion_on()) {
        launcher_closing = 1;
        launcher_close_t0 = ui_now_ms();
    } else {
        launcher_active = 0;
    }
}

/* ウィンドウ出現時のスライド量 (px)。 */
static int win_anim_offset(void) {
    if (!ui_motion_on() || desk_win_max) {
        return 0;
    }
    uint64_t e = ui_now_ms() - win_anim_t0;
    if (e >= UI_ANIM_MS) {
        return 0;
    }
    int f = (int)(e * 256 / UI_ANIM_MS);
    return (256 - ui_ease_out(f)) * 12 / 256;
}

static uint64_t win_x(void) {
    uint64_t base = 0;
    uint64_t area = fb_width();
    if (desk_settings.taskbar_side == 1) {
        base = TASKBAR_W;
        area = fb_width() - TASKBAR_W;
    } else if (desk_settings.taskbar_side == 2) {
        area = fb_width() - TASKBAR_W;
    }
    if (desk_win_max) {
        return base;
    }
    uint64_t w = area * 78 / 100;
    return base + (area - w) / 2;
}
static uint64_t win_y(void) {
    if (desk_win_max) {
        if (taskbar_vertical()) {
            return 0;
        }
        return desk_settings.taskbar_top ? TASKBAR_H : 0;
    }
    if (taskbar_vertical()) {
        uint64_t avail = fb_height() - DOCK_H -
                         (uint64_t)osk_reserved_h();
        uint64_t h = avail * 72 / 100;
        return (avail - h) / 2 + (uint64_t)win_anim_offset();
    }
    uint64_t top = desk_settings.taskbar_top ? (TASKBAR_H + DOCK_H) : 0;
    uint64_t avail = desk_settings.taskbar_top
                         ? fb_height() - top -
                               (uint64_t)osk_reserved_h()
                         : fb_height() - TASKBAR_H - DOCK_H -
                               (uint64_t)osk_reserved_h();
    uint64_t h = avail * 72 / 100;
    return top + (avail - h) / 2 + (uint64_t)win_anim_offset();
}
static uint64_t win_w(void) {
    uint64_t area = fb_width();
    if (taskbar_vertical()) {
        area = fb_width() - TASKBAR_W;
    }
    if (desk_win_max) {
        return area;
    }
    return area * 78 / 100;
}
static uint64_t win_h(void) {
    if (desk_win_max) {
        uint64_t dock = desk_settings.dock_show ? DOCK_H : 0;
        if (taskbar_vertical()) {
            return fb_height() - dock - (uint64_t)osk_reserved_h();
        }
        return fb_height() - TASKBAR_H - dock -
               (uint64_t)osk_reserved_h();
    }
    if (taskbar_vertical()) {
        return (fb_height() - DOCK_H -
                (uint64_t)osk_reserved_h()) * 72 / 100;
    }
    uint64_t top = desk_settings.taskbar_top ? (TASKBAR_H + DOCK_H) : 0;
    uint64_t avail = desk_settings.taskbar_top
                         ? fb_height() - top -
                               (uint64_t)osk_reserved_h()
                         : fb_height() - TASKBAR_H - DOCK_H -
                               (uint64_t)osk_reserved_h();
    return avail * 72 / 100;
}
static uint64_t text_x(void) {
    return win_x() + 8;
}
static uint64_t text_y(void) {
    return win_y() + TITLE_H + 8;
}
static int text_cols(void) {
    uint64_t w = win_w();
    if (w < 16) {
        return 0;
    }
    return (int)((w - 16) / CELL_W);
}
static int text_rows(void) {
    uint64_t h = win_h();
    if (h < TITLE_H + 16) {
        return 0;
    }
    return (int)((h - TITLE_H - 16) / CELL_H);
}

/* 設定アプリ専用の本文原点 (C3): 左にページ一覧サイドバー
 * (15 セル + 余白) を置くため、本文を右へ寄せる。 */
static uint64_t set_x(void) {
    /* 左ペイン幅: 標準文字で 240px (T4 の 240〜280 に
     * 入る)。文字サイズに比例させるのは従来どおり。 */
    return text_x() + 20 * (uint64_t)CELL_W + 12;
}

/* 設定本文の右端 (ウィンドウ右端の内側)。 */
static uint64_t set_right(void) {
    return win_x() + win_w() - 12;
}

/* ---- AA テキスト (第2ラウンド) ----
 * 本文・見出し・注記はアンチエイリアスフォントで描く。
 * 呼び出し側の y は従来どおり「行の上端」で受け取り、
 * ここでベースラインへ変換する。px はビットマップ時代
 * のグリフ高に合わせてあり (本文 16*scale、見出しは
 * その次の段、注記は本物の 12*scale)、インクの位置は
 * 従来とほぼ一致する。 */
static int aa_px_body(void) {
    return 16 * text_scale_now();
}
static int aa_px_title(void) {
    return 16 * (text_scale_now() + 1);
}
static int aa_px_caption(void) {
    return 12 * text_scale_now();
}
static int64_t aa_baseline(uint64_t y, int px) {
    return (int64_t)y + px * 13 / 16;
}

static void draw_text_small(uint64_t x, uint64_t y, const char *s,
                            uint32_t fg, uint32_t bg) {
    int px = aa_px_body();
    fb_draw_text_aa((int64_t)x, aa_baseline(y, px), s, fg,
                    (int32_t)bg, px, 0);
}

/* ---- 文字の段 (T1 / 第2ラウンドで AA 化) ----
 * ページ見出しは本文より 1 段大きい太字、注記は
 * 12px 級の通常字 + 薄い色、セクション見出しは
 * 本文サイズの太字 + アクセント色で段を付ける。
 * レイアウト上の行高 (ui_title_h 等) は従来の段の
 * 高さのままにしてある。 */
static int ui_unit_title(void) {
    int u = text_scale_now() + 1;
    return u > 4 ? 4 : u;
}

/* ページ見出し 1 行が占める高さ (グリフ + 余白)。 */
static uint64_t ui_title_h(void) {
    return (uint64_t)(16 * ui_unit_title()) + 12;
}

static void draw_text_title(uint64_t x, uint64_t y, const char *s,
                            uint32_t fg, uint32_t bg) {
    int px = aa_px_title();
    fb_draw_text_aa((int64_t)x, aa_baseline(y, px), s, fg,
                    (int32_t)bg, px, 1);
}

/* 注記 (説明文) の段: 本物の 12px 級 + 薄い色で描く。 */
static void draw_text_caption(uint64_t x, uint64_t y, const char *s,
                              uint32_t bg) {
    int px = aa_px_caption();
    fb_draw_text_aa((int64_t)x, aa_baseline(y, px), s, col_dim(),
                    (int32_t)bg, px, 0);
}

/* ---- 本文 AA 化のための計測ヘルパー (第3ラウンド) ----
 * 編集系アプリの本文は、描画も折り返しもキャレット位置も
 * AA フォントの実アドバンスで測る。制御文字は半角相当の
 * 固定幅として扱い、描画はしない。 */
static int aa_cp_advance(uint32_t cp, int px, int bold) {
    if (cp < 0x20 || cp == 0x7F) {
        return px / 2;
    }
    char tmp[5];
    int n = 0;
    if (cp < 0x80) {
        tmp[n++] = (char)cp;
    } else if (cp < 0x800) {
        tmp[n++] = (char)(0xC0 | (cp >> 6));
        tmp[n++] = (char)(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
        tmp[n++] = (char)(0xE0 | (cp >> 12));
        tmp[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
        tmp[n++] = (char)(0x80 | (cp & 0x3F));
    } else {
        tmp[n++] = (char)(0xF0 | (cp >> 18));
        tmp[n++] = (char)(0x80 | ((cp >> 12) & 0x3F));
        tmp[n++] = (char)(0x80 | ((cp >> 6) & 0x3F));
        tmp[n++] = (char)(0x80 | (cp & 0x3F));
    }
    tmp[n] = '\0';
    return (int)fb_text_aa_width(tmp, px, bold);
}

/* 文字列を AA 実幅 maxw に収まるようコードポイント
 * 境界で切り詰める (その場で書き換える)。 */
static void aa_truncate(char *s, int maxw, int px, int bold) {
    int x = 0;
    size_t i = 0;
    size_t last = 0;
    while (s[i] != '\0') {
        uint32_t cp = 0;
        int nb = jfont_utf8_decode(s + i, strlen(s + i), &cp);
        if (nb <= 0) {
            break;
        }
        int adv = aa_cp_advance(cp, px, bold);
        if (x + adv > maxw) {
            break;
        }
        x += adv;
        i += (size_t)nb;
        last = i;
    }
    s[last] = '\0';
}

/* バイト範囲 [s, s+len) を AA で描く (一時バッファ経由)。 */
static void draw_text_aa_range(uint64_t x, uint64_t y, const char *s,
                               size_t len, uint32_t fg, int32_t bg,
                               int px, int bold) {
    char buf[512];
    if (len > sizeof(buf) - 1) {
        len = sizeof(buf) - 1;
    }
    for (size_t i = 0; i < len; i++) {
        buf[i] = s[i];
    }
    buf[len] = '\0';
    fb_draw_text_aa((int64_t)x, aa_baseline(y, px), buf, fg, bg,
                    px, bold);
}

static void lerp_rgb(uint32_t a, uint32_t b, int step, int steps,
                     uint8_t *r, uint8_t *g, uint8_t *bl) {
    int ar = (int)((a >> 16) & 0xFF);
    int ag = (int)((a >> 8) & 0xFF);
    int ab = (int)(a & 0xFF);
    int br = (int)((b >> 16) & 0xFF);
    int bg = (int)((b >> 8) & 0xFF);
    int bb = (int)(b & 0xFF);
    *r = (uint8_t)(ar + (br - ar) * step / steps);
    *g = (uint8_t)(ag + (bg - ag) * step / steps);
    *bl = (uint8_t)(ab + (bb - ab) * step / steps);
}

static void draw_wallpaper(void) {
    /* 自分の画像が選ばれていて読み込めていればそれを最優先。
     * 読めなければ標準画像→描画の順にフォールバックする。 */
    if (desk_settings.wallpaper_image == 2 && wp_custom_ok) {
        wallpaper_draw(&wp_custom_img);
        return;
    }
    /* The real image first, when the setting asks for it and the
     * embedded BMP parsed. Otherwise the drawn gradient. */
    if (desk_settings.wallpaper_image && wallpaper_ok) {
        wallpaper_draw(&wallpaper_image);
        return;
    }
    uint64_t w = fb_width();
    uint64_t h = fb_height();
    uint32_t top = desk_settings.dark_mode ? 0x0B1026 : 0xF2F4F8;
    uint32_t bottom = desk_settings.dark_mode ? 0x261A40 : 0xCDD6E8;
    const int bands = 48;
    for (int i = 0; i < bands; i++) {
        uint8_t r, g, b;
        lerp_rgb(top, bottom, i, bands - 1, &r, &g, &b);
        uint64_t y0 = h * (uint64_t)i / (uint64_t)bands;
        uint64_t y1 = h * (uint64_t)(i + 1) / (uint64_t)bands;
        fb_fill_rect(0, y0, w, y1 - y0, fb_rgb(r, g, b));
    }
    /* Light rays from a glass prism: three diagonal bands in
     * the accent colours, drawn as thick lines. The prism sits
     * in the strip above the app window (the window covers the
     * middle of the screen), and the rays run from it to the
     * right edge, passing behind the window. */
    int64_t cx = (int64_t)(w / 2);
    int64_t cy = 52;
    static const uint32_t ray_colours[3] = {0x4CC2FF, 0x7C5CFF, 0xFF6FB5};
    for (int i = 0; i < 3; i++) {
        int64_t y_end = 190 + i * 60;
        for (int t = -1; t <= 1; t++) {
            fb_draw_line(cx + 40, cy + 20 + t, (int64_t)w - 40,
                         y_end + t, rgb(ray_colours[i]));
        }
    }
    /* The prism itself: a triangle outline in the accent colour. */
    uint32_t acc = col_accent();
    fb_draw_line(cx, cy - 42, cx - 38, cy + 30, acc);
    fb_draw_line(cx - 38, cy + 30, cx + 38, cy + 30, acc);
    fb_draw_line(cx + 38, cy + 30, cx, cy - 42, acc);
}

