static void draw_console_text(void) {
    if (!console_ok) {
        return;
    }
    uint32_t fg = col_text();
    uint32_t bg = col_window_bg();
    uint64_t x0 = text_x();
    uint64_t y0 = text_y();
    /* スクロールバック表示中は、履歴と現グリッドを
     * つないだ仮想行から描く。 */
    int hist_avail = console_hist_count < CONSOLE_HIST_LINES
                         ? console_hist_count
                         : CONSOLE_HIST_LINES;
    if (console_view_offset > hist_avail) {
        console_view_offset = hist_avail;
    }
    for (int row = 0; row < console_rows; row++) {
        for (int col = 0; col < console_cols; col++) {
            uint32_t cp;
            if (console_view_offset > 0 &&
                console_hist != NULL &&
                console_hist_cols == console_cols) {
                /* 結合行: 履歴 (古い順) + 現グリッド。 */
                int ci = hist_avail - console_view_offset + row;
                if (ci < hist_avail) {
                    int slot = (console_hist_count - hist_avail +
                                ci) %
                               CONSOLE_HIST_LINES;
                    if (slot < 0) {
                        slot += CONSOLE_HIST_LINES;
                    }
                    cp = console_hist[slot * console_cols + col];
                } else {
                    cp = console_grid[(ci - hist_avail) *
                                          console_cols +
                                      col];
                }
            } else {
                cp = console_grid[row * console_cols + col];
            }
            if (cp == CONSOLE_WIDE_TAIL) {
                continue;
            }
            if (cp == 0) {
                cp = ' ';
            }
            uint64_t px = x0 + (uint64_t)(col * CELL_W);
            uint64_t py = y0 + (uint64_t)(row * CELL_H);
            int cursor = (row == console_row && col == console_col &&
                          desk_mode == DESK_TERMINAL &&
                          console_view_offset == 0);
            if (cp < 0x80) {
                /* Cursor: inverted block. */
                fb_draw_char(px, py, (char)cp, cursor ? bg : fg,
                             cursor ? fg : bg, TEXT_SCALE);
            } else {
                /* A wide glyph is 16x16: it covers this cell
                 * and the next one (24x16 together). */
                fb_draw_wide_char(px + 4, py, cp, cursor ? bg : fg,
                                  cursor ? fg : bg, 1);
                if (cursor && col + 1 < console_cols) {
                    fb_fill_rect(px + CELL_W, py, CELL_W, CELL_H, fg);
                }
            }
        }
    }
    if (console_view_offset > 0 && desk_mode == DESK_TERMINAL) {
        draw_text_small(x0,
                        y0 + (uint64_t)((console_rows - 1) * CELL_H),
                        L("-- scrollback (PgDn = back) --",
                          "-- スクロールバック中 (PgDn = 戻る) --"),
                        col_accent(), bg);
    }
    /* スクロールバー (C1): 履歴があるとき右端に出す。 */
    if (desk_mode == DESK_TERMINAL) {
        int total = console_hist_count + console_rows;
        if (total > console_rows) {
            uint64_t tx = x0 + (uint64_t)(console_cols * CELL_W) +
                          2;
            uint64_t th = (uint64_t)(console_rows * CELL_H);
            fb_fill_rect(tx, y0, 6, th, col_title_bg());
            uint64_t thumb_h = th * (uint64_t)console_rows /
                               (uint64_t)total;
            if (thumb_h < 18) {
                thumb_h = 18;
            }
            int back = console_view_offset;
            uint64_t thumb_y = y0;
            if (total - console_rows > 0) {
                thumb_y = y0 + (th - thumb_h) *
                                   (uint64_t)(total - console_rows -
                                              back) /
                                   (uint64_t)(total - console_rows);
            }
            fb_fill_rect(tx, thumb_y, 6, thumb_h, col_accent());
        }
    }
}

/* Files のディレクトリ移動: files_dir が現在の
 * ディレクトリ ("" = ルート)。行は files_rows に
 * 並ぶ: >=0 は VFS インデックス、-1 は ".."、
 * -2-j はサブディレクトリ (files_dirnames[j])。 */
static void serial_write_num(int v);
static void switch_mode(desktop_mode m);

static char files_dir[32];
static int files_rows[168];
static char files_dirnames[32][28];
static int files_row_count;
/* 一覧の行高 (B2): セル行より広げ、スクロールオフセット
 * (files_top) で選択行を追う。描画とクリック判定で共有。 */
#define FILES_ROW_H (CELL_H + 8)
static int files_top;
/* 一覧の並び順: 0 = 名前、1 = 日付 (新しい順)、
 * 2 = サイズ (大きい順)。'o' キーで切り替える。 */
static int files_sort_mode;

static int files_row_before(int x, int y) {
    const char *nx = vfs_file_name(x);
    const char *ny = vfs_file_name(y);
    if (files_sort_mode == 1) {
        uint32_t mx = vfs_file_mtime(x);
        uint32_t my = vfs_file_mtime(y);
        if (mx != my) {
            return mx > my;
        }
    } else if (files_sort_mode == 2) {
        size_t sx = 0;
        size_t sy = 0;
        (void)vfs_read_ptr(nx, &sx);
        (void)vfs_read_ptr(ny, &sy);
        if (sx != sy) {
            return sx > sy;
        }
    }
    return strcmp(nx != NULL ? nx : "", ny != NULL ? ny : "") < 0;
}

static void files_build_rows(void) {
    files_row_count = 0;
    int ndirs = 0;
    if (files_dir[0] != '\0') {
        files_rows[files_row_count++] = -1;
    }
    size_t pl = 0;
    while (files_dir[pl] != '\0') {
        pl++;
    }
    int count = vfs_file_count();
    for (int i = 0; i < count; i++) {
        const char *n = vfs_file_name(i);
        size_t k = 0;
        if (pl > 0) {
            while (k < pl && n[k] == files_dir[k]) {
                k++;
            }
            if (k != pl || n[pl] != '/') {
                continue;
            }
        }
        const char *rest = n + (pl > 0 ? pl + 1 : 0);
        if (rest[0] == '\0') {
            continue;
        }
        const char *slash = rest;
        while (*slash != '\0' && *slash != '/') {
            slash++;
        }
        if (*slash == '/') {
            size_t dl = (size_t)(slash - rest);
            if (dl >= 28) {
                continue;
            }
            char dn[28];
            for (size_t j = 0; j < dl; j++) {
                dn[j] = rest[j];
            }
            dn[dl] = '\0';
            int seen = 0;
            for (int j = 0; j < ndirs; j++) {
                if (strcmp(files_dirnames[j], dn) == 0) {
                    seen = 1;
                }
            }
            if (!seen && ndirs < 32 &&
                files_row_count < 168) {
                size_t q = 0;
                while (dn[q] != '\0') {
                    files_dirnames[ndirs][q] = dn[q];
                    q++;
                }
                files_dirnames[ndirs][q] = '\0';
                files_rows[files_row_count++] = -2 - ndirs;
                ndirs++;
            }
            continue;
        }
        if (strcmp(rest, ".dir") == 0) {
            continue;
        }
        if (files_row_count < 168) {
            files_rows[files_row_count++] = i;
        }
    }
    /* ファイル行 (>=0) だけを並び替える。".." と
     * フォルダ行は先頭のままにする。 */
    {
        int pos[168];
        int vals[168];
        int nf = 0;
        for (int a = 0; a < files_row_count; a++) {
            if (files_rows[a] >= 0) {
                pos[nf] = a;
                vals[nf] = files_rows[a];
                nf++;
            }
        }
        for (int a = 1; a < nf; a++) {
            int v = vals[a];
            int b = a - 1;
            while (b >= 0 && files_row_before(v, vals[b])) {
                vals[b + 1] = vals[b];
                b--;
            }
            vals[b + 1] = v;
        }
        for (int a = 0; a < nf; a++) {
            files_rows[pos[a]] = vals[a];
        }
    }
    if (files_selected >= files_row_count) {
        files_selected = files_row_count > 0 ? files_row_count - 1 : 0;
    }
    if (files_selected < 0) {
        files_selected = 0;
    }
}

/* ファイルをゴミ箱 (trash/) へ移す。成功 0。 */
static int files_trash_file(const char *name) {
    const char *base = name;
    for (const char *p = name; *p != '\0'; p++) {
        if (*p == '/') {
            base = p + 1;
        }
    }
    if (!vfs_exists("trash/.dir")) {
        (void)vfs_write("trash/.dir", "", 0);
    }
    char dst[40];
    for (int attempt = 0; attempt < 100; attempt++) {
        size_t p = 0;
        const char *pre = "trash/";
        while (pre[p] != '\0' && p + 1 < sizeof(dst)) {
            dst[p] = pre[p];
            p++;
        }
        size_t q = 0;
        while (base[q] != '\0' && p + 1 < sizeof(dst)) {
            dst[p++] = base[q++];
        }
        if (attempt > 0 && p + 2 < sizeof(dst)) {
            dst[p++] = '-';
            dst[p++] = (char)('0' + attempt);
        }
        dst[p] = '\0';
        if (!vfs_exists(dst)) {
            size_t len = 0;
            const char *content = vfs_read_ptr(name, &len);
            if (content == NULL) {
                return -1;
            }
            if (vfs_write(dst, content, len) != 0) {
                return -1;
            }
            return vfs_delete(name);
        }
    }
    return -1;
}

/* Files の名前入力プロンプトと確認ダイアログの状態。
 * prompt: 0=なし, 1=名前変更, 2=新規ファイル,
 * 3=新規フォルダ, 4=コピー。confirm: 0=なし,
 * 1=ゴミ箱を空にする, 2=完全に削除。 */
static int files_prompt;
static char files_prompt_buf[28];
static int files_prompt_len;
static int files_confirm;
static char files_confirm_name[32];

static int files_in_trash(void) {
    return strcmp(files_dir, "trash") == 0;
}

/* files_dir の下のパスを組み立てる。 */
static void files_join_path(char *out, size_t cap, const char *name) {
    size_t p = 0;
    size_t q = 0;
    while (files_dir[q] != '\0' && p + 1 < cap) {
        out[p++] = files_dir[q++];
    }
    if (p > 0 && p + 1 < cap) {
        out[p++] = '/';
    }
    q = 0;
    while (name[q] != '\0' && p + 1 < cap) {
        out[p++] = name[q++];
    }
    out[p] = '\0';
}

static int files_name_ok(const char *name) {
    if (name[0] == '\0') {
        return 0;
    }
    if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0 ||
        strcmp(name, ".dir") == 0) {
        return 0;
    }
    for (const char *p = name; *p != '\0'; p++) {
        if (*p == '/') {
            return 0;
        }
    }
    return 1;
}

static void files_prompt_start(int mode, const char *initial) {
    files_prompt = mode;
    files_prompt_len = 0;
    if (initial != NULL) {
        while (initial[files_prompt_len] != '\0' &&
               files_prompt_len + 1 < (int)sizeof(files_prompt_buf)) {
            files_prompt_buf[files_prompt_len] =
                initial[files_prompt_len];
            files_prompt_len++;
        }
    }
    files_prompt_buf[files_prompt_len] = '\0';
    desktop_redraw();
}

/* プロンプト確定: 対象ファイルは選択行から取る。 */
static void files_prompt_commit(void) {
    int mode = files_prompt;
    files_prompt = 0;
    char newname[28];
    size_t np = 0;
    while (files_prompt_buf[np] != '\0' && np + 1 < sizeof(newname)) {
        newname[np] = files_prompt_buf[np];
        np++;
    }
    newname[np] = '\0';
    if (!files_name_ok(newname)) {
        desktop_notify(L("Invalid name", "使えない名前です"));
        desktop_redraw();
        return;
    }
    char dst[40];
    files_join_path(dst, sizeof(dst), newname);
    if (mode == 3) {
        char marker[48];
        size_t mp = 0;
        while (dst[mp] != '\0' && mp + 1 < sizeof(marker)) {
            marker[mp] = dst[mp];
            mp++;
        }
        const char *sfx = "/.dir";
        size_t sq = 0;
        while (sfx[sq] != '\0' && mp + 1 < sizeof(marker)) {
            marker[mp++] = sfx[sq++];
        }
        marker[mp] = '\0';
        if (vfs_exists(marker) || vfs_exists(dst)) {
            desktop_notify(L("Already exists", "既にあります"));
        } else if (vfs_write(marker, "", 0) == 0) {
            serial_write("files: mkdir ");
            serial_write_line(dst);
            desktop_notify(L("Folder created", "フォルダを作成しました"));
            persist_maybe_sync();
        } else {
            desktop_notify(L("Could not create it", "作成できませんでした"));
        }
        desktop_redraw();
        return;
    }
    if (mode == 2) {
        if (vfs_exists(dst)) {
            desktop_notify(L("Already exists", "既にあります"));
        } else if (vfs_write(dst, "", 0) == 0) {
            serial_write("files: created ");
            serial_write_line(dst);
            desktop_notify(L("File created", "ファイルを作成しました"));
            persist_maybe_sync();
        } else {
            desktop_notify(L("Could not create it", "作成できませんでした"));
        }
        desktop_redraw();
        return;
    }
    /* 1=名前変更, 4=コピー: 選択行のファイルが対象。 */
    files_build_rows();
    if (files_selected < 0 || files_selected >= files_row_count ||
        files_rows[files_selected] < 0) {
        desktop_redraw();
        return;
    }
    const char *src = vfs_file_name(files_rows[files_selected]);
    char srcbuf[32];
    size_t sp = 0;
    while (src[sp] != '\0' && sp + 1 < sizeof(srcbuf)) {
        srcbuf[sp] = src[sp];
        sp++;
    }
    srcbuf[sp] = '\0';
    if (vfs_exists(dst)) {
        desktop_notify(L("Already exists", "既にあります"));
        desktop_redraw();
        return;
    }
    size_t len = 0;
    const char *content = vfs_read_ptr(srcbuf, &len);
    if (content == NULL || vfs_write(dst, content, len) != 0) {
        desktop_notify(L("Failed", "失敗しました"));
        desktop_redraw();
        return;
    }
    if (mode == 1) {
        (void)vfs_delete(srcbuf);
        serial_write("files: renamed ");
        serial_write(srcbuf);
        serial_write(" -> ");
        serial_write_line(dst);
        desktop_notify(L("Renamed", "名前を変更しました"));
    } else {
        serial_write("files: copied ");
        serial_write(srcbuf);
        serial_write(" -> ");
        serial_write_line(dst);
        desktop_notify(L("Copied", "コピーしました"));
    }
    persist_maybe_sync();
    desktop_redraw();
}

/* ゴミ箱から元の場所 (ルート) へ戻す。シェルの
 * trash restore と同じ VFS 操作。 */
static int files_trash_restore(const char *name) {
    char src[40];
    size_t p = 0;
    const char *pre = "trash/";
    while (pre[p] != '\0' && p + 1 < sizeof(src)) {
        src[p] = pre[p];
        p++;
    }
    size_t q = 0;
    while (name[q] != '\0' && p + 1 < sizeof(src)) {
        src[p++] = name[q++];
    }
    src[p] = '\0';
    if (!vfs_exists(src) || vfs_exists(name)) {
        return -1;
    }
    size_t len = 0;
    const char *content = vfs_read_ptr(src, &len);
    if (content == NULL || vfs_write(name, content, len) != 0) {
        return -1;
    }
    (void)vfs_delete(src);
    serial_write("files: restored ");
    serial_write_line(name);
    persist_maybe_sync();
    return 0;
}

static void files_trash_empty(void) {
    int count = vfs_file_count();
    char names[PRISM_VFS_MAX_FILES][32];
    int m = 0;
    for (int i = 0; i < count; i++) {
        const char *n = vfs_file_name(i);
        if (n[0] == 't' && n[1] == 'r' && n[2] == 'a' &&
            n[3] == 's' && n[4] == 'h' && n[5] == '/') {
            size_t q = 0;
            while (n[q] != '\0' && q + 1 < sizeof(names[m])) {
                names[m][q] = n[q];
                q++;
            }
            names[m][q] = '\0';
            m++;
        }
    }
    for (int i = 0; i < m; i++) {
        (void)vfs_delete(names[i]);
    }
    serial_write_line("files: trash emptied");
    persist_maybe_sync();
}

/* 選択中の行を開く (ディレクトリなら移動、
 * ファイルなら表示/実行)。キーとマウスで共用。 */
static void files_activate_row(void) {
    files_build_rows();
    if (files_selected < 0 || files_selected >= files_row_count) {
        return;
    }
    int row = files_rows[files_selected];
    if (row == -1) {
        /* 親へ */
        size_t n = 0;
        while (files_dir[n] != '\0') {
            n++;
        }
        while (n > 0 && files_dir[n - 1] != '/') {
            n--;
        }
        if (n > 0) {
            files_dir[n - 1] = '\0';
        } else {
            files_dir[0] = '\0';
        }
        files_selected = 0;
        desktop_refresh_console();
        return;
    }
    if (row <= -2) {
        const char *dn = files_dirnames[-2 - row];
        size_t p = 0;
        while (files_dir[p] != '\0') {
            p++;
        }
        if (p > 0 && p + 1 < sizeof(files_dir)) {
            files_dir[p++] = '/';
        }
        size_t q = 0;
        while (dn[q] != '\0' && p + 1 < sizeof(files_dir)) {
            files_dir[p++] = dn[q++];
        }
        files_dir[p] = '\0';
        files_selected = 0;
        serial_write("files: cd ");
        serial_write_line(files_dir);
        desktop_refresh_console();
        return;
    }
    const char *name = vfs_file_name(row);
    if (name != NULL && compat_is_app(name)) {
        char tmp[32];
        size_t p = 0;
        while (name[p] != '\0' && p + 1 < sizeof(tmp)) {
            tmp[p] = name[p];
            p++;
        }
        tmp[p] = '\0';
        int code = -1;
        if (compat_run_file(tmp, NULL, 0, &code) == 0) {
            serial_write("compat: ");
            serial_write(tmp);
            serial_write(" exited with code ");
            serial_write_num(code);
            serial_write_line(".");
        }
        switch_mode(DESK_TERMINAL);
        desktop_refresh_console();
        return;
    }
    files_viewing = row;
    desktop_refresh_console();
}

/* ---- C2: ファイルの見た目 (アイコン/パンくず/ツールバー/
 * 場所サイドバー/グリッド表示) ---- */
static int files_grid; /* 0 = 一覧, 1 = グリッド */

static uint64_t files_x(void) {
    return text_x() + 15 * CELL_W;
}

/* ファイル種別 (アイコン用)。 */
enum {
    FK_DIR, FK_TEXT, FK_IMAGE, FK_AUDIO, FK_VIDEO,
    FK_APP, FK_ARCHIVE, FK_PDF, FK_CODE, FK_OTHER
};

static int files_name_kind(const char *name) {
    size_t n = 0;
    while (name[n] != '\0') {
        n++;
    }
    const char *base = name;
    for (const char *p = name; *p != '\0'; p++) {
        if (*p == '/') {
            base = p + 1;
        }
    }
    size_t bn = 0;
    while (base[bn] != '\0') {
        bn++;
    }
    const char *ext = NULL;
    for (size_t i = 0; i < bn; i++) {
        if (base[i] == '.') {
            ext = base + i + 1;
        }
    }
    if (ext == NULL) {
        return FK_OTHER;
    }
    char e[6];
    size_t ei = 0;
    while (ext[ei] != '\0' && ei + 1 < sizeof(e)) {
        char ch = ext[ei];
        if (ch >= 'A' && ch <= 'Z') {
            ch = (char)(ch - 'A' + 'a');
        }
        e[ei] = ch;
        ei++;
    }
    e[ei] = '\0';
    if (!strcmp(e, "bmp") || !strcmp(e, "png") || !strcmp(e, "jpg")) {
        return FK_IMAGE;
    }
    if (!strcmp(e, "wav") || !strcmp(e, "mp3") || !strcmp(e, "mid")) {
        return FK_AUDIO;
    }
    if (!strcmp(e, "mp4") || !strcmp(e, "vid") || !strcmp(e, "avi")) {
        return FK_VIDEO;
    }
    if (!strcmp(e, "pdf")) {
        return FK_PDF;
    }
    if (!strcmp(e, "zip") || !strcmp(e, "tar") || !strcmp(e, "gz")) {
        return FK_ARCHIVE;
    }
    if (!strcmp(e, "elf") || !strcmp(e, "exe") || !strcmp(e, "app") ||
        !strcmp(e, "macho")) {
        return FK_APP;
    }
    if (!strcmp(e, "c") || !strcmp(e, "h") || !strcmp(e, "py") ||
        !strcmp(e, "sh")) {
        return FK_CODE;
    }
    return FK_TEXT;
}

/* s x s のファイルアイコンを描く (s は 16 か 32)。 */
static void draw_file_icon(uint64_t x, uint64_t y, int s, int kind) {
    int u = s / 16;
    if (u < 1) {
        u = 1;
    }
    uint32_t page = rgb(0xF2F4F8);
    uint32_t edge = rgb(0x8A94A6);
    if (kind == FK_DIR) {
        uint32_t body = rgb(0xF5C542);
        uint32_t dark = rgb(0xD9A62E);
        fb_fill_rect(x, y + (uint64_t)(3 * u), (uint64_t)(7 * u),
                     (uint64_t)(3 * u), dark);
        fb_fill_rect(x, y + (uint64_t)(5 * u), (uint64_t)s,
                     (uint64_t)(10 * u), body);
        fb_fill_rect(x, y + (uint64_t)(5 * u), (uint64_t)s,
                     (uint64_t)(2 * u), dark);
        return;
    }
    if (kind == FK_IMAGE) {
        fb_fill_rect(x, y, (uint64_t)s, (uint64_t)s, rgb(0xBFE3FF));
        fb_fill_rect(x, y, (uint64_t)s, (uint64_t)u, edge);
        fb_fill_rect(x, y + (uint64_t)(15 * u), (uint64_t)s,
                     (uint64_t)u, edge);
        fb_fill_rect(x + (uint64_t)(11 * u), y + (uint64_t)(3 * u),
                     (uint64_t)(3 * u), (uint64_t)(3 * u),
                     rgb(0xFFD94D));
        fb_fill_rect(x, y + (uint64_t)(10 * u), (uint64_t)(7 * u),
                     (uint64_t)(5 * u), rgb(0x3FA34D));
        fb_fill_rect(x + (uint64_t)(6 * u), y + (uint64_t)(8 * u),
                     (uint64_t)(10 * u), (uint64_t)(7 * u),
                     rgb(0x2E7D32));
        return;
    }
    /* 書類系は共通のページ形。 */
    fb_fill_rect(x + (uint64_t)(2 * u), y, (uint64_t)(12 * u),
                 (uint64_t)s, page);
    fb_fill_rect(x + (uint64_t)(2 * u), y, (uint64_t)(12 * u),
                 (uint64_t)u, edge);
    fb_fill_rect(x + (uint64_t)(2 * u), y + (uint64_t)(15 * u),
                 (uint64_t)(12 * u), (uint64_t)u, edge);
    if (kind == FK_AUDIO) {
        uint32_t c = rgb(0x7C5CFF);
        fb_fill_rect(x + (uint64_t)(9 * u), y + (uint64_t)(3 * u),
                     (uint64_t)(2 * u), (uint64_t)(8 * u), c);
        fb_fill_rect(x + (uint64_t)(9 * u), y + (uint64_t)(3 * u),
                     (uint64_t)(5 * u), (uint64_t)(2 * u), c);
        fb_fill_rect(x + (uint64_t)(6 * u), y + (uint64_t)(10 * u),
                     (uint64_t)(5 * u), (uint64_t)(4 * u), c);
        return;
    }
    if (kind == FK_VIDEO) {
        fb_fill_rect(x + (uint64_t)(2 * u), y, (uint64_t)(12 * u),
                     (uint64_t)s, rgb(0x263238));
        fb_fill_rect(x + (uint64_t)(6 * u), y + (uint64_t)(5 * u),
                     (uint64_t)(2 * u), (uint64_t)(6 * u),
                     rgb(0xFFFFFF));
        fb_fill_rect(x + (uint64_t)(8 * u), y + (uint64_t)(6 * u),
                     (uint64_t)(2 * u), (uint64_t)(4 * u),
                     rgb(0xFFFFFF));
        fb_fill_rect(x + (uint64_t)(10 * u), y + (uint64_t)(7 * u),
                     (uint64_t)u, (uint64_t)(2 * u), rgb(0xFFFFFF));
        return;
    }
    if (kind == FK_PDF) {
        fb_fill_rect(x + (uint64_t)(2 * u), y + (uint64_t)(2 * u),
                     (uint64_t)(12 * u), (uint64_t)(4 * u),
                     rgb(0xD43A2F));
        fb_fill_rect(x + (uint64_t)(4 * u), y + (uint64_t)(9 * u),
                     (uint64_t)(8 * u), (uint64_t)u, edge);
        fb_fill_rect(x + (uint64_t)(4 * u), y + (uint64_t)(12 * u),
                     (uint64_t)(8 * u), (uint64_t)u, edge);
        return;
    }
    if (kind == FK_APP) {
        fb_fill_rect(x + (uint64_t)(2 * u), y + (uint64_t)(2 * u),
                     (uint64_t)(12 * u), (uint64_t)(12 * u),
                     rgb(0x4CC2FF));
        fb_fill_rect(x + (uint64_t)(2 * u), y + (uint64_t)(2 * u),
                     (uint64_t)(12 * u), (uint64_t)(3 * u),
                     rgb(0x2B7CD3));
        fb_fill_rect(x + (uint64_t)(7 * u), y + (uint64_t)(8 * u),
                     (uint64_t)(3 * u), (uint64_t)(3 * u),
                     rgb(0xFFFFFF));
        return;
    }
    if (kind == FK_ARCHIVE) {
        fb_fill_rect(x + (uint64_t)(2 * u), y, (uint64_t)(12 * u),
                     (uint64_t)s, rgb(0xB08968));
        fb_fill_rect(x + (uint64_t)(7 * u), y, (uint64_t)(2 * u),
                     (uint64_t)s, rgb(0x6F4E37));
        fb_fill_rect(x + (uint64_t)(6 * u), y + (uint64_t)(3 * u),
                     (uint64_t)(4 * u), (uint64_t)(2 * u),
                     rgb(0xEDE0D4));
        fb_fill_rect(x + (uint64_t)(6 * u), y + (uint64_t)(8 * u),
                     (uint64_t)(4 * u), (uint64_t)(2 * u),
                     rgb(0xEDE0D4));
        return;
    }
    if (kind == FK_CODE) {
        uint32_t c = rgb(0x2E9E5B);
        fb_fill_rect(x + (uint64_t)(4 * u), y + (uint64_t)(5 * u),
                     (uint64_t)(2 * u), (uint64_t)(2 * u), c);
        fb_fill_rect(x + (uint64_t)(4 * u), y + (uint64_t)(9 * u),
                     (uint64_t)(2 * u), (uint64_t)(2 * u), c);
        fb_fill_rect(x + (uint64_t)(10 * u), y + (uint64_t)(5 * u),
                     (uint64_t)(2 * u), (uint64_t)(2 * u), c);
        fb_fill_rect(x + (uint64_t)(10 * u), y + (uint64_t)(9 * u),
                     (uint64_t)(2 * u), (uint64_t)(2 * u), c);
        return;
    }
    /* TEXT / OTHER: 罫線入りのページ。 */
    for (int r = 0; r < 3; r++) {
        fb_fill_rect(x + (uint64_t)(4 * u),
                     y + (uint64_t)((5 + r * 4) * u),
                     (uint64_t)(8 * u), (uint64_t)u, edge);
    }
}

/* 場所サイドバーの項目: [0]=ルート, [1]=ゴミ箱, 以降は
 * 最上位フォルダ。 */
static char files_places[10][28];
static int files_places_count;

static void files_places_build(void) {
    files_places_count = 0;
    const char *home = L("Home", "ホーム");
    size_t p = 0;
    while (home[p] != '\0' && p + 1 < sizeof(files_places[0])) {
        files_places[0][p] = home[p];
        p++;
    }
    files_places[0][p] = '\0';
    files_places_count = 1;
    const char *tr = "trash";
    p = 0;
    while (tr[p] != '\0' && p + 1 < sizeof(files_places[1])) {
        files_places[1][p] = tr[p];
        p++;
    }
    files_places[1][p] = '\0';
    files_places_count = 2;
    int count = vfs_file_count();
    for (int i = 0; i < count && files_places_count < 10; i++) {
        const char *n = vfs_file_name(i);
        const char *slash = NULL;
        for (const char *q = n; *q != '\0'; q++) {
            if (*q == '/') {
                slash = q;
                break;
            }
        }
        if (slash == NULL || slash == n) {
            continue;
        }
        size_t dl = (size_t)(slash - n);
        int dup = 0;
        for (int j = 1; j < files_places_count; j++) {
            if (strlen(files_places[j]) == dl &&
                strncmp(files_places[j], n, dl) == 0) {
                dup = 1;
            }
        }
        if (dup || dl + 1 >= sizeof(files_places[0])) {
            continue;
        }
        char *dst = files_places[files_places_count];
        for (size_t k = 0; k < dl; k++) {
            dst[k] = n[k];
        }
        dst[dl] = '\0';
        files_places_count++;
    }
}

/* 場所インデックスへ移動する。 */
static void files_goto_place(int idx) {
    if (idx == 0) {
        files_dir[0] = '\0';
    } else if (idx >= 1 && idx < files_places_count) {
        size_t p = 0;
        while (files_places[idx][p] != '\0' &&
               p + 1 < sizeof(files_dir)) {
            files_dir[p] = files_places[idx][p];
            p++;
        }
        files_dir[p] = '\0';
    } else {
        return;
    }
    files_selected = 0;
    files_viewing = -1;
    serial_write("files: cd ");
    serial_write_line(files_dir[0] != '\0' ? files_dir : "/");
    desktop_refresh_console();
}

/* パンくず: files_dir を区切った区間の数と開始位置。 */
static int files_crumb_count(void) {
    if (files_dir[0] == '\0') {
        return 1;
    }
    int n = 1;
    for (const char *p = files_dir; *p != '\0'; p++) {
        if (*p == '/') {
            n++;
        }
    }
    return n;
}

/* 区間 depth までのパスへ移動 (0 = ルート)。 */
static void files_goto_crumb(int depth) {
    if (depth <= 0) {
        files_dir[0] = '\0';
    } else {
        int seen = 0;
        size_t i = 0;
        while (files_dir[i] != '\0') {
            if (files_dir[i] == '/') {
                seen++;
                if (seen == depth) {
                    files_dir[i] = '\0';
                    break;
                }
            }
            i++;
        }
    }
    files_selected = 0;
    files_viewing = -1;
    desktop_refresh_console();
}

/* ツールバーのボタン矩形 (描画とクリックで共有)。 */
static int files_tool_x[8];
static int files_tool_w[8];
static int files_tool_n;

static void draw_files(void) {
    uint32_t fg = col_text();
    uint32_t bg = col_window_bg();
    uint32_t acc = col_accent();
    uint64_t x0 = text_x();
    uint64_t y0 = text_y();
    int count = vfs_file_count();
    if (files_viewing >= 0 && files_viewing < count) {
        const char *name = vfs_file_name(files_viewing);
        size_t len = 0;
        const char *content = vfs_read_ptr(name, &len);
        /* PDF はテキストを抽出して表示し、日本語の
         * 旧文字コード (SJIS/EUC/2022) は UTF-8 へ
         * 変換して表示する。 */
        static char view_buf[16384];
        if (content != NULL && len >= 5 &&
            name[0] != '\0') {
            size_t nl = 0;
            while (name[nl] != '\0') {
                nl++;
            }
            if (nl >= 4 && strcmp(name + nl - 4, ".pdf") == 0) {
                int n = pdf_extract_text((const uint8_t *)content,
                                         len, view_buf,
                                         sizeof(view_buf));
                if (n > 0) {
                    content = view_buf;
                    len = (size_t)n;
                }
            } else {
                charset_kind k = charset_detect(
                    (const uint8_t *)content, len);
                if (k == CHARSET_SJIS || k == CHARSET_EUCJP ||
                    k == CHARSET_ISO2022JP) {
                    size_t w = charset_to_utf8(
                        k, (const uint8_t *)content, len,
                        view_buf, sizeof(view_buf) - 1);
                    view_buf[w] = '\0';
                    content = view_buf;
                    len = w;
                }
            }
        }
        /* 長いファイル名で末尾が切れないよう 96 バイト (C7)。 */
        char header[96];
        size_t p = 0;
        const char *h = L("Viewing: ", "表示中: ");
        while (*h != '\0' && p + 1 < sizeof(header)) {
            header[p++] = *h++;
        }
        while (*name != '\0' && p + 1 < sizeof(header)) {
            header[p++] = *name++;
        }
        header[p] = '\0';
        draw_text_small(x0, y0, header, acc, bg);
        /* 本文 (AA): 折り返しは AA の実アドバンスで測る。 */
        {
            int px = aa_px_body();
            int wrap_w = (int)win_w() - 16;
            if (wrap_w < 40) {
                wrap_w = 40;
            }
            int row = 2;
            size_t pos = 0;
            int more = 0;
            while (pos < len) {
                if (row >= text_rows()) {
                    more = 1;
                    break;
                }
                size_t ls = pos;
                int x = 0;
                int has = 0;
                while (pos < len && content[pos] != '\n') {
                    uint32_t cp = 0;
                    int nb = jfont_utf8_decode(content + pos,
                                               len - pos, &cp);
                    if (nb <= 0) {
                        nb = 1;
                        cp = (uint8_t)content[pos];
                    }
                    int adv = aa_cp_advance(cp, px, 0);
                    if (x + adv > wrap_w && has) {
                        break;
                    }
                    x += adv;
                    has = 1;
                    pos += (size_t)nb;
                }
                if (pos > ls) {
                    draw_text_aa_range(x0,
                                       y0 + (uint64_t)(row * CELL_H),
                                       content + ls, pos - ls, fg,
                                       (int32_t)bg, px, 0);
                }
                if (pos < len && content[pos] == '\n') {
                    pos++;
                }
                row++;
            }
            if (more) {
                draw_text_aa_range(x0,
                                   y0 + (uint64_t)(row * CELL_H),
                                   "...", 3, col_dim(),
                                   (int32_t)bg, px, 0);
            }
        }
        draw_text_small(x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
                        L("Esc = back to list", "Esc = 一覧へ戻る"), col_dim(), bg);
        return;
    }
    files_build_rows();
    {
        /* パンくずアドレスバー (行0)。 */
        uint64_t cx = x0;
        draw_file_icon(cx, y0 + 2, 16, FK_DIR);
        cx += 22;
        int nseg = files_crumb_count();
        const char *seg = files_dir;
        for (int sgi = 0; sgi < nseg; sgi++) {
            char part[28];
            size_t pp = 0;
            if (sgi == 0) {
                const char *rt = L("Root", "ルート");
                while (rt[pp] != '\0' && pp + 1 < sizeof(part)) {
                    part[pp] = rt[pp];
                    pp++;
                }
            } else {
                while (seg[pp] != '\0' && seg[pp] != '/' &&
                       pp + 1 < sizeof(part)) {
                    part[pp] = seg[pp];
                    pp++;
                }
            }
            part[pp] = '\0';
            uint32_t sc = sgi == nseg - 1 ? fg : col_dim();
            draw_text_small(cx, y0, part, sc, bg);
            cx += fb_text_aa_width(part, aa_px_body(), 0);
            if (sgi + 1 < nseg) {
                draw_text_small(cx + 2, y0, ">", col_dim(), bg);
                cx += CELL_W + 4;
                /* 次の区間へ進む。 */
                while (*seg != '\0' && *seg != '/') {
                    seg++;
                }
                if (*seg == '/') {
                    seg++;
                }
            }
        }
        const char *srt = files_sort_mode == 1
            ? L("[by date]", "[日付順]")
            : files_sort_mode == 2
            ? L("[by size]", "[サイズ順]")
            : L("[by name]", "[名前順]");
        draw_text_small(x0 + win_w() - 16 -
                            fb_text_aa_width(srt, aa_px_body(), 0),
                        y0, srt, col_dim(), bg);
    }
    {
        /* ツールバー (行1): クリックできるボタン列。 */
        const char *labels[8];
        int n = 0;
        if (files_in_trash()) {
            labels[n++] = L("Restore", "復元");
            labels[n++] = L("Delete", "完全削除");
            labels[n++] = L("Empty", "空にする");
        } else {
            labels[n++] = L("New file", "新規ファイル");
            labels[n++] = L("New folder", "新規フォルダ");
            labels[n++] = L("Rename", "名前変更");
            labels[n++] = L("Copy", "コピー");
            labels[n++] = L("Trash", "ゴミ箱へ");
        }
        labels[n++] = L("Sort", "並び替え");
        labels[n++] = files_grid ? L("List view", "一覧表示")
                                 : L("Grid view", "グリッド表示");
        files_tool_n = n;
        uint64_t tx = x0;
        uint64_t ty = y0 + CELL_H + 2;
        for (int i = 0; i < n; i++) {
            uint64_t w = fb_text_aa_width(labels[i], aa_px_body(),
                                          0) + 16;
            files_tool_x[i] = (int)tx;
            files_tool_w[i] = (int)w;
            uint32_t face =
                ui_hover((int)tx, (int)ty, (int)w,
                         (int)CELL_H - 4)
                    ? col_hover()
                    : col_title_bg();
            fb_fill_round_rect((int64_t)tx, (int64_t)ty,
                               (int64_t)w, (int64_t)CELL_H - 4,
                               UI_R_CTL, face);
            fb_stroke_round_rect((int64_t)tx, (int64_t)ty,
                                 (int64_t)w, (int64_t)CELL_H - 4,
                                 UI_R_CTL, col_border());
            draw_text_small(tx + 8, ty, labels[i], fg, face);
            tx += w + 8;
        }
    }
    {
        /* 場所サイドバー (行2以降)。 */
        files_places_build();
        uint64_t sx = x0;
        uint64_t fx = files_x();
        fb_fill_rect(fx - 8, y0 + (uint64_t)(2 * CELL_H), 1,
                     (uint64_t)((text_rows() - 3) * CELL_H),
                     col_dim());
        for (int i = 0; i < files_places_count; i++) {
            uint64_t py = y0 + (uint64_t)(2 * CELL_H) +
                          (uint64_t)(i * FILES_ROW_H);
            int cur = (i == 0 && files_dir[0] == '\0') ||
                      (i >= 1 &&
                       strcmp(files_places[i], files_dir) == 0);
            if (cur) {
                fb_fill_rect(sx - 2, py, fx - sx - 12,
                             FILES_ROW_H, acc);
            } else if (ui_hover((int)sx - 2, (int)py,
                                (int)(fx - sx - 12),
                                FILES_ROW_H)) {
                fb_fill_rect(sx - 2, py, fx - sx - 12,
                             FILES_ROW_H, col_hover());
            }
            draw_file_icon(sx + 2,
                           py + (FILES_ROW_H - 16) / 2, 16,
                           i == 1 ? FK_ARCHIVE : FK_DIR);
            char pname[16];
            size_t pp2 = 0;
            while (files_places[i][pp2] != '\0' &&
                   pp2 + 1 < sizeof(pname)) {
                pname[pp2] = files_places[i][pp2];
                pp2++;
            }
            pname[pp2] = '\0';
            /* サイドバー幅 (11セル) に収まるよう切る。 */
            while (pp2 > 0 &&
                   fb_text_aa_width(pname, aa_px_body(), 0) >
                       11 * CELL_W) {
                /* UTF-8 の文字境界まで戻す。 */
                pp2--;
                while (pp2 > 0 &&
                       (pname[pp2] & 0xC0) == 0x80) {
                    pp2--;
                }
                pname[pp2] = '\0';
            }
            draw_text_small(sx + 24,
                            py + (FILES_ROW_H - CELL_H) / 2,
                            pname,
                            cur ? rgb(0xFFFFFF) : fg,
                            cur ? acc : bg);
        }
    }
    /* 一覧のスクロール位置を選択行に追随させる (B2)。 */
    int files_vis = (text_rows() - 3) * CELL_H / FILES_ROW_H;
    if (files_vis < 1) {
        files_vis = 1;
    }
    if (!files_grid) {
        if (files_top > files_row_count - files_vis) {
            files_top = files_row_count - files_vis;
        }
        if (files_top < 0) {
            files_top = 0;
        }
        if (files_selected < files_top) {
            files_top = files_selected;
        }
        if (files_selected >= files_top + files_vis) {
            files_top = files_selected - files_vis + 1;
        }
    }
    for (int vi = 0; !files_grid && vi < files_vis; vi++) {
        int i = files_top + vi;
        if (i >= files_row_count) {
            break;
        }
        int rowv = files_rows[i];
        const char *name;
        size_t len = 0;
        char dirbuf[36];
        if (rowv == -1) {
            name = "..";
        } else if (rowv <= -2) {
            size_t dp = 0;
            const char *dn = files_dirnames[-2 - rowv];
            while (*dn != '\0' && dp + 1 < sizeof(dirbuf)) {
                dirbuf[dp++] = *dn++;
            }
            if (dp + 1 < sizeof(dirbuf)) {
                dirbuf[dp++] = '/';
            }
            dirbuf[dp] = '\0';
            name = dirbuf;
        } else {
            name = vfs_file_name(rowv);
            (void)vfs_read_ptr(name, &len);
        }
        /* 名前とメタ情報 (サイズ・日付) は別々に組み立てる
         * (B2: 名前は左、メタは右寄せで列を揃える)。 */
        char nm[80];
        size_t np2 = 0;
        while (*name != '\0' && np2 + 1 < sizeof(nm)) {
            nm[np2++] = *name++;
        }
        nm[np2] = '\0';
        char line[48];
        size_t p = 0;
        if (rowv >= 0) {
            line[p++] = '(';
        char num[21];
        int ni = 0;
        size_t v = len;
        if (v == 0) {
            num[ni++] = '0';
        } else {
            char rev[21];
            int ri = 0;
            while (v > 0 && ri < 20) {
                rev[ri++] = (char)('0' + (v % 10));
                v /= 10;
            }
            while (ri > 0) {
                num[ni++] = rev[--ri];
            }
        }
        num[ni] = '\0';
        for (int k = 0; num[k] != '\0' && p + 1 < sizeof(line); k++) {
            line[p++] = num[k];
        }
        const char *tail = L(" bytes)", " バイト)");
        while (*tail != '\0' && p + 1 < sizeof(line)) {
            line[p++] = *tail++;
        }
        /* 更新日 (記録があるファイルのみ)。 */
        if (rowv >= 0) {
            uint32_t mt = vfs_file_mtime(rowv);
            if (mt > 0) {
                prism_rtc_time rt;
                rtc_from_unix(mt, desk_settings.tz_offset, &rt);
                int yr = 2000 + rt.year;
                if (p + 13 < sizeof(line)) {
                    line[p++] = ' ';
                    line[p++] = ' ';
                    line[p++] = (char)('0' + (yr / 1000) % 10);
                    line[p++] = (char)('0' + (yr / 100) % 10);
                    line[p++] = (char)('0' + (yr / 10) % 10);
                    line[p++] = (char)('0' + yr % 10);
                    line[p++] = '/';
                    line[p++] = (char)('0' + (rt.month / 10) % 10);
                    line[p++] = (char)('0' + rt.month % 10);
                    line[p++] = '/';
                    line[p++] = (char)('0' + (rt.day / 10) % 10);
                    line[p++] = (char)('0' + rt.day % 10);
                }
            }
        }
        line[p] = '\0';
        }
        uint64_t py = y0 + (uint64_t)(2 * CELL_H) +
                      (uint64_t)(vi * FILES_ROW_H);
        uint64_t fx = files_x();
        int kind = rowv < 0 ? FK_DIR
                            : files_name_kind(vfs_file_name(rowv));
        uint32_t face = bg;
        if (i == files_selected) {
            face = acc;
        } else if (ui_hover((int)fx - 4, (int)py,
                            (int)(win_x() + win_w() - 12 - fx + 4),
                            FILES_ROW_H)) {
            face = col_hover();
        }
        if (face != bg) {
            fb_fill_rect(fx - 4, py,
                         win_x() + win_w() - 12 - fx + 4,
                         FILES_ROW_H, face);
        }
        draw_file_icon(fx, py + (FILES_ROW_H - 16) / 2, 16,
                       kind);
        draw_text_small(fx + 22,
                        py + (FILES_ROW_H - CELL_H) / 2, nm,
                        i == files_selected ? rgb(0xFFFFFF) : fg,
                        face);
        if (line[0] != '\0') {
            uint64_t mw = fb_text_aa_width(line, aa_px_body(),
                                           0);
            draw_text_small(win_x() + win_w() - 12 - mw,
                            py + (FILES_ROW_H - CELL_H) / 2,
                            line,
                            i == files_selected ? rgb(0xFFFFFF)
                                                : col_dim(),
                            face);
        }
    }
    if (files_grid) {
        /* グリッド表示: アイコン+名前のタイル。BMP は
         * サムネイルを描く。 */
        uint64_t fx = files_x();
        uint64_t gy = y0 + (uint64_t)(2 * CELL_H);
        int cols = (int)((win_x() + win_w() - 12 - fx) / 108);
        if (cols < 1) {
            cols = 1;
        }
        int maxrows = (text_rows() - 3) * (int)CELL_H / 96;
        for (int i = 0; i < files_row_count &&
                        i < cols * maxrows; i++) {
            int rowv = files_rows[i];
            uint64_t tx = fx + (uint64_t)(i % cols) * 108;
            uint64_t ty = gy + (uint64_t)(i / cols) * 96;
            const char *name;
            char dirbuf[36];
            if (rowv == -1) {
                name = "..";
            } else if (rowv <= -2) {
                size_t dp = 0;
                const char *dn = files_dirnames[-2 - rowv];
                while (*dn != '\0' && dp + 1 < sizeof(dirbuf)) {
                    dirbuf[dp++] = *dn++;
                }
                dirbuf[dp] = '\0';
                name = dirbuf;
            } else {
                name = vfs_file_name(rowv);
                const char *bs = name;
                for (const char *q = name; *q != '\0'; q++) {
                    if (*q == '/') {
                        bs = q + 1;
                    }
                }
                name = bs;
            }
            if (i == files_selected) {
                fb_fill_rect(tx, ty, 100, 88, acc);
            } else if (ui_hover((int)tx, (int)ty, 100, 88)) {
                fb_fill_rect(tx, ty, 100, 88, col_hover());
            }
            int kind = rowv < 0 ? FK_DIR : files_name_kind(name);
            int thumb = 0;
            if (rowv >= 0 && kind == FK_IMAGE) {
                const char *full = vfs_file_name(rowv);
                size_t len = 0;
                const char *content = vfs_read_ptr(full, &len);
                wallpaper_img img;
                if (content != NULL &&
                    wallpaper_parse((const uint8_t *)content, len,
                                    &img) == 0) {
                    fb_draw_image_rgb24_rect(tx + 18, ty + 4, 64, 48,
                                             img.pixels, img.width,
                                             img.height, img.stride,
                                             img.top_down, 0, 0,
                                             img.width, img.height);
                    thumb = 1;
                }
            }
            if (!thumb) {
                draw_file_icon(tx + 34, ty + 8, 32, kind);
            }
            char nm[16];
            size_t np = 0;
            while (name[np] != '\0' && np + 1 < sizeof(nm)) {
                nm[np] = name[np];
                np++;
            }
            nm[np] = '\0';
            /* タイル幅に収まるよう切る (座標の負転防止)。 */
            while (np > 0 &&
                   fb_text_aa_width(nm, aa_px_body(), 0) > 96) {
                np--;
                while (np > 0 && (nm[np] & 0xC0) == 0x80) {
                    np--;
                }
                nm[np] = '\0';
            }
            uint64_t nw = fb_text_aa_width(nm, aa_px_body(), 0);
            draw_text_small(tx + (100 - nw) / 2, ty + 60, nm,
                            i == files_selected ? rgb(0xFFFFFF) : fg,
                            i == files_selected ? acc : bg);
        }
    }
    if (files_row_count == 0) {
        draw_text_small(files_x(), y0 + (uint64_t)(2 * CELL_H), L("(no files)", "(ファイルなし)"),
                        col_dim(), bg);
    }
    if (!files_grid && files_row_count > 0) {
        /* 表示範囲の指標 (B2): スクロール位置を示す。 */
        char cnt[40];
        size_t cp2 = 0;
        int range[3];
        range[0] = files_top + 1;
        range[1] = files_top + files_vis;
        if (range[1] > files_row_count) {
            range[1] = files_row_count;
        }
        range[2] = files_row_count;
        for (int q = 0; q < 3; q++) {
            char rev[12];
            int ri = 0;
            int v = range[q];
            if (v == 0) {
                rev[ri++] = '0';
            }
            while (v > 0 && ri < 11) {
                rev[ri++] = (char)('0' + v % 10);
                v /= 10;
            }
            while (ri > 0 && cp2 + 1 < sizeof(cnt)) {
                cnt[cp2++] = rev[--ri];
            }
            if (q == 0 && cp2 + 1 < sizeof(cnt)) {
                cnt[cp2++] = '-';
            }
            if (q == 1 && cp2 + 3 < sizeof(cnt)) {
                cnt[cp2++] = ' ';
                cnt[cp2++] = '/';
                cnt[cp2++] = ' ';
            }
        }
        cnt[cp2] = '\0';
        uint64_t cw2 = fb_text_aa_width(cnt, aa_px_body(), 0);
        draw_text_small(win_x() + win_w() - 12 - cw2,
                        y0 + (uint64_t)((text_rows() - 1) * CELL_H),
                        cnt, col_dim(), bg);
    }
    if (files_prompt) {
        const char *pl = files_prompt == 1
            ? L("Rename to: ", "新しい名前: ")
            : files_prompt == 2
            ? L("New file: ", "新規ファイル: ")
            : files_prompt == 3
            ? L("New folder: ", "新規フォルダ: ")
            : L("Copy to: ", "コピー先の名前: ");
        char pline[64];
        size_t pp = 0;
        while (*pl != '\0' && pp + 1 < sizeof(pline)) {
            pline[pp++] = *pl++;
        }
        size_t pq = 0;
        while (files_prompt_buf[pq] != '\0' && pp + 1 < sizeof(pline)) {
            pline[pp++] = files_prompt_buf[pq++];
        }
        if (pp + 1 < sizeof(pline)) {
            pline[pp++] = '_';
        }
        pline[pp] = '\0';
        draw_text_small(x0, y0 + (uint64_t)((text_rows() - 2) * CELL_H),
                        pline, acc, bg);
    }
    if (files_confirm) {
        draw_text_small(x0, y0 + (uint64_t)((text_rows() - 2) * CELL_H),
                        files_confirm == 1
                            ? L("Empty the trash? y = yes, n = no",
                                "ゴミ箱を空にしますか？ y = はい, n = いいえ")
                            : L("Delete permanently? y = yes, n = no",
                                "完全に削除しますか？ y = はい, n = いいえ"),
                        acc, bg);
    }
    draw_text_small(x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
                    L("Esc = back to Terminal", "Esc = ターミナルへ戻る"), col_dim(), bg);
}

