static uint32_t icon_color(char c, uint32_t bg) {
    switch (c) {
    case 'K': return rgb(0x202226);
    case 'W': return rgb(0xFFFFFF);
    case 'R': return rgb(0xE5484D);
    case 'G': return rgb(0x46A758);
    case 'B': return rgb(0x3E7BFA);
    case 'Y': return rgb(0xFFD60A);
    case 'y': return rgb(0xF5C518);
    case 'O': return rgb(0xF76B15);
    case 'P': return rgb(0x8E4EC6);
    case 'C': return rgb(0x12A594);
    case 'g': return rgb(0x8B8D98);
    case 'd': return rgb(0x44474E);
    case 'b': return rgb(0x8EC8F8);
    case 'e': return rgb(0xF1F5F9);
    default: return bg;
    }
}

/* Draw mode's icon at (x, y), scaled by `scale` (1 or 2).
 * `bg` fills the transparent ('.') cells. */
static void draw_app_icon(desktop_mode m, uint64_t x, uint64_t y,
                          int scale, uint32_t bg) {
    int idx = (int)m;
    if (idx < 0 || idx > ICON_MAX_INDEX) {
        idx = DESK_APP_COUNT;
    }
    for (int row = 0; row < 16; row++) {
        const char *line = APP_ICONS[idx][row];
        for (int col = 0; col < 16; col++) {
            uint32_t c = icon_color(line[col], bg);
            fb_fill_rect(x + (uint64_t)(col * scale),
                         y + (uint64_t)(row * scale),
                         (uint64_t)scale, (uint64_t)scale, c);
        }
    }
}

/* アイコンを任意のピクセル寸法で描く (T9: タスクバー
 * 24px のような整数倍でない寸法向け)。16x16 の原画を
 * 最近傍で拡縮する。 */
static void draw_app_icon_px(int idx, uint64_t x, uint64_t y, int px,
                             uint32_t bg) {
    if (idx < 0 || idx > ICON_MAX_INDEX) {
        idx = DESK_APP_COUNT;
    }
    if (px <= 0) {
        return;
    }
    for (int row = 0; row < px; row++) {
        const char *line = APP_ICONS[idx][row * 16 / px];
        uint32_t run_c = 0;
        int run_x = 0;
        int run_w = 0;
        for (int col = 0; col < px; col++) {
            uint32_t c = icon_color(line[col * 16 / px], bg);
            if (col > 0 && c == run_c) {
                run_w++;
            } else {
                if (col > 0) {
                    fb_fill_rect(x + (uint64_t)run_x,
                                 y + (uint64_t)row, (uint64_t)run_w,
                                 1, run_c);
                }
                run_c = c;
                run_x = col;
                run_w = 1;
            }
        }
        fb_fill_rect(x + (uint64_t)run_x, y + (uint64_t)row,
                     (uint64_t)run_w, 1, run_c);
    }
}

static void draw_dock(void) {
    uint64_t w = fb_width();
    uint32_t bg = col_dock();
    uint32_t fg = col_text();
    uint32_t acc = col_accent();
    const int bw = dock_btn_w();
    const int bh = dock_btn_h();
    const int gap = 4;
    int64_t start = 0;
    int64_t cross = 0;
    int count = dock_layout(&start, &cross);
    if (desk_settings.dock_pos == 1) {
        fb_fill_rect(0, 0, (uint64_t)(bw + 12), fb_height(), bg);
    } else {
        fb_fill_rect(0, dock_y(), w, (uint64_t)dock_strip_h(), bg);
    }
    for (int i = 0; i < count; i++) {
        int64_t bx = desk_settings.dock_pos == 1 ? cross
                                                 : start + i * (bw + gap);
        int64_t by = desk_settings.dock_pos == 1
                         ? start + i * (bh + gap)
                         : cross;
        desktop_mode app = desk_visible_mode(i);
        int active = (desk_mode == app);
        uint32_t fill = active ? acc : bg;
        uint32_t label = active ? rgb(0xFFFFFF) : fg;
        fb_fill_rect((uint64_t)bx, (uint64_t)by, (uint64_t)bw,
                     (uint64_t)bh, fill);
        if (!active) {
            for (int64_t px = bx; px < bx + bw; px++) {
                fb_put_pixel((uint64_t)px, (uint64_t)by, col_dim());
                fb_put_pixel((uint64_t)px, (uint64_t)(by + bh - 1),
                             col_dim());
            }
            for (int64_t py = by; py < by + bh; py++) {
                fb_put_pixel((uint64_t)bx, (uint64_t)py, col_dim());
                fb_put_pixel((uint64_t)(bx + bw - 1), (uint64_t)py,
                             col_dim());
            }
        }
        draw_app_icon(app, (uint64_t)(bx + 4),
                      (uint64_t)(by + (bh - 16) / 2), 1, fill);
        const char *name = mode_name(app);
        size_t len = strlen(name);
        int64_t tx = bx + 22 + (bw - 22 - (int64_t)(len * 6)) / 2;
        if (tx < bx + 22) {
            tx = bx + 22;
        }
        draw_text_small((uint64_t)tx, (uint64_t)(by + (bh - 8) / 2),
                        name, label, fill);
    }
}
/* ---- 横タスクバーのアイコン群 ----
 * スタートボタン (プリズムの三角マーク + PrismOS) と、
 * ピン留めしたコアアプリのアイコンボタンを一列に並べる。
 * ピン留めは少数に絞り、全アプリはスタートメニューから
 * 開く。ピン留めされていない起動中アプリは末尾に一時
 * 表示する。配置は設定 taskbar_center で中央寄せ
 * (既定) / 左寄せ。起動中アプリはボタン下端の下線で示す。 */
#define TB_BTN_MAX 40
#define TB_BTN_H 40
#define TB_GAP 4
#define TB_START_W 118

/* ピン留めするコアアプリ (この順で並ぶ)。 */
static const desktop_mode tb_pins[] = {
    DESK_FILES, DESK_BROWSER, DESK_SETTINGS, DESK_TERMINAL
};
#define TB_PINS ((int)(sizeof(tb_pins) / sizeof(tb_pins[0])))

static int tb_is_pinned(desktop_mode m) {
    for (int i = 0; i < TB_PINS; i++) {
        if (tb_pins[i] == m) {
            return 1;
        }
    }
    return 0;
}

/* ボタンの並び (描画とヒットテストで共有する対応表)。
 * tb_button_count が呼ばれるたびに作り直す。 */
static desktop_mode tb_map[TB_PINS + 1];
static int tb_map_count;

static void tb_build_map(void) {
    int c = 0;
    for (int i = 0; i < TB_PINS; i++) {
        if (!app_is_hidden(tb_pins[i])) {
            tb_map[c++] = tb_pins[i];
        }
    }
    if (!tb_is_pinned(desk_mode) && !app_is_hidden(desk_mode)) {
        tb_map[c++] = desk_mode;
    }
    tb_map_count = c;
}

/* タスクバーのボタン数: 表示できるピン留め + (ピン留め
 * されていない起動中アプリがあれば末尾に 1 つ)。 */
static int tb_button_count(void) {
    tb_build_map();
    return tb_map_count;
}

static desktop_mode tb_button_app(int idx) {
    /* 対応表は tb_button_count (tb_btn_w / tb_cluster_x)
     * が先に作り直している。 */
    return tb_map[idx];
}

static int tb_btn_w(void) {
    int count = tb_button_count();
    if (count <= 0) {
        return TB_BTN_MAX;
    }
    /* 右端のトレイ (ネットワークアイコン 40 + 間隔 8 +
     * 日付と時刻) に 152px を残す。 */
    int avail = (int)fb_width() - 8 - TB_START_W - TB_GAP - 152 -
                (count - 1) * TB_GAP;
    int w = avail / count;
    if (w > TB_BTN_MAX) {
        w = TB_BTN_MAX;
    }
    if (w < 24) {
        w = 24;
    }
    return w;
}

static int64_t tb_cluster_x(void) {
    int count = tb_button_count();
    int bw = tb_btn_w();
    int64_t total = TB_START_W + TB_GAP + (int64_t)count * bw +
                    (int64_t)(count - 1) * TB_GAP;
    if (desk_settings.taskbar_center) {
        int64_t x = ((int64_t)fb_width() - total) / 2;
        return x < 4 ? 4 : x;
    }
    return 8;
}

static int64_t tb_app_x(int i) {
    return tb_cluster_x() + TB_START_W + TB_GAP +
           (int64_t)i * (tb_btn_w() + TB_GAP);
}

/* 横タスクバーのヒットテスト: -2 = スタートボタン、
 * -1 = なし、0 以上 = アプリの並び順インデックス。 */
static int taskbar_app_at(int x, int y) {
    uint64_t ty = taskbar_y();
    if (y < (int)ty + 4 || y >= (int)ty + 4 + TB_BTN_H) {
        return -1;
    }
    int64_t sx = tb_cluster_x();
    if (x >= sx && x < sx + TB_START_W) {
        return -2;
    }
    int bw = tb_btn_w();
    int count = tb_button_count();
    for (int i = 0; i < count; i++) {
        int64_t bx = tb_app_x(i);
        if (x >= bx && x < bx + bw) {
            return i;
        }
    }
    return -1;
}

/* トレイのネットワークアイコンの左端 x。時計ブロック
 * (実測幅) の左に 40px のボタンを置く。 */
static int net_icon_x(void) {
    int px = aa_px_body();
    uint64_t tw = fb_text_aa_width(clock_text, px, 0);
    if (text_scale_now() < 2) {
        uint64_t dw = fb_text_aa_width(date_text, px, 0);
        if (dw > tw) {
            tw = dw;
        }
    }
    return (int)fb_width() - 12 - (int)tw - 8 - 40;
}

/* 信号強度のバー (4 本、下端揃え)。lit 本を on 色で、
 * 残りを off 色で描く。 */
static void draw_signal_bars(int x, int y, int lit, uint32_t on_c,
                             uint32_t off_c) {
    static const int hs[4] = {5, 9, 13, 17};
    for (int i = 0; i < 4; i++) {
        fb_fill_rect((uint64_t)(x + i * 6),
                     (uint64_t)(y + (17 - hs[i])), 4,
                     (uint64_t)hs[i], i < lit ? on_c : off_c);
    }
}

static int wifi_signal_lit(void) {
    int s = wifi_current_signal();
    if (s >= 75) {
        return 4;
    }
    if (s >= 50) {
        return 3;
    }
    if (s >= 25) {
        return 2;
    }
    if (s > 0) {
        return 1;
    }
    return 0;
}

static void draw_taskbar(void) {
    if (taskbar_vertical()) {
        uint64_t h = fb_height();
        uint64_t x = desk_settings.taskbar_side == 1
                         ? 0
                         : fb_width() - TASKBAR_W;
        uint32_t bgv = col_taskbar();
        uint32_t fgv = col_text();
        uint32_t accv = col_accent();
        fb_fill_rect_alpha(x, 0, TASKBAR_W, h, bgv, 232);
        fb_fill_rect(desk_settings.taskbar_side == 1
                         ? TASKBAR_W - 2
                         : x,
                     0, 2, h, accv);
        draw_text_small(x + 10, 16, "PrismOS", accv, bgv);
        fb_fill_rect(x + 10, 40, TASKBAR_W - 20, 24,
                     launcher_active ? accv : bgv);
        draw_text_small(x + 22, 48, L("Apps", "アプリ"),
                        launcher_active ? rgb(0xFFFFFF) : fgv,
                        launcher_active ? accv : bgv);
        const char *mode = mode_name(desk_mode);
        draw_app_icon(desk_mode, x + 10, 84, 1, bgv);
        draw_text_small(x + 32, 88, mode, fgv, bgv);
        draw_text_small(x + 10, h - 40, date_text, fgv, bgv);
        draw_text_small(x + 10, h - 24, clock_text, fgv, bgv);
        return;
    }
    uint64_t w = fb_width();
    uint64_t y = taskbar_y();
    uint32_t bg = col_taskbar();
    uint32_t fg = col_text();
    uint32_t acc = col_accent();
    /* バーは半透明 (素材感): 下の壁紙/ウィンドウが
     * ほんのり透ける。 */
    fb_fill_rect_alpha(0, y, w, TASKBAR_H, bg, 232);
    fb_fill_rect(0, y, w, 2, acc);
    /* スタートボタン: プリズムの三角マーク + PrismOS。
     * ランチャー (スタートメニュー) を開閉する。 */
    {
        int64_t sx = tb_cluster_x();
        uint32_t sfill = launcher_active ? acc : bg;
        uint32_t smark = launcher_active ? rgb(0xFFFFFF) : acc;
        uint32_t stext = launcher_active ? rgb(0xFFFFFF) : fg;
        fb_fill_round_rect(sx, (int64_t)(y + 4), TB_START_W,
                           TB_BTN_H, UI_R_CTL, sfill);
        int64_t cx = sx + 17;
        int64_t cy = (int64_t)y + TASKBAR_H / 2;
        fb_draw_line(cx, cy - 9, cx - 8, cy + 7, smark);
        fb_draw_line(cx - 8, cy + 7, cx + 8, cy + 7, smark);
        fb_draw_line(cx + 8, cy + 7, cx, cy - 9, smark);
        draw_text_small((uint64_t)(sx + 32), y + 20, "PrismOS",
                        stext, sfill);
    }
    /* ピン留め + 起動中アプリのアイコンボタン。 */
    {
        int bw = tb_btn_w();
        int count = tb_button_count();
        for (int i = 0; i < count; i++) {
            desktop_mode app = tb_button_app(i);
            int64_t bx = tb_app_x(i);
            int active = (desk_mode == app);
            uint32_t fill = active ? col_window_bg() : bg;
            fb_fill_round_rect(bx, (int64_t)(y + 4), bw, TB_BTN_H,
                               UI_R_CTL, fill);
            /* アイコンは 24px (T9)。ボタンが狭いときは
             * 16px に落とす。 */
            int ipix = bw >= 28 ? 24 : 16;
            draw_app_icon_px((int)app,
                             (uint64_t)(bx + (bw - ipix) / 2),
                             y + (uint64_t)((TASKBAR_H - ipix) / 2),
                             ipix, fill);
            if (active) {
                fb_fill_rect((uint64_t)(bx + (bw - 20) / 2),
                             y + TASKBAR_H - 3, 20, 3, acc);
            }
        }
    }
    /* トレイのネットワークアイコン: クリックで
     * クイックパネルを開く。状態はバーの本数と色で
     * 表し、オフ/ハードウェアなしは斜線を重ねる。 */
    {
        int ix = net_icon_x();
        int iy = (int)y + 4;
        wifi_ui_ensure();
        int hov = ui_hover(ix, iy, 40, TB_BTN_H);
        if (net_panel_open) {
            fb_fill_round_rect((int64_t)ix, (int64_t)iy, 40, TB_BTN_H,
                               UI_R_CTL, col_window_bg());
        } else if (hov) {
            fb_fill_round_rect((int64_t)ix, (int64_t)iy, 40, TB_BTN_H,
                               UI_R_CTL, col_hover());
        }
        wifi_state st = wifi_get_state();
        int unavail = st == WIFI_ST_NO_HW || st == WIFI_ST_OFF;
        int lit = st == WIFI_ST_CONNECTED ? wifi_signal_lit() : 0;
        draw_signal_bars(ix + 9, iy + 11, lit,
                         st == WIFI_ST_CONNECTED ? acc : fg,
                         col_dim());
        if (unavail) {
            fb_draw_line((int64_t)(ix + 9), (int64_t)(iy + 28),
                         (int64_t)(ix + 31), (int64_t)(iy + 12), acc);
        }
    }
    /* トレイ (右端): 時刻と日付を 2 行で右寄せ表示。
     * 幅は実メトリクスで測る (B1)。 */
    {
        if (text_scale_now() >= 2) {
            /* 大 / 特大: 48px のバーに 2 行は入らないので
             * 時刻だけを大きく出す (日付はツールチップと
             * ロック画面・時計アプリで見られる) (E3)。 */
            int px = aa_px_body();
            uint64_t cw = fb_text_aa_width(clock_text, px, 0);
            fb_draw_text_aa((int64_t)(w - 12 - cw),
                            (int64_t)(y + 8) + px * 13 / 16,
                            clock_text, fg, (int32_t)bg, px, 0);
        } else {
            int px = aa_px_body();
            uint64_t cw = fb_text_aa_width(clock_text, px, 0);
            uint64_t dw = fb_text_aa_width(date_text, px, 0);
            fb_draw_text_aa((int64_t)(w - 12 - cw),
                            (int64_t)(y + 4) + px * 13 / 16,
                            clock_text, fg, (int32_t)bg, px, 0);
            fb_draw_text_aa((int64_t)(w - 12 - dw),
                            (int64_t)(y + 25) + px * 13 / 16,
                            date_text, fg, (int32_t)bg, px, 0);
        }
    }
}

/* The mouse cursor: a small arrow, white with a black shadow
 * so it stays visible on light and dark backgrounds. */
static const char *CURSOR_SHAPE[16] = {
    "X           ",
    "XX          ",
    "XXX         ",
    "XXXX        ",
    "XXXXX       ",
    "XXXXXX      ",
    "XXXXXXX     ",
    "XXXXXXXX    ",
    "XXXXXXXXX   ",
    "XXXXXX      ",
    "XXXX XX     ",
    "XXX   XX    ",
    "XX     XX   ",
    "X       XX  ",
    "         XX ",
    "            ",
};

static void draw_cursor(void) {
    uint32_t white = rgb(0xFFFFFF);
    uint32_t black = rgb(0x000000);
    /* Shadow first (offset by one pixel), then the arrow. */
    for (int pass = 0; pass < 2; pass++) {
        uint32_t colour = pass == 0 ? black : white;
        int ox = pass == 0 ? 1 : 0;
        int oy = pass == 0 ? 1 : 0;
        for (int row = 0; row < 16; row++) {
            for (int col = 0; col < 12; col++) {
                if (CURSOR_SHAPE[row][col] == 'X') {
                    fb_put_pixel((uint64_t)(mouse_x + col + ox),
                                 (uint64_t)(mouse_y + row + oy), colour);
                }
            }
        }
    }
}

/* ================= ネットワークのクイックパネル =====
 * トレイのアイコンから開くフライアウト。Wi-Fi の
 * トグルとネットワーク一覧、その場での接続/切断、
 * 有線の状態、設定への導線を 1 枚に集約する
 * (「簡単に繋げる」の本命)。縦タスクバーでは出さない
 * (設定ページは使える)。 */
#define NETP_W 360
#define NETP_ROW_H 40
#define NETP_MAX_HITS 24
enum {
    NETP_TOGGLE = 1,
    NETP_SCAN,
    NETP_SAVED,
    NETP_OTHER,
    NETP_DISCONN,
    NETP_SETTINGS
};
static int netp_x, netp_y, netp_w, netp_h;
static int netp_kinds[NETP_MAX_HITS];
static int netp_idxs[NETP_MAX_HITS];
static int netp_ys[NETP_MAX_HITS];
static int netp_hs[NETP_MAX_HITS];
static int netp_count;

static void netp_push(int kind, int idx, int y, int h) {
    if (netp_count < NETP_MAX_HITS) {
        netp_kinds[netp_count] = kind;
        netp_idxs[netp_count] = idx;
        netp_ys[netp_count] = y;
        netp_hs[netp_count] = h;
        netp_count++;
    }
}

static void net_panel_close_on_start(void) { net_panel_open = 0; }

static void draw_net_panel(void) {
    if (!net_panel_open || taskbar_vertical()) {
        return;
    }
    wifi_ui_ensure();
    uint32_t bg = col_taskbar();
    uint32_t fg = col_text();
    uint32_t dim = col_dim();
    uint32_t acc = col_accent();
    int has_hw = wifi_hw_present();
    int on = wifi_get_enabled();
    int connected = wifi_get_state() == WIFI_ST_CONNECTED;
    int nscan = (has_hw && on) ? wifi_scan_count() : 0;
    if (nscan > 8) {
        nscan = 8;
    }
    /* スキャン結果と重ならない保存済みだけを抜粋表示。 */
    int saved_shown[4];
    int nsaved = 0;
    for (int i = 0; i < wifi_saved_count() && nsaved < 4; i++) {
        const wifi_saved *sv = wifi_saved_at(i);
        int dup = 0;
        for (int j = 0; j < nscan; j++) {
            const wifi_net *wn = wifi_scan_at(j);
            if (wn != NULL && strcmp(wn->ssid, sv->ssid) == 0) {
                dup = 1;
                break;
            }
        }
        if (!dup) {
            saved_shown[nsaved++] = i;
        }
    }
    int state_line = (!has_hw || !on) ? 30 : 0;
    int empty_line = (has_hw && on && nscan == 0 && !connected) ? 30 : 0;
    /* 14 余白 + 見出し 26 + 状態 26 + メッセージ 26 +
     * 有線 26 + 区切り 10 + 状態行 + 空行 + 一覧 +
     * その他 40 + 区切り 10 + 設定 40 + 下余白 12。 */
    int h = 14 + 26 + 26 + 26 + 26 + 10 + state_line + empty_line +
            nscan * NETP_ROW_H + (connected ? NETP_ROW_H : 0) +
            nsaved * NETP_ROW_H + NETP_ROW_H + 10 + NETP_ROW_H + 12;
    if (wifi_ui_msg[0] == '\0') {
        h -= 26;
    }
    int pw = NETP_W;
    int px = (int)fb_width() - pw - 8;
    int py = desk_settings.taskbar_top
                 ? TASKBAR_H + 8
                 : (int)taskbar_y() - h - 8;
    if (py < 4) {
        py = 4;
    }
    netp_x = px;
    netp_y = py;
    netp_w = pw;
    netp_h = h;
    netp_count = 0;
    fb_shadow_round_rect((int64_t)px, (int64_t)py, (int64_t)pw,
                         (int64_t)h, UI_R_WIN, 4);
    fb_fill_round_rect_alpha((int64_t)px, (int64_t)py, (int64_t)pw,
                             (int64_t)h, UI_R_WIN, bg, 238);
    fb_stroke_round_rect((int64_t)px, (int64_t)py, (int64_t)pw,
                         (int64_t)h, UI_R_WIN, col_border());
    int cx = px + 16;
    int cw = pw - 32;
    int cy = py + 14;
    /* 見出し + Wi-Fi トグル。 */
    draw_text_small((uint64_t)cx, (uint64_t)cy,
                    L("Network", "ネットワーク"), acc, (int32_t)bg);
    draw_toggle_pill((uint64_t)(px + pw - 16 - UI_TOGGLE_W),
                     (uint64_t)cy, on);
    netp_push(NETP_TOGGLE, 0, cy - 4, 28);
    cy += 26;
    draw_text_small((uint64_t)cx, (uint64_t)cy, wifi_state_text(), dim,
                    (int32_t)bg);
    cy += 26;
    if (wifi_ui_msg[0] != '\0') {
        char clip[128];
        wifi_clip_text(clip, sizeof(clip), wifi_ui_msg, cw);
        draw_text_small((uint64_t)cx, (uint64_t)cy, clip, acc,
                        (int32_t)bg);
        cy += 26;
    }
    /* 有線の状態。 */
    {
        char cur[96];
        net_status(cur, sizeof(cur));
        char line[128];
        size_t p = 0;
        line[0] = '\0';
        buf_cat(line, sizeof(line), &p, L("Wired: ", "有線: "));
        if (strcmp(cur, "ip=0.0.0.0") == 0 ||
            (cur[0] == 'i' && cur[1] == 'p' && cur[2] == '=' &&
             cur[3] == '0' && cur[4] == '.' && cur[5] == '0' &&
             cur[6] == '.' && cur[7] == '0' && cur[8] == '.' &&
             cur[9] == '0' &&
             (cur[10] == ' ' || cur[10] == '\0'))) {
            buf_cat(line, sizeof(line), &p,
                    L("not connected", "未接続"));
        } else {
            buf_cat(line, sizeof(line), &p, cur);
        }
        char clip[128];
        wifi_clip_text(clip, sizeof(clip), line, cw);
        draw_text_small((uint64_t)cx, (uint64_t)cy, clip, dim,
                        (int32_t)bg);
        cy += 26;
    }
    fb_fill_rect((uint64_t)cx, (uint64_t)(cy + 4), (uint64_t)cw, 1,
                 col_border());
    cy += 10;
    if (state_line > 0) {
        draw_text_small((uint64_t)cx, (uint64_t)cy,
                        !has_hw ? L("No Wi-Fi hardware found",
                                    "Wi-Fi ハードウェアが見つかりません")
                                : L("Wi-Fi is off", "Wi-Fi はオフです"),
                        dim, (int32_t)bg);
        cy += state_line;
    }
    if (empty_line > 0) {
        draw_text_small((uint64_t)cx, (uint64_t)cy,
                        L("No networks found", "ネットワークが見つかりません"),
                        dim, (int32_t)bg);
        cy += empty_line;
    }
    /* スキャン結果。 */
    for (int i = 0; i < nscan; i++) {
        const wifi_net *wn = wifi_scan_at(i);
        int hov = ui_hover(px + 8, cy, pw - 16, NETP_ROW_H);
        if (hov) {
            fb_fill_round_rect((int64_t)(px + 8), (int64_t)cy,
                               (int64_t)(pw - 16), NETP_ROW_H, UI_R_CTL,
                               col_hover());
        }
        int lit = 0;
        if (wn->signal >= 75) {
            lit = 4;
        } else if (wn->signal >= 50) {
            lit = 3;
        } else if (wn->signal >= 25) {
            lit = 2;
        } else if (wn->signal > 0) {
            lit = 1;
        }
        draw_signal_bars(cx + 2, cy + 11, lit, fg, dim);
        int is_cur = connected &&
                     strcmp(wifi_current_ssid(), wn->ssid) == 0;
        char clip[40];
        wifi_clip_text(clip, sizeof(clip), wn->ssid, cw - 130);
        draw_text_small((uint64_t)(cx + 34), (uint64_t)(cy + 10), clip,
                        fg, (int32_t)bg);
        if (is_cur) {
            const char *t = L("Connected", "接続済み");
            draw_text_small(
                (uint64_t)(px + pw - 16 - set_text_w(t)),
                (uint64_t)(cy + 10), t, acc, (int32_t)bg);
        } else if (wifi_saved_find(wn->ssid) >= 0) {
            const char *t = L("Saved", "保存済み");
            draw_text_small(
                (uint64_t)(px + pw - 16 - set_text_w(t)),
                (uint64_t)(cy + 10), t, dim, (int32_t)bg);
        } else if (wn->secured) {
            /* 鍵マーク (南京錠を矩形で描く)。 */
            int kx = px + pw - 16 - 12;
            int ky = cy + 12;
            fb_stroke_round_rect((int64_t)(kx + 2), (int64_t)ky, 8, 8,
                                 3, dim);
            fb_fill_round_rect((int64_t)kx, (int64_t)(ky + 6), 12, 9,
                               2, dim);
        }
        netp_push(NETP_SCAN, i, cy, NETP_ROW_H);
        cy += NETP_ROW_H;
    }
    if (connected) {
        int hov = ui_hover(px + 8, cy, pw - 16, NETP_ROW_H);
        if (hov) {
            fb_fill_round_rect((int64_t)(px + 8), (int64_t)cy,
                               (int64_t)(pw - 16), NETP_ROW_H, UI_R_CTL,
                               col_hover());
        }
        draw_text_small((uint64_t)(cx + 34), (uint64_t)(cy + 10),
                        L("Disconnect", "切断"), acc, (int32_t)bg);
        netp_push(NETP_DISCONN, 0, cy, NETP_ROW_H);
        cy += NETP_ROW_H;
    }
    /* 保存済み (スキャン結果と重ならない分)。 */
    for (int i = 0; i < nsaved; i++) {
        const wifi_saved *sv = wifi_saved_at(saved_shown[i]);
        int hov = ui_hover(px + 8, cy, pw - 16, NETP_ROW_H);
        if (hov) {
            fb_fill_round_rect((int64_t)(px + 8), (int64_t)cy,
                               (int64_t)(pw - 16), NETP_ROW_H, UI_R_CTL,
                               col_hover());
        }
        int is_cur = connected &&
                     strcmp(wifi_current_ssid(), sv->ssid) == 0;
        char clip[40];
        wifi_clip_text(clip, sizeof(clip), sv->ssid, cw - 130);
        draw_text_small((uint64_t)(cx + 34), (uint64_t)(cy + 10), clip,
                        fg, (int32_t)bg);
        const char *t = is_cur ? L("Connected", "接続済み")
                               : L("Saved", "保存済み");
        draw_text_small((uint64_t)(px + pw - 16 - set_text_w(t)),
                        (uint64_t)(cy + 10), t, is_cur ? acc : dim,
                        (int32_t)bg);
        netp_push(NETP_SAVED, saved_shown[i], cy, NETP_ROW_H);
        cy += NETP_ROW_H;
    }
    /* その他のネットワーク。 */
    {
        int hov = ui_hover(px + 8, cy, pw - 16, NETP_ROW_H);
        if (hov) {
            fb_fill_round_rect((int64_t)(px + 8), (int64_t)cy,
                               (int64_t)(pw - 16), NETP_ROW_H, UI_R_CTL,
                               col_hover());
        }
        draw_text_small((uint64_t)(cx + 34), (uint64_t)(cy + 10),
                        L("Other network...", "その他のネットワーク..."),
                        fg, (int32_t)bg);
        netp_push(NETP_OTHER, 0, cy, NETP_ROW_H);
        cy += NETP_ROW_H;
    }
    fb_fill_rect((uint64_t)cx, (uint64_t)(cy + 4), (uint64_t)cw, 1,
                 col_border());
    cy += 10;
    /* 設定への導線。 */
    {
        int hov = ui_hover(px + 8, cy, pw - 16, NETP_ROW_H);
        if (hov) {
            fb_fill_round_rect((int64_t)(px + 8), (int64_t)cy,
                               (int64_t)(pw - 16), NETP_ROW_H, UI_R_CTL,
                               col_hover());
        }
        draw_text_small((uint64_t)cx, (uint64_t)(cy + 10),
                        L("Open network settings",
                          "ネットワーク設定を開く"),
                        fg, (int32_t)bg);
        netp_push(NETP_SETTINGS, 0, cy, NETP_ROW_H);
        cy += NETP_ROW_H;
    }
}

static void net_panel_act(int kind, int idx) {
    switch (kind) {
    case NETP_TOGGLE:
        wifi_ui_toggle();
        break;
    case NETP_SCAN: {
        const wifi_net *n = wifi_scan_at(idx);
        if (n != NULL) {
            wifi_ui_connect_net(n, 1);
            if (wifi_dlg_is_open()) {
                net_panel_open = 0;
            }
        }
        break;
    }
    case NETP_SAVED:
        wifi_ui_connect_saved_idx(idx, 1);
        if (wifi_dlg_is_open()) {
            net_panel_open = 0;
        }
        break;
    case NETP_OTHER:
        net_panel_open = 0;
        wifi_dlg_begin(NULL, 1);
        break;
    case NETP_DISCONN:
        wifi_disconnect();
        serial_write_line("wifi: disconnected");
        wifi_ui_report("Disconnected", "切断しました");
        wifi_ui_save();
        desktop_redraw();
        break;
    case NETP_SETTINGS:
        net_panel_open = 0;
        serial_write_line("wifi: open network settings");
        settings_page = 6;
        switch_mode(DESK_SETTINGS);
        net_refresh();
        break;
    default:
        break;
    }
}

/* パネル内のクリック。パネル外なら 0 (呼び出し側が
 * 閉じる処理をする)。 */
static int net_panel_click(int x, int y) {
    if (!net_panel_open) {
        return 0;
    }
    if (x < netp_x || x >= netp_x + netp_w || y < netp_y ||
        y >= netp_y + netp_h) {
        return 0;
    }
    for (int i = 0; i < netp_count; i++) {
        if (y >= netp_ys[i] && y < netp_ys[i] + netp_hs[i] &&
            x >= netp_x + 8 && x < netp_x + netp_w - 8) {
            net_panel_act(netp_kinds[i], netp_idxs[i]);
            return 1;
        }
    }
    return 1;
}

static void net_panel_toggle(void) {
    if (net_panel_open) {
        net_panel_open = 0;
        serial_write_line("wifi: quick panel closed");
    } else {
        wifi_ui_ensure();
        if (wifi_hw_present() && wifi_get_enabled()) {
            wifi_scan();
        }
        net_panel_open = 1;
        launcher_active = 0;
        launcher_closing = 0;
        menu_active = 0;
        serial_write_line("wifi: quick panel opened");
    }
    desktop_redraw();
}

static void switch_mode(desktop_mode m);

/* ================= Notifications ================= */

/* ---- アクセシビリティ: ナレーターと画面キーボード ---- */

/* ナレーター (読み上げの基礎): 有効な間、通知を
 * キャプションとして画面下部に表示し、シリアルにも
 * "narrator: ..." で記録する。音声合成エンジンは無い
 * ため、読み上げの基礎は文字キャプションとログで
 * 実装する (合成そのものは未実装)。 */
static char narrator_caption[160];

static void narrator_say(const char *text) {
    if (!desk_settings.narrator || text == NULL) {
        return;
    }
    size_t i = 0;
    while (text[i] != '\0' && i + 1 < sizeof(narrator_caption)) {
        narrator_caption[i] = text[i];
        i++;
    }
    narrator_caption[i] = '\0';
    serial_write("narrator: ");
    serial_write_line(narrator_caption);
}

/* 画面キーボード (OSK): 有効な間、画面下部にキーの
 * パネルを出す。クリックしたキーは物理キーボードと
 * 同じ desktop_handle_key へ入る。 */
#define OSK_KEY_H 36
#define OSK_GAP 4
#define OSK_ROWS 5
static const char *const OSK_ROW_KEYS[4] = {
    "1234567890", "qwertyuiop", "asdfghjkl", "zxcvbnm,."
};
typedef struct {
    const char *label;
    int code;
    int units;
} osk_ctl_key;
static const osk_ctl_key OSK_CTL[6] = {
    {"Esc", 0x1B, 2},   {"Bksp", '\b', 3}, {"Space", ' ', 6},
    {"Enter", '\n', 3}, {"Up", DESK_KEY_UP, 2},
    {"Down", DESK_KEY_DOWN, 2},
};
#define OSK_CTL_UNITS 18

static int osk_panel_h(void) {
    return OSK_ROWS * (OSK_KEY_H + OSK_GAP) + OSK_GAP;
}

static int osk_reserved_h(void) {
    return desk_settings.osk ? osk_panel_h() : 0;
}

static uint64_t osk_panel_y(void) {
    uint64_t ty = taskbar_y();
    int h = osk_panel_h();
    return ty > (uint64_t)h ? ty - (uint64_t)h : 0;
}

static int osk_row_key_w(int n) {
    return (int)((fb_width() - 16 - (uint64_t)(OSK_GAP * (n + 1))) /
                 (uint64_t)n);
}

static void osk_draw_key(uint64_t kx, uint64_t ky, uint64_t kw,
                         const char *label) {
    fb_fill_rect(kx, ky, kw, OSK_KEY_H, rgb(0x3A3A44));
    /* ラベルはキーの中央に置く (E2)。計測も描画も AA。 */
    uint64_t lw = fb_text_aa_width(label, aa_px_body(), 0);
    uint64_t lx = kx + (kw > lw ? (kw - lw) / 2 : 0);
    uint64_t ly = ky + (OSK_KEY_H - CELL_H) / 2;
    draw_text_small(lx, ly, label, rgb(0xFFFFFF), rgb(0x3A3A44));
}

static void draw_osk(void) {
    if (!desk_settings.osk) {
        return;
    }
    uint64_t py = osk_panel_y();
    fb_fill_rect(0, py, fb_width(), (uint64_t)osk_panel_h(),
                 rgb(0x202028));
    for (int r = 0; r < 4; r++) {
        const char *keys = OSK_ROW_KEYS[r];
        int n = (int)strlen(keys);
        int kw = osk_row_key_w(n);
        for (int i = 0; i < n; i++) {
            uint64_t kx = 8 + OSK_GAP +
                          (uint64_t)i * (uint64_t)(kw + OSK_GAP);
            uint64_t ky = py + OSK_GAP +
                          (uint64_t)r * (OSK_KEY_H + OSK_GAP);
            char label[2] = {keys[i], '\0'};
            osk_draw_key(kx, ky, (uint64_t)kw, label);
        }
    }
    {
        uint64_t ky = py + OSK_GAP +
                      (uint64_t)4 * (OSK_KEY_H + OSK_GAP);
        int unit = (int)((fb_width() - 16 - OSK_GAP * 7) /
                         OSK_CTL_UNITS);
        uint64_t kx = 8 + OSK_GAP;
        for (int i = 0; i < 6; i++) {
            uint64_t kw = (uint64_t)(OSK_CTL[i].units * unit);
            osk_draw_key(kx, ky, kw, OSK_CTL[i].label);
            kx += kw + OSK_GAP;
        }
    }
}

/* パネル上のクリック位置からキーコードを返す。
 * パネル外は -1、パネルの隙間は -2。 */
static int osk_key_at(int x, int y) {
    if (!desk_settings.osk) {
        return -1;
    }
    uint64_t py = osk_panel_y();
    if (y < (int)py) {
        return -1;
    }
    int rel = y - (int)py - OSK_GAP;
    if (rel < 0) {
        return -2;
    }
    int r = rel / (OSK_KEY_H + OSK_GAP);
    if (r >= OSK_ROWS || (rel % (OSK_KEY_H + OSK_GAP)) >= OSK_KEY_H) {
        return -2;
    }
    int relx = x - 8 - OSK_GAP;
    if (relx < 0) {
        return -2;
    }
    if (r < 4) {
        const char *keys = OSK_ROW_KEYS[r];
        int n = (int)strlen(keys);
        int kw = osk_row_key_w(n);
        int i = relx / (kw + OSK_GAP);
        if (i >= n || (relx % (kw + OSK_GAP)) >= kw) {
            return -2;
        }
        return (unsigned char)keys[i];
    }
    {
        int unit = (int)((fb_width() - 16 - OSK_GAP * 7) /
                         OSK_CTL_UNITS);
        int acc = 0;
        for (int i = 0; i < 6; i++) {
            int w = OSK_CTL[i].units * unit;
            if (relx >= acc && relx < acc + w) {
                return OSK_CTL[i].code;
            }
            acc += w + OSK_GAP;
        }
    }
    return -2;
}

/* OSK の注入キュー: クリックされたキーはここに入り、
 * シェルの入力ループが物理キーと同じ経路で取り出す
 * (desktop_handle_key で消費されなければ行入力になる)。 */
#define OSK_QUEUE_MAX 16
static int osk_queue[OSK_QUEUE_MAX];
static int osk_queue_len;

int desktop_osk_poll_key(void) {
    if (osk_queue_len <= 0) {
        return -1;
    }
    int c = osk_queue[0];
    for (int i = 1; i < osk_queue_len; i++) {
        osk_queue[i - 1] = osk_queue[i];
    }
    osk_queue_len--;
    return c;
}

static void draw_narrator_caption(void) {
    if (!desk_settings.narrator || narrator_caption[0] == '\0') {
        return;
    }
    /* 字幕は文字サイズに追従し、幅に合わせて最大 3 行に
     * 折り返す (E3)。 */
    int unit = text_scale_now();
    uint64_t lh = (uint64_t)(20 * unit);
    uint64_t maxw = fb_width() - 24;
    /* 行分け: 1 行に収まる最長プレフィックスを繰り返し取る。 */
    char lines[3][170];
    int nlines = 0;
    const char *p = narrator_caption;
    while (*p != '\0' && nlines < 3) {
        size_t best = 0;
        size_t i = 0;
        while (p[i] != '\0') {
            size_t cl = ((unsigned char)p[i] & 0xE0) == 0xC0
                            ? 2
                        : ((unsigned char)p[i] & 0xF0) == 0xE0
                            ? 3
                        : ((unsigned char)p[i] & 0xF8) == 0xF0
                            ? 4
                            : 1;
            char tmp[170];
            size_t n = i + cl;
            if (n >= sizeof(tmp)) {
                break;
            }
            for (size_t k = 0; k < n; k++) {
                tmp[k] = p[k];
            }
            tmp[n] = '\0';
            if (fb_text_aa_width(tmp, aa_px_body(), 0) > maxw) {
                break;
            }
            best = n;
            i += cl;
        }
        if (best == 0) {
            best = i > 0 ? i : 1;
        }
        for (size_t k = 0; k < best; k++) {
            lines[nlines][k] = p[k];
        }
        lines[nlines][best] = '\0';
        nlines++;
        p += best;
    }
    uint64_t base = desk_settings.osk ? osk_panel_y() : taskbar_y();
    uint64_t band = lh * (uint64_t)nlines + 16;
    if (base < band) {
        return;
    }
    fb_fill_rect(0, base - band, fb_width(), band, rgb(0x000000));
    for (int i = 0; i < nlines; i++) {
        fb_draw_text_aa(12,
                        aa_baseline(base - band + 8 +
                                        lh * (uint64_t)i,
                                    aa_px_body()),
                        lines[i], rgb(0xFFFF00), 0x000000,
                        aa_px_body(), 0);
    }
    (void)unit;
}

void desktop_notify(const char *msg) {
    if (msg == NULL) {
        return;
    }
    int slot = -1;
    for (int i = 0; i < NOTIFY_MAX; i++) {
        if (notify_ttl[i] == 0) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {
        slot = 0; /* overwrite the oldest slot */
    }
    size_t n = 0;
    while (msg[n] != '\0' && n + 1 < NOTIFY_TEXT_MAX) {
        notify_text[slot][n] = msg[n];
        n++;
    }
    notify_text[slot][n] = '\0';
    {
        int hs = notify_hist_count % NOTIFY_HIST_MAX;
        {
            prism_rtc_time nt;
            if (rtc_read(&nt) == 0) {
                notify_hist_time[hs][0] =
                    (char)('0' + nt.hour / 10);
                notify_hist_time[hs][1] =
                    (char)('0' + nt.hour % 10);
                notify_hist_time[hs][2] = ':';
                notify_hist_time[hs][3] =
                    (char)('0' + nt.minute / 10);
                notify_hist_time[hs][4] =
                    (char)('0' + nt.minute % 10);
                notify_hist_time[hs][5] = '\0';
            } else {
                notify_hist_time[hs][0] = '\0';
            }
        }
        size_t hn = 0;
        while (notify_text[slot][hn] != '\0' &&
               hn + 1 < NOTIFY_TEXT_MAX) {
            notify_hist[hs][hn] = notify_text[slot][hn];
            hn++;
        }
        notify_hist[hs][hn] = '\0';
        notify_hist_count++;
        notify_hist_save();
    }
    notify_ttl[slot] = 6; /* about six seconds */
    if (slot >= notify_count) {
        notify_count = slot + 1;
    }
    serial_write("notify: ");
    serial_write_line(notify_text[slot]);
    narrator_say(notify_text[slot]);
    if (desk_ok) {
        desktop_redraw();
    }
}

/* ================= カメラ (D3) =================
 * USB ビデオデバイス (UVC) のプレビューと撮影。デバイス
 * 側は xhci.c の uvc_start / uvc_poll_frame。YUY2 フレーム
 * を RGB へ変換して表示し、撮影は BMP で写真へ保存する。
 * MJPEG 形式はデコーダが無いため未対応と表示する。
 * カメラが無い環境では「見つからない」画面になる (実機
 * 転送の検証は実機側の課題として既知)。 */
#define CAM_MAX_W 640
#define CAM_MAX_H 480
static uint8_t cam_frame[CAM_MAX_W * CAM_MAX_H * 2];
static uint8_t cam_bmp[54 + CAM_MAX_W * 3 * CAM_MAX_H];
static int cam_streaming;
static int cam_fmt_idx;
static int cam_have_frame;
static char cam_status[96];
static int cam_btn_x[3];
static int cam_btn_w[3];
static int cam_btn_y;

static void cam_set_status(const char *en, const char *ja) {
    const char *s = desk_settings.language ? ja : en;
    size_t p = 0;
    while (s[p] != '\0' && p + 1 < sizeof(cam_status)) {
        cam_status[p] = s[p];
        p++;
    }
    cam_status[p] = '\0';
}

static void cam_stop_stream(void) {
    if (cam_streaming) {
        uvc_stop();
        cam_streaming = 0;
        serial_write_line("camera: stream stopped");
    }
}

static void cam_start_stream(void) {
    if (!uvc_present()) {
        return;
    }
    const uvc_format_frame *f = uvc_format_at(cam_fmt_idx);
    if (f == NULL) {
        return;
    }
    if (f->is_mjpeg) {
        cam_set_status("MJPEG preview is not supported yet.",
                       "MJPEG形式のプレビューは未対応です");
        return;
    }
    if (uvc_start(cam_fmt_idx) == 0) {
        cam_streaming = 1;
        cam_have_frame = 0;
        serial_write_line("camera: stream started");
    } else {
        cam_set_status("Could not start the camera.",
                       "カメラを開始できませんでした");
    }
}

static void cam_poll(void) {
    if (!cam_streaming) {
        return;
    }
    if (desk_mode != DESK_CAMERA) {
        cam_stop_stream();
        return;
    }
    int n = uvc_poll_frame(cam_frame, sizeof(cam_frame));
    if (n > 0) {
        cam_have_frame = 1;
        desktop_redraw();
    }
}

static void cam_capture(void) {
    const uvc_format_frame *f = uvc_format_at(cam_fmt_idx);
    if (!cam_have_frame || f == NULL || f->is_mjpeg) {
        cam_set_status("No frame to capture yet.",
                       "撮影できるフレームがまだありません");
        desktop_redraw();
        return;
    }
    uint32_t w = f->width;
    uint32_t h = f->height;
    if (w > CAM_MAX_W) w = CAM_MAX_W;
    if (w == 0) w = 1;
    if (h > CAM_MAX_H) h = CAM_MAX_H;
    if (h == 0) h = 1;
    uint32_t row = w * 3;
    uint32_t total = 54 + row * h;
    for (uint32_t i = 0; i < total; i++) {
        cam_bmp[i] = 0;
    }
    cam_bmp[0] = 'B';
    cam_bmp[1] = 'M';
    cam_bmp[2] = (uint8_t)total;
    cam_bmp[3] = (uint8_t)(total >> 8);
    cam_bmp[4] = (uint8_t)(total >> 16);
    cam_bmp[10] = 54;
    cam_bmp[14] = 40;
    cam_bmp[18] = (uint8_t)w;
    cam_bmp[19] = (uint8_t)(w >> 8);
    cam_bmp[22] = (uint8_t)h;
    cam_bmp[23] = (uint8_t)(h >> 8);
    cam_bmp[26] = 1;
    cam_bmp[28] = 24;
    for (uint32_t y = 0; y < h; y++) {
        uint32_t sy = h - 1 - y; /* BMP は下から上 */
        for (uint32_t x = 0; x < w; x++) {
            uint32_t pair = ((sy * f->width + x) / 2) * 4;
            int yv = cam_frame[pair + (x & 1) * 2];
            int u = cam_frame[pair + 1];
            int v = cam_frame[pair + 3];
            int r = yv + ((359 * (v - 128)) >> 8);
            int g = yv - ((88 * (u - 128) + 183 * (v - 128)) >> 8);
            int b = yv + ((454 * (u - 128)) >> 8);
            if (r < 0) r = 0;
            if (r > 255) r = 255;
            if (g < 0) g = 0;
            if (g > 255) g = 255;
            if (b < 0) b = 0;
            if (b > 255) b = 255;
            size_t o = 54 + (size_t)y * row + (size_t)x * 3;
            cam_bmp[o] = (uint8_t)b;
            cam_bmp[o + 1] = (uint8_t)g;
            cam_bmp[o + 2] = (uint8_t)r;
        }
    }
    /* cam1.bmp, cam2.bmp, ... の空き名へ保存する。 */
    char name[16];
    int num = 1;
    for (; num < 100; num++) {
        int p = 0;
        name[p++] = 'c';
        name[p++] = 'a';
        name[p++] = 'm';
        if (num >= 10) {
            name[p++] = (char)('0' + num / 10);
        }
        name[p++] = (char)('0' + num % 10);
        name[p++] = '.';
        name[p++] = 'b';
        name[p++] = 'm';
        name[p++] = 'p';
        name[p] = '\0';
        size_t dummy = 0;
        if (vfs_read_ptr(name, &dummy) == NULL) {
            break;
        }
    }
    if (num < 100 &&
        vfs_write(name, (const char *)cam_bmp, total) == 0) {
        persist_maybe_sync();
        cam_set_status("Saved to Photos.", "写真に保存しました");
        serial_write("camera: saved ");
        serial_write_line(name);
        desktop_notify(L("Photo saved", "写真を保存しました"));
    } else {
        cam_set_status("Could not save the photo.",
                       "写真を保存できませんでした");
    }
    desktop_redraw();
}

static void draw_camera(void) {
    uint32_t fg = col_text();
    uint32_t bg = col_window_bg();
    uint32_t acc = col_accent();
    uint32_t dim = col_dim();
    uint64_t x0 = text_x();
    uint64_t y0 = text_y();
    draw_text_small(x0, y0, L("Camera", "カメラ"), acc, bg);
    if (!uvc_present()) {
        draw_text_small(x0, y0 + (uint64_t)(3 * CELL_H),
                        L("No camera found.", "カメラが見つかりません"),
                        fg, bg);
        draw_text_small(
            x0, y0 + (uint64_t)(5 * CELL_H),
            L("Connect a USB camera. The preview and capture "
              "work when a camera is present.",
              "USBカメラを接続してください。カメラがあれば"
              "プレビューと撮影ができます"),
            dim, bg);
        return;
    }
    const uvc_format_frame *f = uvc_format_at(cam_fmt_idx);
    char line[80];
    size_t p = 0;
    if (f != NULL) {
        const char *t = f->is_mjpeg ? "MJPEG " : "YUY2 ";
        while (*t != '\0' && p + 1 < sizeof(line)) {
            line[p++] = *t++;
        }
        char num[12];
        int nd = 0;
        unsigned wv = f->width;
        if (wv == 0) {
            num[nd++] = '0';
        }
        while (wv > 0) {
            num[nd++] = (char)('0' + wv % 10);
            wv /= 10;
        }
        while (nd > 0 && p + 1 < sizeof(line)) {
            line[p++] = num[--nd];
        }
        if (p + 1 < sizeof(line)) {
            line[p++] = 'x';
        }
        nd = 0;
        unsigned hv = f->height;
        if (hv == 0) {
            num[nd++] = '0';
        }
        while (hv > 0) {
            num[nd++] = (char)('0' + hv % 10);
            hv /= 10;
        }
        while (nd > 0 && p + 1 < sizeof(line)) {
            line[p++] = num[--nd];
        }
    }
    line[p] = '\0';
    draw_text_small(x0, y0 + (uint64_t)(2 * CELL_H), line, fg, bg);
    /* プレビュー枠。 */
    uint64_t px = x0;
    uint64_t py = y0 + 4 * CELL_H;
    uint64_t pw = win_w() - 32;
    uint64_t ph = 300;
    if (pw > 560) {
        pw = 560;
    }
    fb_fill_rect(px, py, pw, ph, rgb(0x000000));
    for (uint64_t i = 0; i < pw; i++) {
        fb_put_pixel(px + i, py, dim);
        fb_put_pixel(px + i, py + ph - 1, dim);
    }
    for (uint64_t i = 0; i < ph; i++) {
        fb_put_pixel(px, py + i, dim);
        fb_put_pixel(px + pw - 1, py + i, dim);
    }
    if (cam_have_frame && f != NULL && !f->is_mjpeg &&
        f->width > 0 && f->height > 0) {
        for (uint64_t dy = 0; dy < ph - 2; dy++) {
            uint32_t sy = (uint32_t)(dy * f->height / (ph - 2));
            for (uint64_t dx = 0; dx < pw - 2; dx++) {
                uint32_t sx = (uint32_t)(dx * f->width / (pw - 2));
                uint32_t pair = ((sy * f->width + sx) / 2) * 4;
                int yv = cam_frame[pair + (sx & 1) * 2];
                int u = cam_frame[pair + 1];
                int v = cam_frame[pair + 3];
                int r = yv + ((359 * (v - 128)) >> 8);
                int g = yv - ((88 * (u - 128) + 183 * (v - 128)) >> 8);
                int b = yv + ((454 * (u - 128)) >> 8);
                if (r < 0) r = 0;
                if (r > 255) r = 255;
                if (g < 0) g = 0;
                if (g > 255) g = 255;
                if (b < 0) b = 0;
                if (b > 255) b = 255;
                fb_put_pixel(px + 1 + dx, py + 1 + dy,
                             rgb((uint32_t)r << 16 |
                                 (uint32_t)g << 8 | (uint32_t)b));
            }
        }
    } else {
        draw_text_small(px + 16, py + 16,
                        cam_streaming
                            ? L("Waiting for frames...", "フレーム待ち...")
                            : L("Press Start to preview.",
                                "「開始」でプレビューします"),
                        dim, rgb(0x000000));
    }
    if (cam_status[0] != '\0') {
        draw_text_small(x0, py + ph + (uint64_t)CELL_H, cam_status,
                        acc, bg);
    }
    /* ボタン: 開始/停止、撮影、形式切替。 */
    cam_btn_y = (int)(y0 + (uint64_t)((text_rows() - 3) * CELL_H));
    const char *labels[3] = {
        cam_streaming ? L("Stop", "停止") : L("Start", "開始"),
        L("Capture", "撮影"), L("Format", "形式切替")};
    int bx = (int)x0;
    for (int i = 0; i < 3; i++) {
        int w = (int)fb_text_aa_width(labels[i], aa_px_body(), 0) + 28;
        cam_btn_x[i] = bx;
        cam_btn_w[i] = w;
        uint32_t face = i == 1 ? acc : col_title_bg();
        if (i != 1 &&
            ui_hover(bx, cam_btn_y, w, (int)CELL_H + 10)) {
            face = col_hover();
        }
        fb_fill_rect((uint64_t)bx, (uint64_t)cam_btn_y, (uint64_t)w,
                     (uint64_t)(CELL_H + 10), face);
        draw_text_small((uint64_t)(bx + 14),
                        (uint64_t)(cam_btn_y + 5), labels[i],
                        i == 1 ? rgb(0xFFFFFF) : fg, face);
        bx += w + 10;
    }
    draw_text_small(
        x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
        L("Enter = start/stop  C = capture  Left/Right = format",
          "Enter = 開始/停止  C = 撮影  ←→ = 形式"),
        dim, bg);
}

static int cam_handle_key(int c) {
    if (c == '\n' || c == '\r') {
        if (cam_streaming) {
            cam_stop_stream();
        } else {
            cam_start_stream();
        }
        desktop_redraw();
        return 1;
    }
    if (c == 'c' || c == 'C') {
        cam_capture();
        return 1;
    }
    if (c == DESK_KEY_LEFT || c == DESK_KEY_RIGHT) {
        int n = uvc_format_count();
        if (n > 0) {
            cam_stop_stream();
            cam_fmt_idx = (cam_fmt_idx + (c == DESK_KEY_RIGHT ? 1 : n - 1)) % n;
            cam_have_frame = 0;
        }
        desktop_redraw();
        return 1;
    }
    return 0;
}

/* ================= レコーダー (D4) =================
 * HD Audio の入力 (hda_record) で録音し、WAV で保存する。
 * 録音ファイルの一覧と再生 (16bit → 8bit 変換して SB16 で
 * 再生)・削除もここで行う。採取 DMA の完了が観測できない
 * 環境では録音は正直に失敗として表示する (偽のファイルは
 * 作らない)。 */
static int rec_secs = 2;
static int rec_sel;
static char rec_status[96];
static int rec_playing;
static int rec_recording;
static int rec_btn_x[4];
static int rec_btn_w[4];
static int rec_btn_y;
static int rec_list_y;
static uint8_t rec_conv[96 * 1024];
static uint8_t rec_wavbuf[44 + 589824];

static void rec_set_status(const char *en, const char *ja) {
    const char *s = desk_settings.language ? ja : en;
    size_t p = 0;
    while (s[p] != '\0' && p + 1 < sizeof(rec_status)) {
        rec_status[p] = s[p];
        p++;
    }
    rec_status[p] = '\0';
}

static int rec_is_name(const char *n) {
    if (n == NULL || n[0] != 'r' || n[1] != 'e' || n[2] != 'c') {
        return 0;
    }
    size_t l = 0;
    while (n[l] != '\0') {
        l++;
    }
    return l >= 5 && n[l - 4] == '.' && n[l - 3] == 'w' &&
           n[l - 2] == 'a' && n[l - 1] == 'v';
}

static int rec_list(int *out, int max) {
    int count = 0;
    int n = vfs_file_count();
    for (int i = 0; i < n && count < max; i++) {
        const char *name = vfs_file_name(i);
        if (name != NULL && rec_is_name(name)) {
            out[count++] = i;
        }
    }
    return count;
}

static void rec_do_record(void) {
    if (!hda_capture_supported()) {
        rec_set_status("No recording device found.",
                       "録音デバイスがありません");
        serial_write_line("recorder: no device");
        desktop_redraw();
        return;
    }
    rec_recording = 1;
    rec_set_status("Recording...", "録音中...");
    desktop_redraw();
    fb_flush();
    uint32_t bytes = 0;
    uint32_t peak = 0;
    int rc = hda_record((uint32_t)rec_secs * 1000u, &bytes, &peak);
    rec_recording = 0;
    const int16_t *pcm = hda_capture_data();
    if (rc != 0 || bytes == 0 || pcm == NULL ||
        wav_build_header16(rec_wavbuf, sizeof(rec_wavbuf), bytes,
                           48000, 2) != 0) {
        /* 採取できない環境では正直に失敗を表示する。 */
        rec_set_status("Could not capture audio in this environment.",
                       "この環境では音声を採取できませんでした");
        serial_write_line("recorder: capture failed");
        desktop_redraw();
        return;
    }
    const uint8_t *s = (const uint8_t *)pcm;
    for (uint32_t i = 0; i < bytes; i++) {
        rec_wavbuf[44 + i] = s[i];
    }
    /* rec1.wav, rec2.wav, ... の空き名へ保存する。 */
    char name[16];
    int num = 1;
    for (; num < 100; num++) {
        int p = 0;
        name[p++] = 'r';
        name[p++] = 'e';
        name[p++] = 'c';
        if (num >= 10) {
            name[p++] = (char)('0' + num / 10);
        }
        name[p++] = (char)('0' + num % 10);
        name[p++] = '.';
        name[p++] = 'w';
        name[p++] = 'a';
        name[p++] = 'v';
        name[p] = '\0';
        size_t dummy = 0;
        if (vfs_read_ptr(name, &dummy) == NULL) {
            break;
        }
    }
    if (num >= 100 ||
        vfs_write(name, (const char *)rec_wavbuf, 44 + bytes) != 0) {
        rec_set_status("Could not save the recording.",
                       "録音を保存できませんでした");
        desktop_redraw();
        return;
    }
    rec_set_status("Saved.", "保存しました");
    serial_write("recorder: saved ");
    serial_write_line(name);
    desktop_notify(L("Recording saved", "録音を保存しました"));
    desktop_redraw();
}

static void rec_do_play(void) {
    int list[PRISM_VFS_MAX_FILES];
    int count = rec_list(list, PRISM_VFS_MAX_FILES);
    if (count == 0 || rec_sel < 0 || rec_sel >= count) {
        return;
    }
    const char *name = vfs_file_name(list[rec_sel]);
    size_t len = 0;
    const char *data = vfs_read_ptr(name, &len);
    if (data == NULL || len < 44) {
        return;
    }
    const uint8_t *d = (const uint8_t *)data;
    /* 8-bit mono WAV はそのまま再生する。 */
    wav_info info;
    if (wav_parse(d, len, &info) == 0) {
        if (sb16_start_8bit(info.samples, info.sample_count,
                            info.sample_rate) == 0) {
            rec_playing = 1;
            serial_write_line("recorder: playing");
        }
        return;
    }
    /* 16-bit PCM WAV (このアプリと `hda record` の形式) を
     * 8-bit / 24kHz / mono へ変換して再生する。 */
    if (len < 44 || memcmp(d, "RIFF", 4) != 0 ||
        memcmp(d + 8, "WAVE", 4) != 0) {
        rec_set_status("Unsupported WAV format.", "未対応のWAV形式です");
        return;
    }
    uint16_t fmt = (uint16_t)(d[20] | (d[21] << 8));
    uint16_t ch = (uint16_t)(d[22] | (d[23] << 8));
    uint32_t rate = (uint32_t)d[24] | ((uint32_t)d[25] << 8) |
                    ((uint32_t)d[26] << 16) | ((uint32_t)d[27] << 24);
    uint16_t bits = (uint16_t)(d[34] | (d[35] << 8));
    if (fmt != 1 || bits != 16 || (ch != 1 && ch != 2) || rate == 0) {
        rec_set_status("Unsupported WAV format.", "未対応のWAV形式です");
        return;
    }
    /* data チャンクを探す。 */
    size_t off = 12;
    const uint8_t *pcm = NULL;
    uint32_t pcm_len = 0;
    while (off + 8 <= len) {
        uint32_t csz = (uint32_t)d[off + 4] |
                       ((uint32_t)d[off + 5] << 8) |
                       ((uint32_t)d[off + 6] << 16) |
                       ((uint32_t)d[off + 7] << 24);
        if (memcmp(d + off, "data", 4) == 0) {
            pcm = d + off + 8;
            pcm_len = csz;
            if (off + 8 + pcm_len > len) {
                pcm_len = (uint32_t)(len - (off + 8));
            }
            break;
        }
        off += 8 + csz + (csz & 1);
    }
    if (pcm == NULL) {
        rec_set_status("Unsupported WAV format.", "未対応のWAV形式です");
        return;
    }
    uint32_t frames = pcm_len / (2u * ch);
    uint32_t step = rate / 24000;
    if (step == 0) {
        step = 1;
    }
    uint32_t outn = frames / step;
    if (outn > sizeof(rec_conv)) {
        outn = (uint32_t)sizeof(rec_conv);
    }
    for (uint32_t i = 0; i < outn; i++) {
        const uint8_t *f = pcm + (size_t)(i * step) * 2u * ch;
        int v = (int)(int16_t)(f[0] | (f[1] << 8));
        if (ch == 2) {
            v += (int)(int16_t)(f[2] | (f[3] << 8));
            v /= 2;
        }
        int o = (v >> 8) + 128;
        if (o < 0) {
            o = 0;
        }
        if (o > 255) {
            o = 255;
        }
        rec_conv[i] = (uint8_t)o;
    }
    if (sb16_start_8bit(rec_conv, outn, 24000) == 0) {
        rec_playing = 1;
        serial_write_line("recorder: playing");
    }
}

static void rec_poll(void) {
    if (rec_playing && !sb16_is_playing()) {
        sb16_stop();
        rec_playing = 0;
        serial_write_line("recorder: play done");
        if (desk_mode == DESK_RECORDER) {
            desktop_redraw();
        }
    }
}

static void draw_recorder(void) {
    uint32_t fg = col_text();
    uint32_t bg = col_window_bg();
    uint32_t acc = col_accent();
    uint32_t dim = col_dim();
    uint64_t x0 = text_x();
    uint64_t y0 = text_y();
    draw_text_small(x0, y0, L("Recorder", "レコーダー"), acc, bg);
    int have_dev = hda_capture_supported();
    draw_text_small(x0, y0 + (uint64_t)(2 * CELL_H),
                    have_dev ? L("Microphone: available",
                                 "マイク: 利用できます")
                             : L("Microphone: no device",
                                 "マイク: デバイスがありません"),
                    have_dev ? fg : dim, bg);
    /* 録音時間と録音ボタン。 */
    char line[64];
    size_t p = 0;
    const char *h = L("Length: ", "録音時間: ");
    while (*h != '\0' && p + 1 < sizeof(line)) {
        line[p++] = *h++;
    }
    line[p++] = (char)('0' + rec_secs);
    const char *u = L(" sec", " 秒");
    while (*u != '\0' && p + 1 < sizeof(line)) {
        line[p++] = *u++;
    }
    line[p] = '\0';
    /* ボタン (3 行目、高さ CELL_H+10) の下に置く。ボタンと
     * 重なると文字が欠けて見える。 */
    draw_text_small(x0, y0 + (uint64_t)(5 * CELL_H), line, fg, bg);
    rec_btn_y = (int)(y0 + 3 * CELL_H);
    const char *rl = rec_recording ? L("Recording...", "録音中...")
                                   : L("Record", "録音開始");
    int rw = (int)fb_text_aa_width(rl, aa_px_body(), 0) + 28;
    /* ボタンは本文の左端に揃える (C2)。マイクがない場合は
     * 通常ボタンの見た目にして、押せない理由が状態欄に出る
     * 従来動作と見た目を一致させる。 */
    rec_btn_x[0] = (int)x0;
    rec_btn_w[0] = rw;
    uint32_t rface = rec_recording ? rgb(0xC0392B)
                                   : (have_dev ? acc
                                               : col_title_bg());
    fb_fill_rect((uint64_t)rec_btn_x[0], (uint64_t)rec_btn_y,
                 (uint64_t)rw, (uint64_t)(CELL_H + 10), rface);
    draw_text_small((uint64_t)(rec_btn_x[0] + 14),
                    (uint64_t)(rec_btn_y + 5), rl,
                    (rec_recording || have_dev) ? rgb(0xFFFFFF)
                                                : dim,
                    rface);
    if (rec_status[0] != '\0') {
        draw_text_small(x0, y0 + (uint64_t)(6 * CELL_H), rec_status,
                        acc, bg);
    }
    /* 録音ファイルの一覧。 */
    draw_text_small(x0, y0 + (uint64_t)(8 * CELL_H),
                    L("Recordings", "録音ファイル"), acc, bg);
    int list[PRISM_VFS_MAX_FILES];
    int count = rec_list(list, PRISM_VFS_MAX_FILES);
    if (rec_sel >= count) {
        rec_sel = count > 0 ? count - 1 : 0;
    }
    rec_list_y = (int)(y0 + 9 * CELL_H);
    if (count == 0) {
        draw_text_small(x0, y0 + (uint64_t)(10 * CELL_H),
                        L("No recordings yet. Press Record to make one.",
                          "まだ録音がありません。「録音開始」で作れます"),
                        dim, bg);
    }
    for (int i = 0; i < count; i++) {
        uint64_t ry = y0 + (uint64_t)((9 + i) * CELL_H);
        const char *name = vfs_file_name(list[i]);
        size_t flen = 0;
        (void)vfs_read_ptr(name, &flen);
        if (i == rec_sel) {
            fb_fill_rect(x0 - 4, ry, win_w() - 24, CELL_H, acc);
        }
        draw_text_small(x0, ry, name, i == rec_sel ? rgb(0xFFFFFF) : fg,
                        i == rec_sel ? acc : bg);
        char sz[24];
        size_t q = 0;
        unsigned kb = (unsigned)(flen / 1024);
        char tmp[10];
        int td = 0;
        if (kb == 0) {
            tmp[td++] = '0';
        }
        while (kb > 0) {
            tmp[td++] = (char)('0' + kb % 10);
            kb /= 10;
        }
        while (td > 0) {
            sz[q++] = tmp[--td];
        }
        sz[q++] = ' ';
        sz[q++] = 'K';
        sz[q++] = 'B';
        sz[q] = '\0';
        draw_text_small(x0 + 300, ry, sz,
                        i == rec_sel ? rgb(0xFFFFFF) : dim,
                        i == rec_sel ? acc : bg);
    }
    /* 再生 / 停止 / 削除ボタン。再生は録音がある時だけ
     * 主要ボタンの見た目にする (C2)。 */
    rec_btn_y = (int)(y0 + (uint64_t)((text_rows() - 3) * CELL_H));
    const char *labels[3] = {L("Play", "再生"), L("Stop", "停止"),
                             L("Delete", "削除")};
    int bx = (int)x0;
    for (int i = 0; i < 3; i++) {
        int w = (int)fb_text_aa_width(labels[i], aa_px_body(), 0) + 28;
        rec_btn_x[1 + i] = bx;
        rec_btn_w[1 + i] = w;
        int primary = i == 0 && count > 0;
        uint32_t face = primary ? acc : col_title_bg();
        if (!primary &&
            ui_hover(bx, rec_btn_y, w, (int)CELL_H + 10)) {
            face = col_hover();
        }
        fb_fill_rect((uint64_t)bx, (uint64_t)rec_btn_y, (uint64_t)w,
                     (uint64_t)(CELL_H + 10), face);
        draw_text_small((uint64_t)(bx + 14),
                        (uint64_t)(rec_btn_y + 5), labels[i],
                        primary ? rgb(0xFFFFFF)
                                : (i == 0 ? dim : fg),
                        face);
        bx += w + 10;
    }
    draw_text_small(
        x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
        L("Enter = record  Left/Right = length  Up/Down = select",
          "Enter = 録音  ←→ = 時間  ↑↓ = 選択"),
        dim, bg);
}

static int rec_handle_key(int c) {
    int list[PRISM_VFS_MAX_FILES];
    int count = rec_list(list, PRISM_VFS_MAX_FILES);
    if (c == '\n' || c == '\r') {
        rec_do_record();
        return 1;
    }
    if (c == DESK_KEY_LEFT) {
        if (rec_secs > 1) {
            rec_secs--;
        }
        desktop_redraw();
        return 1;
    }
    if (c == DESK_KEY_RIGHT) {
        if (rec_secs < 3) {
            rec_secs++;
        }
        desktop_redraw();
        return 1;
    }
    if (c == DESK_KEY_UP) {
        if (rec_sel > 0) {
            rec_sel--;
        }
        desktop_redraw();
        return 1;
    }
    if (c == DESK_KEY_DOWN) {
        if (rec_sel + 1 < count) {
            rec_sel++;
        }
        desktop_redraw();
        return 1;
    }
    if (c == 'p' || c == 'P') {
        rec_do_play();
        desktop_redraw();
        return 1;
    }
    if (c == 's' || c == 'S') {
        if (rec_playing) {
            sb16_stop();
            rec_playing = 0;
            serial_write_line("recorder: stopped");
        }
        desktop_redraw();
        return 1;
    }
    if (c == 'd' || c == 'D') {
        if (count > 0 && rec_sel < count) {
            const char *name = vfs_file_name(list[rec_sel]);
            if (vfs_delete(name) == 0) {
                serial_write_line("recorder: deleted");
                rec_set_status("Deleted.", "削除しました");
            }
        }
        desktop_redraw();
        return 1;
    }
    return 0;
}

/* ================= 時計アプリ (D5) =================
 * 大きな現在時刻に、アラーム / タイマー / ストップウォッチの
 * タブを付けた独立アプリ。時刻は RTC、経過は epoch 秒で
 * 数える。アラームとタイマーの終了は desktop_tick から
 * clock_poll() が見張り、通知で知らせる。 */
static int clock_tab; /* 0 時計 1 アラーム 2 タイマー 3 SW */
static int clock_alarm_h = 7;
static int clock_alarm_m;
static int clock_alarm_on;
static int clock_alarm_field; /* 0=時 1=分 */
static uint32_t clock_alarm_fired; /* 発火済み epoch 分 */
static int clock_timer_set = 300;
static int clock_timer_state; /* 0 停止 1 動作 2 一時停止 */
static uint32_t clock_timer_end;
static int clock_timer_left_hold;
static int clock_timer_field; /* 0=分 1=秒 */
static uint32_t clock_sw_accum;
static uint32_t clock_sw_start;
static int clock_sw_state; /* 0 停止 1 動作 */
static int clock_last_sec = -1;
static int clock_tab_x[4];
static int clock_tab_w[4];
static int clock_btn_x[3];
static int clock_btn_w[3];
static int clock_btn_y;
static int clock_big_x;
static int clock_big_y;

static void clock_fmt_hms(char *buf, uint32_t secs, int with_hour) {
    uint32_t h = secs / 3600;
    uint32_t m = (secs / 60) % 60;
    uint32_t s = secs % 60;
    int p = 0;
    if (with_hour) {
        buf[p++] = (char)('0' + (h / 10) % 10);
        buf[p++] = (char)('0' + h % 10);
        buf[p++] = ':';
    }
    buf[p++] = (char)('0' + (m / 10) % 10);
    buf[p++] = (char)('0' + m % 10);
    buf[p++] = ':';
    buf[p++] = (char)('0' + (s / 10) % 10);
    buf[p++] = (char)('0' + s % 10);
    buf[p] = '\0';
}

static uint32_t clock_sw_elapsed(void) {
    if (clock_sw_state == 1) {
        return clock_sw_accum + (lock_now_epoch() - clock_sw_start);
    }
    return clock_sw_accum;
}

static int clock_timer_left(void) {
    if (clock_timer_state == 1) {
        uint32_t now = lock_now_epoch();
        return now >= clock_timer_end ? 0
                                      : (int)(clock_timer_end - now);
    }
    if (clock_timer_state == 2) {
        return clock_timer_left_hold;
    }
    return clock_timer_set;
}

static void clock_poll(void) {
    prism_rtc_time t;
    if (rtc_read(&t) != 0) {
        return;
    }
    uint32_t now = lock_now_epoch();
    if (clock_alarm_on && t.hour == clock_alarm_h &&
        t.minute == clock_alarm_m) {
        uint32_t min_key = now / 60;
        if (clock_alarm_fired != min_key) {
            clock_alarm_fired = min_key;
            char msg[64];
            size_t p = 0;
            const char *h = L("Alarm ", "アラーム ");
            while (*h != '\0' && p + 1 < sizeof(msg)) {
                msg[p++] = *h++;
            }
            msg[p++] = (char)('0' + (clock_alarm_h / 10) % 10);
            msg[p++] = (char)('0' + clock_alarm_h % 10);
            msg[p++] = ':';
            msg[p++] = (char)('0' + (clock_alarm_m / 10) % 10);
            msg[p++] = (char)('0' + clock_alarm_m % 10);
            msg[p] = '\0';
            desktop_notify(msg);
            serial_write_line("clock: alarm");
        }
    }
    if (clock_timer_state == 1 && now >= clock_timer_end) {
        clock_timer_state = 0;
        desktop_notify(L("Timer finished", "タイマーが終了しました"));
        serial_write_line("clock: timer done");
    }
    /* 時計アプリ表示中は秒の変化で描き直す。 */
    if (desk_mode == DESK_CLOCK && t.second != clock_last_sec) {
        clock_last_sec = t.second;
        desktop_redraw();
    }
}

static void draw_clockapp(void) {
    uint32_t fg = col_text();
    uint32_t bg = col_window_bg();
    uint32_t acc = col_accent();
    uint32_t dim = col_dim();
    uint64_t x0 = text_x();
    uint64_t y0 = text_y();
    draw_text_small(x0, y0, L("Clock", "時計"), acc, bg);
    /* タブ。 */
    static const char *const tab_en[4] = {"Clock", "Alarm", "Timer",
                                          "Stopwatch"};
    static const char *const tab_ja[4] = {"時計", "アラーム", "タイマー",
                                          "ストップウォッチ"};
    int tx = (int)x0;
    int ty = (int)(y0 + 2 * CELL_H);
    for (int i = 0; i < 4; i++) {
        const char *s = desk_settings.language ? tab_ja[i] : tab_en[i];
        int w = (int)fb_text_aa_width(s, aa_px_body(), 0) + 20;
        clock_tab_x[i] = tx;
        clock_tab_w[i] = w;
        uint32_t face = i == clock_tab ? acc : col_title_bg();
        if (i != clock_tab &&
            ui_hover(tx, ty, w, (int)CELL_H + 8)) {
            face = col_hover();
        }
        fb_fill_rect((uint64_t)tx, (uint64_t)ty, (uint64_t)w,
                     (uint64_t)(CELL_H + 8), face);
        draw_text_small((uint64_t)(tx + 10), (uint64_t)(ty + 4), s,
                        i == clock_tab ? rgb(0xFFFFFF) : fg, face);
        tx += w + 8;
    }
    uint64_t by = y0 + 5 * CELL_H;
    clock_btn_y = (int)(y0 + (uint64_t)((text_rows() - 3) * CELL_H));
    clock_big_x = (int)x0;
    clock_big_y = (int)by;
    prism_rtc_time t;
    int have = rtc_read(&t) == 0;
    if (clock_tab == 0) {
        if (have) {
            char tb[16];
            int p = 0;
            tb[p++] = (char)('0' + (t.hour / 10) % 10);
            tb[p++] = (char)('0' + t.hour % 10);
            tb[p++] = ':';
            tb[p++] = (char)('0' + (t.minute / 10) % 10);
            tb[p++] = (char)('0' + t.minute % 10);
            tb[p++] = ':';
            tb[p++] = (char)('0' + (t.second / 10) % 10);
            tb[p++] = (char)('0' + t.second % 10);
            tb[p] = '\0';
            /* 大きな現在時刻 (AA 56px)。 */
            uint64_t tw = fb_text_aa_width(tb, 56, 0);
            fb_draw_text_aa((win_x() + win_w() / 2) - tw / 2,
                            aa_baseline(by, 56), tb, fg,
                            (int32_t)bg, 56, 0);
            char db[64];
            size_t q = 0;
            const char *pre = "";
            if (desk_settings.language) {
                char nb[16];
                size_t np = 0;
                unsigned yr = 2000u + t.year;
                nb[np++] = (char)('0' + (yr / 1000) % 10);
                nb[np++] = (char)('0' + (yr / 100) % 10);
                nb[np++] = (char)('0' + (yr / 10) % 10);
                nb[np++] = (char)('0' + yr % 10);
                nb[np] = '\0';
                const char *parts[6] = {nb, "年", NULL, "月", NULL, "日"};
                char mb[4];
                char dyb[4];
                mb[0] = (char)('0' + (t.month / 10) % 10);
                mb[1] = (char)('0' + t.month % 10);
                mb[2] = '\0';
                dyb[0] = (char)('0' + (t.day / 10) % 10);
                dyb[1] = (char)('0' + t.day % 10);
                dyb[2] = '\0';
                parts[2] = mb;
                parts[4] = dyb;
                for (int i = 0; i < 6; i++) {
                    const char *s = parts[i];
                    while (*s != '\0' && q + 1 < sizeof(db)) {
                        db[q++] = *s++;
                    }
                }
                static const char *const wd[7] = {
                    "日", "月", "火", "水", "木", "金", "土"};
                db[q++] = ' ';
                const char *w =
                    wd[rtc_weekday(2000 + t.year, t.month, t.day) % 7];
                while (*w != '\0' && q + 1 < sizeof(db)) {
                    db[q++] = *w++;
                }
                (void)pre;
            } else {
                const char *f = "%04d-%02d-%02d";
                (void)f;
                size_t np = 0;
                unsigned yr = 2000u + t.year;
                db[np++] = (char)('0' + (yr / 1000) % 10);
                db[np++] = (char)('0' + (yr / 100) % 10);
                db[np++] = (char)('0' + (yr / 10) % 10);
                db[np++] = (char)('0' + yr % 10);
                db[np++] = '-';
                db[np++] = (char)('0' + (t.month / 10) % 10);
                db[np++] = (char)('0' + t.month % 10);
                db[np++] = '-';
                db[np++] = (char)('0' + (t.day / 10) % 10);
                db[np++] = (char)('0' + t.day % 10);
                q = np;
            }
            db[q] = '\0';
            uint64_t dw = fb_text_aa_width(db, 28, 0);
            fb_draw_text_aa((win_x() + win_w() / 2) - dw / 2,
                            aa_baseline(by + 5 * 20 + 16, 28), db,
                            dim, (int32_t)bg, 28, 0);
        }
        draw_text_small(
            x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
            L("Tab = switch tab", "Tab = タブ切替"), dim, bg);
        return;
    }
    if (clock_tab == 1) {
        char tb[8];
        tb[0] = (char)('0' + (clock_alarm_h / 10) % 10);
        tb[1] = (char)('0' + clock_alarm_h % 10);
        tb[2] = ':';
        tb[3] = (char)('0' + (clock_alarm_m / 10) % 10);
        tb[4] = (char)('0' + clock_alarm_m % 10);
        tb[5] = '\0';
        fb_draw_text_aa((int64_t)x0, aa_baseline(by, 44), tb, fg,
                        (int32_t)bg, 44, 0);
        /* 選択中フィールドの下線 (AA 実幅で位置決め)。 */
        int uw = (int)fb_text_aa_width("00", 44, 0);
        int ux = (int)x0 +
                 (clock_alarm_field == 0
                      ? 0
                      : uw + (int)fb_text_aa_width(":", 44, 0));
        fb_fill_rect((uint64_t)ux, by + 52, (uint64_t)uw, 3, acc);
        int px = (int)x0 + (int)fb_text_aa_width(tb, 44, 0) + 40;
        draw_toggle_pill((uint64_t)px, by + 8, clock_alarm_on);
        draw_text_small((uint64_t)(px + 48), by + 8,
                        clock_alarm_on ? L("On", "オン")
                                       : L("Off", "オフ"),
                        fg, bg);
        draw_text_small(x0, by + 6 * CELL_H,
                        clock_alarm_on
                            ? L("The alarm will ring at the set time.",
                                "設定した時刻に通知します")
                            : L("The alarm is off.",
                                "アラームはオフです"),
                        dim, bg);
        draw_text_small(
            x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
            L("Left/Right = field  Up/Down = value  Space = on/off",
              "←→ = 欄の移動  ↑↓ = 値  Space = オン/オフ"),
            dim, bg);
        return;
    }
    if (clock_tab == 2) {
        char tb[16];
        clock_fmt_hms(tb, (uint32_t)clock_timer_left(), 0);
        fb_draw_text_aa((int64_t)x0, aa_baseline(by, 44), tb,
                        clock_timer_state == 1 ? acc : fg,
                        (int32_t)bg, 44, 0);
        if (clock_timer_state == 0) {
            int uw = (int)fb_text_aa_width("00", 44, 0);
            int ux = (int)x0 +
                     (clock_timer_field == 0
                          ? 0
                          : uw + (int)fb_text_aa_width(":", 44,
                                                       0));
            fb_fill_rect((uint64_t)ux, by + 52, (uint64_t)uw, 3,
                         acc);
        }
        /* 進捗バー。 */
        if (clock_timer_set > 0) {
            int bw = (int)(win_w() - 32);
            int filled = bw * clock_timer_left() / clock_timer_set;
            fb_fill_rect(x0, by + 5 * CELL_H, (uint64_t)bw, 10,
                         col_title_bg());
            fb_fill_rect(x0, by + 5 * CELL_H, (uint64_t)filled, 10,
                         acc);
        }
    } else {
        char tb[16];
        clock_fmt_hms(tb, clock_sw_elapsed(),
                      clock_sw_elapsed() >= 3600);
        fb_draw_text_aa((int64_t)x0, aa_baseline(by, 44), tb,
                        clock_sw_state == 1 ? acc : fg, (int32_t)bg,
                        44, 0);
    }
    /* タイマー / ストップウォッチ共通のボタン。 */
    const char *labels[3];
    labels[0] = (clock_tab == 2)
                    ? (clock_timer_state == 1
                           ? L("Pause", "一時停止")
                       : clock_timer_state == 2 ? L("Resume", "再開")
                                                : L("Start", "開始"))
                    : (clock_sw_state == 1 ? L("Stop", "停止")
                                           : L("Start", "開始"));
    labels[1] = L("Reset", "リセット");
    labels[2] = NULL;
    int bx = (int)x0;
    for (int i = 0; i < 2; i++) {
        int w = (int)fb_text_aa_width(labels[i], aa_px_body(), 0) + 28;
        clock_btn_x[i] = bx;
        clock_btn_w[i] = w;
        uint32_t face = i == 0 ? acc : col_title_bg();
        if (i == 1 &&
            ui_hover(bx, clock_btn_y, w, (int)CELL_H + 10)) {
            face = col_hover();
        }
        fb_fill_rect((uint64_t)bx, (uint64_t)clock_btn_y, (uint64_t)w,
                     (uint64_t)(CELL_H + 10), face);
        draw_text_small((uint64_t)(bx + 14),
                        (uint64_t)(clock_btn_y + 5), labels[i],
                        i == 0 ? rgb(0xFFFFFF) : fg, face);
        bx += w + 10;
    }
    draw_text_small(x0, y0 + (uint64_t)((text_rows() - 1) * CELL_H),
                    clock_tab == 2
                        ? L("Left/Right = field  Up/Down = value  "
                            "Space = start/pause",
                            "←→ = 欄の移動  ↑↓ = 値  Space = 開始/一時停止")
                        : L("Space = start/stop  R = reset",
                            "Space = 開始/停止  R = リセット"),
                    dim, bg);
}

static void clock_timer_toggle(void) {
    if (clock_timer_state == 1) {
        clock_timer_left_hold = clock_timer_left();
        clock_timer_state = 2;
        serial_write_line("clock: timer paused");
    } else if (clock_timer_state == 2) {
        clock_timer_end = lock_now_epoch() +
                          (uint32_t)clock_timer_left_hold;
        clock_timer_state = 1;
        serial_write_line("clock: timer resumed");
    } else if (clock_timer_set > 0) {
        clock_timer_end = lock_now_epoch() + (uint32_t)clock_timer_set;
        clock_timer_state = 1;
        serial_write_line("clock: timer started");
    }
}

static void clock_sw_toggle(void) {
    if (clock_sw_state == 1) {
        clock_sw_accum = clock_sw_elapsed();
        clock_sw_state = 0;
        serial_write_line("clock: stopwatch stopped");
    } else {
        clock_sw_start = lock_now_epoch();
        clock_sw_state = 1;
        serial_write_line("clock: stopwatch started");
    }
}

static int clock_handle_key(int c) {
    if (c == '\t') {
        clock_tab = (clock_tab + 1) % 4;
        desktop_redraw();
        return 1;
    }
    if (clock_tab == 1) {
        if (c == DESK_KEY_LEFT || c == DESK_KEY_RIGHT) {
            clock_alarm_field = clock_alarm_field == 0 ? 1 : 0;
        } else if (c == DESK_KEY_UP || c == DESK_KEY_DOWN) {
            int d = c == DESK_KEY_UP ? 1 : -1;
            if (clock_alarm_field == 0) {
                clock_alarm_h = (clock_alarm_h + d + 24) % 24;
            } else {
                clock_alarm_m = (clock_alarm_m + d + 60) % 60;
            }
        } else if (c == ' ') {
            clock_alarm_on = !clock_alarm_on;
            serial_write_line(clock_alarm_on ? "clock: alarm on"
                                             : "clock: alarm off");
        } else {
            return 0;
        }
        desktop_redraw();
        return 1;
    }
    if (clock_tab == 2) {
        if (c == ' ') {
            clock_timer_toggle();
        } else if (c == 'r' || c == 'R') {
            clock_timer_state = 0;
            serial_write_line("clock: timer reset");
        } else if (clock_timer_state == 0 &&
                   (c == DESK_KEY_LEFT || c == DESK_KEY_RIGHT)) {
            clock_timer_field = clock_timer_field == 0 ? 1 : 0;
        } else if (clock_timer_state == 0 &&
                   (c == DESK_KEY_UP || c == DESK_KEY_DOWN)) {
            int d = c == DESK_KEY_UP ? 1 : -1;
            int m = clock_timer_set / 60;
            int s = clock_timer_set % 60;
            if (clock_timer_field == 0) {
                m = (m + d + 100) % 100;
            } else {
                s = (s + d + 60) % 60;
            }
            clock_timer_set = m * 60 + s;
        } else {
            return 0;
        }
        desktop_redraw();
        return 1;
    }
    if (clock_tab == 3) {
        if (c == ' ') {
            clock_sw_toggle();
        } else if (c == 'r' || c == 'R') {
            clock_sw_state = 0;
            clock_sw_accum = 0;
            serial_write_line("clock: stopwatch reset");
        } else {
            return 0;
        }
        desktop_redraw();
        return 1;
    }
    return 0;
}

/* 通知履歴アプリ: 過去の通知を新しい順に一覧する。 */
static void draw_notiflog(void) {
    uint32_t fg = col_text();
    uint32_t bg = col_window_bg();
    uint32_t acc = col_accent();
    uint64_t x0 = text_x();
    uint64_t y0 = text_y();
    draw_text_small(x0, y0, L("Notifications", "通知履歴"), acc,
                    bg);
    int total = notify_hist_count < NOTIFY_HIST_MAX
                    ? notify_hist_count
                    : NOTIFY_HIST_MAX;
    if (total == 0) {
        draw_text_small(x0, y0 + (uint64_t)(2 * CELL_H),
                        L("(no notifications yet)",
                          "(まだ通知はありません)"),
                        col_dim(), bg);
    }
    int rows = text_rows() - 4;
    if (notif_scroll > total - 1) {
        notif_scroll = total > 0 ? total - 1 : 0;
    }
    if (notif_scroll < 0) {
        notif_scroll = 0;
    }
    for (int i = 0; i < rows && notif_scroll + i < total; i++) {
        /* 新しい順: 履歴の末尾から数える。 */
        int idx = (notify_hist_count - 1 - (notif_scroll + i)) %
                  NOTIFY_HIST_MAX;
        if (idx < 0) {
            idx += NOTIFY_HIST_MAX;
        }
        /* 種類アイコン (情報) + 時刻 + 本文 (C21)。 */
        uint64_t ry = y0 + (uint64_t)((2 + i) * CELL_H);
        fb_fill_rect(x0 + 4, ry + 2, 14, 14, acc);
        draw_text_small(x0 + 8, ry, "i", rgb(0xFFFFFF), acc);
        if (notify_hist_time[idx][0] != '\0') {
            draw_text_small(x0 + 26, ry, notify_hist_time[idx],
                            col_dim(), bg);
        }
        draw_text_small(x0 + 26 +
                            (notify_hist_time[idx][0] != '\0'
                                 ? fb_text_aa_width("00:00 ",
                                                    aa_px_body(), 0)
                                 : 0),
                        ry, notify_hist[idx], fg, bg);
    }
    /* すべて消去ボタン (C21)。 */
    if (total > 0) {
        const char *cl = L("Clear all", "すべて消去");
        uint64_t cw = fb_text_aa_width(cl, aa_px_body(), 0) + 18;
        uint64_t cx = x0 + win_w() - 16 - cw;
        notif_clear_x = (int)cx;
        notif_clear_w = (int)cw;
        uint32_t face =
            ui_hover((int)cx, (int)y0, (int)cw, (int)CELL_H - 2)
                ? col_hover()
                : col_title_bg();
        fb_fill_rect(cx, y0, cw, CELL_H - 2, face);
        draw_text_small(cx + 9, y0 - 1, cl, fg, face);
    }
    draw_text_small(x0,
                    y0 + (uint64_t)((text_rows() - 1) * CELL_H),
                    L("Up/Down = scroll  Esc = back",
                      "上下 = スクロール  Esc = 戻る"),
                    col_dim(), bg);
}

/* トーストの描画矩形 (クリック判定と共有, B7)。 */
static int notify_rx[NOTIFY_MAX];
static int notify_ry[NOTIFY_MAX];
static int notify_rw[NOTIFY_MAX];
static int notify_rh[NOTIFY_MAX];

static void draw_notifications(void) {
    uint64_t w = fb_width();
    /* ウィンドウのタイトルバー (ボタン領域) と重ならない
     * よう、少し下から積む (B7)。 */
    uint64_t y = desk_settings.taskbar_top ? TASKBAR_H + 44 : 44;
    for (int i = 0; i < NOTIFY_MAX; i++) {
        notify_rw[i] = 0;
        if (notify_ttl[i] == 0) {
            continue;
        }
        uint64_t bw = fb_text_aa_width(notify_text[i],
                                       aa_px_body(), 0) +
                      24 + 30;
        if (bw > w - 20) {
            bw = w - 20;
        }
        uint64_t bx = w - bw - 10;
        /* 高さは文字サイズに追従する (E3: 特大でも文字が
         * 枠からはみ出さない)。 */
        uint64_t th = (uint64_t)(16 * text_scale_now()) + 20;
        fb_fill_rect(bx, y, bw, th, col_taskbar());
        for (uint64_t px = bx; px < bx + bw; px++) {
            fb_put_pixel(px, y, col_accent());
            fb_put_pixel(px, y + th - 1, col_accent());
        }
        for (uint64_t py = y; py < y + th; py++) {
            fb_put_pixel(bx, py, col_accent());
            fb_put_pixel(bx + bw - 1, py, col_accent());
        }
        draw_text_small(bx + 12, y + 10, notify_text[i],
                        col_text(), col_taskbar());
        /* 閉じるボタン (×)。 */
        draw_text_small(bx + bw - 24, y + 10, "x", col_dim(),
                        col_taskbar());
        notify_rx[i] = (int)bx;
        notify_ry[i] = (int)y;
        notify_rw[i] = (int)bw;
        notify_rh[i] = (int)th;
        y += th + 6;
    }
}

/* ================= Clipboard ================= */

void desktop_clipboard_set(const char *s, size_t n) {
    if (s == NULL) {
        n = 0;
    }
    if (n > CLIP_MAX - 1) {
        n = CLIP_MAX - 1;
    }
    for (size_t i = 0; i < n; i++) {
        desk_clipboard[i] = s[i];
    }
    desk_clipboard[n] = '\0';
    desk_clipboard_len = n;
}

const char *desktop_clipboard_get(size_t *n) {
    if (n != NULL) {
        *n = desk_clipboard_len;
    }
    return desk_clipboard;
}

/* ================= Floating windows ================= */

static int win_w_of(int kind) {
    return kind == WIN_NOTES ? 460 : kind == WIN_CALC ? 240 : 300;
}
static int win_h_of(int kind) {
    return kind == WIN_NOTES ? 300 : kind == WIN_CALC ? 300 : 160;
}

static void win_open_kind(int kind) {
    if (!win_open[kind]) {
        win_open[kind] = 1;
        win_px[kind] = 120 + kind * 60;
        win_py[kind] = 110 + kind * 40;
        if (kind == WIN_NOTES) {
            notes_load();
        }
        if (kind == WIN_CALC && calc_len == 0) {
            calc_display[0] = '0';
            calc_display[1] = '\0';
            calc_len = 1;
            calc_fresh = 1;
        }
    }
    win_z[kind] = ++win_z_top;
    win_focus = kind;
    serial_write("window: opened ");
    serial_write_line(WIN_NAMES[kind]);
    desktop_redraw();
}

static void win_close(int kind) {
    if (kind == WIN_NOTES && notes_dirty) {
        notes_save();
    }
    win_open[kind] = 0;
    if (win_focus == kind) {
        win_focus = -1;
        int best = -1;
        for (int i = 0; i < WIN_COUNT; i++) {
            if (win_open[i] && (best < 0 || win_z[i] > win_z[best])) {
                best = i;
            }
        }
        win_focus = best;
    }
    serial_write("window: closed ");
    serial_write_line(WIN_NAMES[kind]);
    desktop_redraw();
}

/* The topmost open window at (x, y), or -1. */
static int win_at(int x, int y) {
    int best = -1;
    for (int i = 0; i < WIN_COUNT; i++) {
        if (!win_open[i]) {
            continue;
        }
        if (x >= win_px[i] && x < win_px[i] + win_w_of(i) &&
            y >= win_py[i] && y < win_py[i] + win_h_of(i)) {
            if (best < 0 || win_z[i] > win_z[best]) {
                best = i;
            }
        }
    }
    return best;
}

static int64_t calc_parse(void) {
    int64_t v = 0;
    int neg = 0;
    int i = 0;
    if (calc_display[0] == '-') {
        neg = 1;
        i = 1;
    }
    for (; calc_display[i] != '\0'; i++) {
        if (calc_display[i] >= '0' && calc_display[i] <= '9') {
            v = v * 10 + (calc_display[i] - '0');
        }
    }
    return neg ? -v : v;
}

static void calc_show(int64_t v) {
    char tmp[24];
    int n = 0;
    int neg = 0;
    uint64_t u;
    if (v < 0) {
        neg = 1;
        u = (uint64_t)(-(v + 1)) + 1;
    } else {
        u = (uint64_t)v;
    }
    if (u == 0) {
        tmp[n++] = '0';
    }
    while (u > 0) {
        tmp[n++] = (char)('0' + (u % 10));
        u /= 10;
    }
    int p = 0;
    if (neg) {
        calc_display[p++] = '-';
    }
    while (n > 0) {
        calc_display[p++] = tmp[--n];
    }
    calc_display[p] = '\0';
    calc_len = p;
}

static void calc_apply(void) {
    int64_t v = calc_parse();
    if (calc_op == 0) {
        calc_acc = v;
        return;
    }
    switch (calc_op) {
    case '+': calc_acc += v; break;
    case '-': calc_acc -= v; break;
    case '*': calc_acc *= v; break;
    case '/':
        if (v == 0) {
            calc_show(0);
            calc_len = 3;
            calc_display[0] = 'E';
            calc_display[1] = 'r';
            calc_display[2] = 'r';
            calc_display[3] = '\0';
            calc_op = 0;
            calc_fresh = 1;
            return;
        }
        calc_acc /= v;
        break;
    }
}

static void calc_input(int c) {
    if (c >= '0' && c <= '9') {
        if (calc_fresh || calc_len == 0 ||
            (calc_len == 1 && calc_display[0] == '0')) {
            calc_len = 0;
            calc_fresh = 0;
        }
        if (calc_len + 1 < (int)sizeof(calc_display)) {
            calc_display[calc_len++] = (char)c;
            calc_display[calc_len] = '\0';
        }
        return;
    }
    if (c == '+' || c == '-' || c == '*' || c == '/') {
        if (!calc_fresh) {
            calc_apply();
        }
        calc_op = c;
        calc_fresh = 1;
        calc_show(calc_acc);
        return;
    }
    if (c == '=' || c == '\n' || c == '\r') {
        if (calc_op != 0) {
            calc_apply();
            calc_op = 0;
        } else {
            calc_acc = calc_parse();
        }
        calc_fresh = 1;
        calc_show(calc_acc);
        serial_write("calc: result ");
        serial_write_line(calc_display);
        return;
    }
    if (c == 'c' || c == 'C') {
        calc_acc = 0;
        calc_op = 0;
        calc_fresh = 1;
        calc_show(0);
        return;
    }
    if (c == '\b' || c == 0x7F) {
        if (!calc_fresh && calc_len > 0) {
            calc_display[--calc_len] = '\0';
            if (calc_len == 0) {
                calc_show(0);
                calc_fresh = 1;
            }
        }
        return;
    }
}

/* One key for the focused window. Returns 1 if consumed. */
static int win_key(int kind, int c) {
    if (kind == WIN_CALC) {
        calc_input(c);
        desktop_redraw();
        return 1;
    }
    if (kind == WIN_NOTES) {
        if (c == 0xA2) { /* Ctrl+V: paste */
            size_t n = 0;
            const char *clip = desktop_clipboard_get(&n);
            for (size_t i = 0; i < n; i++) {
                if (notes_len + 1 < PRISM_VFS_MAX_APP_FILE_SIZE) {
                    /* insert at cursor */
                    for (size_t j = notes_len; j > notes_cursor; j--) {
                        notes_buf[j] = notes_buf[j - 1];
                    }
                    notes_buf[notes_cursor++] = clip[i];
                    notes_len++;
                    notes_buf[notes_len] = '\0';
                    notes_dirty = 1;
                }
            }
            desktop_redraw();
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            if (notes_cursor > 0) {
                for (size_t j = notes_cursor - 1; j + 1 < notes_len; j++) {
                    notes_buf[j] = notes_buf[j + 1];
                }
                notes_cursor--;
                notes_len--;
                notes_buf[notes_len] = '\0';
                notes_dirty = 1;
            }
            desktop_redraw();
            return 1;
        }
        if (c >= 32 && c < 127) {
            if (notes_len + 1 < PRISM_VFS_MAX_APP_FILE_SIZE) {
                for (size_t j = notes_len; j > notes_cursor; j--) {
                    notes_buf[j] = notes_buf[j - 1];
                }
                notes_buf[notes_cursor++] = (char)c;
                notes_len++;
                notes_buf[notes_len] = '\0';
                notes_dirty = 1;
            }
            desktop_redraw();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (notes_len + 1 < PRISM_VFS_MAX_APP_FILE_SIZE) {
                for (size_t j = notes_len; j > notes_cursor; j--) {
                    notes_buf[j] = notes_buf[j - 1];
                }
                notes_buf[notes_cursor++] = '\n';
                notes_len++;
                notes_buf[notes_len] = '\0';
                notes_dirty = 1;
            }
            desktop_redraw();
            return 1;
        }
        return 1; /* other keys in a focused window: consumed */
    }
    return 1; /* clock window: any key is consumed except Esc
                 (handled by the caller) */
}

/* ウィンドウの表示名 (言語切替つき)。WIN_NAMES は
 * ログ用に英語のまま残す。 */
static const char *win_name(int kind) {
    switch (kind) {
        case WIN_NOTES:
            return L("Notes", "メモ");
        case WIN_CALC:
            return L("Calculator", "電卓");
        default:
            return L("Clock", "時計");
    }
}

static void draw_window_frame(int kind) {
    int x = win_px[kind];
    int y = win_py[kind];
    int w = win_w_of(kind);
    int h = win_h_of(kind);
    uint32_t bg = col_window_bg();
    uint32_t title = win_focus == kind ? col_accent() : col_taskbar();
    if (ui_shadow_pass) {
        fb_shadow_round_rect(x, y, w, h, UI_R_WIN, 3);
    }
    fb_fill_round_rect(x, y, w, h, UI_R_WIN, bg);
    fb_fill_clipped_rrect(x, y, w, 24, x, y, w, h, UI_R_WIN, title);
    draw_text_small((uint64_t)(x + 8), (uint64_t)(y + 8), win_name(kind),
                    rgb(0xFFFFFF), title);
    /* 閉じる箱: 通常はタイトルバーに溶け込み、ホバーで
     * 赤くなる。× は線で描く。 */
    {
        int hover = mouse_x >= x + w - 24 && mouse_x < x + w &&
                    mouse_y >= y && mouse_y < y + 24;
        uint32_t cfill = hover ? rgb(0xC0392B) : title;
        uint32_t cglyph = hover ? rgb(0xFFFFFF) : col_text();
        fb_fill_clipped_rrect(x + w - 24, y, 24, 24, x, y, w, h,
                              UI_R_WIN, cfill);
        int64_t gx = (int64_t)(x + w) - 12;
        int64_t gy = (int64_t)y + 12;
        fb_draw_line(gx - 4, gy - 4, gx + 4, gy + 4, cglyph);
        fb_draw_line(gx - 4, gy + 4, gx + 4, gy - 4, cglyph);
    }
    /* Border. */
    fb_stroke_round_rect(x, y, w, h, UI_R_WIN, col_border());
    if (kind == WIN_NOTES) {
        /* Show the last lines of the notes buffer. */
        int lines = (h - 40) / CELL_H;
        int cols = (w - 16) / CELL_W;
        /* Find the start of the visible tail. */
        size_t pos = notes_len;
        int up = lines;
        while (pos > 0 && up > 0) {
            pos--;
            if (notes_buf[pos] == '\n') {
                up--;
            }
        }
        if (pos > 0 && notes_buf[pos - 1] != '\n' && pos < notes_len) {
            /* mid-line start: fine for a preview window */
        }
        int row = 0;
        int col = 0;
        for (size_t i = pos; i < notes_len && row < lines; i++) {
            char ch = notes_buf[i];
            if (ch == '\n') {
                row++;
                col = 0;
                continue;
            }
            if (col >= cols) {
                row++;
                col = 0;
                if (row >= lines) {
                    break;
                }
            }
            fb_draw_char((uint64_t)(x + 8 + col * CELL_W),
                         (uint64_t)(y + 32 + row * CELL_H), ch,
                         col_text(), bg, TEXT_SCALE);
            col++;
        }
    } else if (kind == WIN_CALC) {
        fb_fill_rect((uint64_t)(x + 12), (uint64_t)(y + 36),
                     (uint64_t)(w - 24), 28, col_taskbar());
        size_t dl = strlen(calc_display);
        draw_text_small((uint64_t)(x + w - 20 - (int)dl * 6),
                        (uint64_t)(y + 46), calc_display, col_text(),
                        col_taskbar());
        draw_text_small((uint64_t)(x + 12), (uint64_t)(y + 76),
                        L("Keys: 0-9 + - * / = C", "キー: 0-9 + - * / = C"), col_dim(), bg);
        draw_text_small((uint64_t)(x + 12), (uint64_t)(y + 92),
                        L("Enter = result", "Enter = 結果"), col_dim(), bg);
    } else {
        draw_text_small((uint64_t)(x + 16), (uint64_t)(y + 48),
                        clock_text, col_text(), bg);
        prism_rtc_time t;
        if (rtc_read(&t) == 0) {
            char dbuf[24];
            int p = 0;
            int yr = t.year;
            int mo = t.month;
            int dy = t.day;
            dbuf[p++] = (char)('0' + (yr / 1000) % 10);
            dbuf[p++] = (char)('0' + (yr / 100) % 10);
            dbuf[p++] = (char)('0' + (yr / 10) % 10);
            dbuf[p++] = (char)('0' + yr % 10);
            dbuf[p++] = '-';
            dbuf[p++] = (char)('0' + (mo / 10) % 10);
            dbuf[p++] = (char)('0' + mo % 10);
            dbuf[p++] = '-';
            dbuf[p++] = (char)('0' + (dy / 10) % 10);
            dbuf[p++] = (char)('0' + dy % 10);
            dbuf[p] = '\0';
            draw_text_small((uint64_t)(x + 16), (uint64_t)(y + 68),
                            dbuf, col_dim(), bg);
        }
    }
}

static void draw_windows(void) {
    if (desk_mode != DESK_TERMINAL) {
        return;
    }
    /* Draw from the back to the front. */
    for (int z = 0; z <= win_z_top; z++) {
        for (int i = 0; i < WIN_COUNT; i++) {
            if (win_open[i] && win_z[i] == z) {
                draw_window_frame(i);
            }
        }
    }
}

/* ================= Launcher ================= */

/* ================= 電源メニューとロック画面 =================
 * ランチャーの末尾に電源項目 (ロック/ユーザー切替/スリープ/
 * 再起動/シャットダウン) を出す。処理はシェルの power /
 * sleep / poweroff / lock と同じ部品 (acpi_poweroff、
 * acpi_enter_s3、shell_reboot_now、account_verify +
 * bio_verify) に接続する。ユーザー切替はシェルのログイン
 * フローへ戻る (shell_request_user_switch)。 */

static int desk_locked;
static char lock_buf[17];
static int lock_len;
static int lock_failed;
/* ロック画面の試行制限 (監査 M3)。ログインと同じ政策
 * (lockout_attempts 回の連続失敗で lockout_seconds 秒の
 * 待ち。秒数が 0 なら停止) を適用し、失敗は監査に残す。
 * 以前は無制限・無記録に試せた。 */
static int lock_wrong;
static uint32_t lock_wait_until; /* 待ちの終わる epoch 秒。0 = 待ちなし */

static uint32_t lock_now_epoch(void) {
    prism_rtc_time t;
    if (rtc_read(&t) != 0) {
        return 0;
    }
    return rtc_epoch_seconds(&t);
}

static int lock_waiting(void) {
    return lock_wait_until != 0 &&
           lock_now_epoch() < lock_wait_until;
}

/* 2 桁 / 4 桁のゼロ詰め数値 (ロック画面の日付用)。 */
static size_t lock_put2(char *dst, unsigned v) {
    dst[0] = (char)('0' + (v / 10) % 10);
    dst[1] = (char)('0' + v % 10);
    return 2;
}

static size_t lock_put4(char *dst, unsigned v) {
    dst[0] = (char)('0' + (v / 1000) % 10);
    dst[1] = (char)('0' + (v / 100) % 10);
    dst[2] = (char)('0' + (v / 10) % 10);
    dst[3] = (char)('0' + v % 10);
    return 4;
}

/* テキストを中央そろえで描く (ロック画面用)。 */
static void lock_draw_centered(uint64_t cx, uint64_t y,
                               const char *s, uint32_t fg,
                               uint32_t bg, int unit) {
    /* unit は従来のビットマップ倍率。AA では px に読み替え、
     * 計測と描画を同じ実アドバンスでそろえる。 */
    int px = unit >= 4 ? 56 : unit >= 2 ? 28 : aa_px_body();
    uint64_t tw = fb_text_aa_width(s, px, 0);
    fb_draw_text_aa(cx - tw / 2, aa_baseline(y, px), s, fg,
                    (int32_t)bg, px, 0);
}

static void draw_lock_screen(void) {
    uint64_t w = fb_width();
    uint64_t h = fb_height();
    /* 背景は壁紙。その上に中央パネルを置く (A4)。 */
    draw_wallpaper();
    const uint32_t panel = rgb(0x10182E);
    const uint32_t field = rgb(0x0A0F22);
    uint64_t pw = 520;
    uint64_t ph = 470;
    uint64_t px = (w - pw) / 2;
    uint64_t py = (h - ph) / 2;
    uint64_t cx = px + pw / 2;
    /* パネルは角丸 + 影 + 1px 輪郭 (T3/T8)。壁紙はこの
     * 関数が毎回描き直すので影は蓄積しない。 */
    fb_shadow_round_rect((int64_t)px, (int64_t)py, (int64_t)pw,
                         (int64_t)ph, UI_R_WIN, 6);
    fb_fill_round_rect((int64_t)px, (int64_t)py, (int64_t)pw,
                       (int64_t)ph, UI_R_WIN, panel);
    fb_stroke_round_rect((int64_t)px, (int64_t)py, (int64_t)pw,
                         (int64_t)ph, UI_R_WIN, col_border());

    /* 大きな時計と日付。 */
    prism_rtc_time t;
    if (rtc_read(&t) == 0) {
        unsigned year_full = 2000u + t.year; /* RTC の年は 2000+年 */
        char clock[8];
        clock[0] = (char)('0' + (t.hour / 10) % 10);
        clock[1] = (char)('0' + t.hour % 10);
        clock[2] = ':';
        clock[3] = (char)('0' + (t.minute / 10) % 10);
        clock[4] = (char)('0' + t.minute % 10);
        clock[5] = '\0';
        lock_draw_centered(cx, py + 26, clock, rgb(0xFFFFFF), panel,
                           4);
        char date[64];
        size_t p = 0;
        p += lock_put4(date + p, year_full);
        date[p++] = '-';
        p += lock_put2(date + p, t.month);
        date[p++] = '-';
        p += lock_put2(date + p, t.day);
        date[p] = '\0';
        if (desk_settings.language) {
            /* 年月日と曜日に組み直す。 */
            char ja[64];
            size_t q = 0;
            q += lock_put4(ja + q, year_full);
            const char *nen = "年";
            while (*nen != '\0') {
                ja[q++] = *nen++;
            }
            q += lock_put2(ja + q, t.month);
            const char *getsu = "月";
            while (*getsu != '\0') {
                ja[q++] = *getsu++;
            }
            q += lock_put2(ja + q, t.day);
            const char *nichi = "日";
            while (*nichi != '\0') {
                ja[q++] = *nichi++;
            }
            ja[q++] = ' ';
            static const char *const wd_ja[7] = {
                "(日)", "(月)", "(火)", "(水)", "(木)", "(金)", "(土)"
            };
            const char *wd = wd_ja[t.weekday % 7];
            while (*wd != '\0') {
                ja[q++] = *wd++;
            }
            ja[q] = '\0';
            lock_draw_centered(cx, py + 96, ja, rgb(0xC8D2E0),
                               panel, 1);
        } else {
            static const char *const wd_en[7] = {
                "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"
            };
            char en[72];
            size_t q = 0;
            const char *wd = wd_en[t.weekday % 7];
            while (*wd != '\0') {
                en[q++] = *wd++;
            }
            en[q++] = ' ';
            size_t d = 0;
            while (date[d] != '\0') {
                en[q++] = date[d++];
            }
            en[q] = '\0';
            lock_draw_centered(cx, py + 96, en, rgb(0xC8D2E0),
                               panel, 1);
        }
    }

    /* ユーザーアイコン (円 + 頭文字) と名前。 */
    const char *user = shell_current_user_name();
    {
        uint64_t av = 64;
        uint64_t ax = cx - av / 2;
        uint64_t ay = py + 140;
        for (int dy = -(int)av / 2; dy <= (int)av / 2; dy++) {
            int span = 0;
            int r = (int)av / 2;
            while ((span + 1) * (span + 1) + dy * dy <= r * r) {
                span++;
            }
            fb_fill_rect(cx - (uint64_t)span,
                         (uint64_t)((int64_t)(ay + av / 2) + dy),
                         (uint64_t)(2 * span + 1), 1, col_accent());
        }
        char init[2] = { user[0], '\0' };
        if (init[0] >= 'a' && init[0] <= 'z') {
            init[0] = (char)(init[0] - 'a' + 'A');
        }
        uint64_t tw = fb_text_aa_width(init, 28, 1);
        fb_draw_text_aa(cx - tw / 2, aa_baseline(ay + 16, 28),
                        init, rgb(0x0A0F22), (int32_t)col_accent(),
                        28, 1);
        (void)ax;
    }
    lock_draw_centered(cx, py + 222, user, rgb(0xFFFFFF), panel, 1);
    lock_draw_centered(cx, py + 248,
                       L("Locked", "ロック中"), rgb(0x9AA7BD),
                       panel, 1);

    /* PIN 入力欄 (枠 + ドット)。 */
    uint64_t bw = 280;
    uint64_t bx = cx - bw / 2;
    uint64_t by = py + 292;
    fb_fill_round_rect((int64_t)bx, (int64_t)by, (int64_t)bw, 44,
                       UI_R_CTL, field);
    fb_stroke_round_rect((int64_t)bx, (int64_t)by, (int64_t)bw, 44,
                         UI_R_CTL, col_accent());
    {
        char dots[20];
        int n = lock_len;
        if (n > 16) {
            n = 16;
        }
        for (int i = 0; i < n; i++) {
            dots[i] = '*';
        }
        dots[n] = '\0';
        if (n > 0) {
            lock_draw_centered(cx, by + 12, dots, rgb(0xFFFFFF),
                               field, 1);
        }
    }

    /* メッセージとヒント。 */
    if (lock_waiting()) {
        lock_draw_centered(cx, py + 356,
                           L("Too many attempts. Locked for a while.",
                             "試行回数が多すぎます。しばらくロックされます"),
                           rgb(0xFF8080), panel, 1);
    } else if (lock_failed) {
        lock_draw_centered(cx, py + 356,
                           L("Wrong PIN.", "PINが違います"),
                           rgb(0xFF8080), panel, 1);
    }
    lock_draw_centered(cx, py + 392,
                       L("Type your PIN and press Enter",
                         "PINを入力してEnter"),
                       rgb(0x8A94A6), panel, 1);
    if (bio_enrolled(BIO_TYPE_FINGER) || bio_enrolled(BIO_TYPE_FACE)) {
        lock_draw_centered(cx, py + 420,
                           L("Tab = use biometrics",
                             "Tab = 生体認証を使う"),
                           rgb(0x8A94A6), panel, 1);
    }
}

/* ロック中のキー処理。シェルの lock と同じ照合
 * (主アカウントの PIN、または生体認証) で解除する。 */
static int lock_key(int c) {
    if (c == '\t' &&
        (bio_enrolled(BIO_TYPE_FINGER) || bio_enrolled(BIO_TYPE_FACE))) {
        int rc = -3;
        if (bio_enrolled(BIO_TYPE_FINGER)) {
            rc = bio_verify(BIO_TYPE_FINGER);
        }
        if (rc != 0 && bio_enrolled(BIO_TYPE_FACE)) {
            rc = bio_verify(BIO_TYPE_FACE);
        }
        if (rc == 0) {
            desk_locked = 0;
            lock_len = 0;
            lock_buf[0] = '\0';
            lock_failed = 0;
            lock_wrong = 0;
            lock_wait_until = 0;
            audit_log_event("unlock", "biometrics accepted");
            serial_write_line("desktop: unlocked (biometrics)");
        } else {
            lock_failed = 1;
            serial_write_line("desktop: biometric unlock failed");
        }
        desktop_redraw();
        return 1;
    }
    if (c == '\n' || c == '\r') {
        lock_buf[lock_len] = '\0';
        if (lock_wait_until != 0 && !lock_waiting()) {
            /* 待ち時間が過ぎた。失敗回数を数え直す。 */
            lock_wait_until = 0;
            lock_wrong = 0;
        }
        if (lock_waiting()) {
            /* ロックアウト中は照合自体をしない。 */
            lock_failed = 1;
            serial_write_line("desktop: unlock refused (lockout)");
            lock_len = 0;
            lock_buf[0] = '\0';
            desktop_redraw();
            return 1;
        }
        size_t len = 0;
        const char *text = vfs_read_ptr(PRISM_ACCOUNT_FILE, &len);
        if (text != NULL && account_verify(lock_buf, text, len) == 1) {
            desk_locked = 0;
            lock_wrong = 0;
            lock_wait_until = 0;
            bio_unlock_reset();
            audit_log_event("unlock", "PIN accepted");
            serial_write_line("desktop: unlocked");
        } else {
            lock_failed = 1;
            /* シェルの lock と同じく失敗を監査に残す (監査 M3)。 */
            audit_log_event("unlock-fail",
                            "wrong PIN at lock screen");
            serial_write_line("desktop: unlock failed");
            lock_wrong++;
            int attempts = desk_settings.lockout_attempts;
            if (attempts < 1) {
                attempts = 1;
            }
            if (attempts > 10) {
                attempts = 10;
            }
            if (lock_wrong >= attempts) {
                audit_log_event(
                    "lockout", "too many wrong PINs at lock screen");
                if (desk_settings.lockout_seconds > 0) {
                    lock_wait_until =
                        lock_now_epoch() +
                        (uint32_t)desk_settings.lockout_seconds;
                    lock_wrong = 0;
                    serial_write_line("desktop: lock screen locked out");
                } else {
                    /* 秒数 0 = 回数を超えたら止まる (設定の
                     * 取り決め。ログインとシェルの lock に同じ)。 */
                    serial_write_line(
                        "desktop: too many unlock attempts, halting");
                    prism_halt();
                }
            }
        }
        lock_len = 0;
        lock_buf[0] = '\0';
        desktop_redraw();
        return 1;
    }
    if (c == '\b' || c == 0x7F) {
        if (lock_len > 0) {
            lock_len--;
            lock_buf[lock_len] = '\0';
        }
        desktop_redraw();
        return 1;
    }
    if (c >= 32 && c < 127 && lock_len < 16) {
        lock_buf[lock_len++] = (char)c;
        lock_buf[lock_len] = '\0';
        lock_failed = 0;
        desktop_redraw();
        return 1;
    }
    return 1; /* ロック中は他のキーをすべて消費する */
}

static void power_action(int which) {
    switch (which) {
        case 0: { /* ロック */
            size_t len = 0;
            const char *text = vfs_read_ptr(PRISM_ACCOUNT_FILE, &len);
            if (text == NULL && !bio_enrolled(BIO_TYPE_FINGER) &&
                !bio_enrolled(BIO_TYPE_FACE)) {
                desktop_notify(L("No PIN set: lock unavailable",
                                 "PINが未設定のためロックできません"));
                serial_write_line("power: lock unavailable (no PIN)");
                return;
            }
            desk_locked = 1;
            lock_len = 0;
            lock_buf[0] = '\0';
            lock_failed = 0;
            lock_wrong = 0;
            lock_wait_until = 0;
            audit_log_event("lock", "screen locked from desktop");
            serial_write_line("desktop: locked");
            break;
        }
        case 1: /* ユーザー切替 */
            serial_write_line("desktop: switch user");
            persist_maybe_sync();
            shell_request_user_switch();
            break;
        case 2: /* スリープ */
            if (acpi_s3_available()) {
                serial_write_line("desktop: entering S3 sleep");
                if (acpi_enter_s3() == 0) {
                    serial_write_line("desktop: resumed from S3");
                }
            } else {
                desktop_notify(L("Sleep is not available here",
                                 "このマシンではスリープできません"));
                serial_write_line("desktop: sleep unavailable");
            }
            break;
        case 3: /* 再起動 */
            serial_write_line("desktop: restart");
            persist_maybe_sync();
            shell_reboot_now();
            break;
        default: /* シャットダウン */
            serial_write_line("desktop: shutdown");
            persist_maybe_sync();
            (void)acpi_poweroff();
            /* ここに来るのは電源を切れなかった場合だけ。 */
            desktop_notify(L("Could not shut down",
                             "シャットダウンできませんでした"));
            serial_write_line("desktop: poweroff failed");
            break;
    }
    desktop_redraw();
}

#define LAUNCH_COLS 6
/* タイル幅は最長ラベル (全角 6 文字 = 144px) が 1 行に
 * 収まる幅にする (T6: ラベルを単語の途中で割らない)。 */
#define LAUNCH_CELL_W 152
#define LAUNCH_CELL_H 84
#define LAUNCH_GAP 10
#define LAUNCH_PAD 24 /* パネル余白 (T6) */
#define LAUNCH_SEARCH_H 32
/* 検索欄 + 間隔 + 見出し分 (グリッドより上の高さ)。 */
#define LAUNCH_HEAD_H (LAUNCH_SEARCH_H + 12 + 18 + 6)

#define POWER_COUNT 5
#define WIDGETS_COUNT 1
/* フッター (ユーザー表示 + 電源ボタン) の高さ (B8)。 */
#define LAUNCH_FOOT_H 44

/* 電源メニューの状態 (B8): ボタンにフォーカスがあるか、
 * メニューが開いているか、選択中の項目。 */
static int launcher_power_focus;
static int launcher_power_open;
static int launcher_power_sel;

static int launcher_entries(void) {
    return desk_visible_count() + WIN_COUNT + WIDGETS_COUNT;
}

static const char *power_label(int i) {
    switch (i) {
        case 0:
            return L("Lock", "ロック");
        case 1:
            return L("Switch user", "ユーザー切替");
        case 2:
            return L("Sleep", "スリープ");
        case 3:
            return L("Restart", "再起動");
        default:
            return L("Shut down", "シャットダウン");
    }
}

static void launcher_geometry(int *pw, int *ph, int *px, int *py) {
    int rows = (launcher_entries() + LAUNCH_COLS - 1) / LAUNCH_COLS;
    *pw = LAUNCH_PAD * 2 + LAUNCH_COLS * LAUNCH_CELL_W +
          (LAUNCH_COLS - 1) * LAUNCH_GAP;
    *ph = LAUNCH_PAD * 2 + LAUNCH_HEAD_H + rows * LAUNCH_CELL_H +
          (rows - 1) * LAUNCH_GAP + LAUNCH_FOOT_H;
    *px = ((int)fb_width() - *pw) / 2;
    /* パネルはタスクバーのすぐ上に寄せる (縦タスクバーの
     * ときは画面中央)。 */
    if (taskbar_vertical()) {
        *py = ((int)fb_height() - *ph) / 2;
    } else if (desk_settings.taskbar_top) {
        *py = TASKBAR_H + 10;
    } else {
        int dock = desk_settings.dock_show &&
                           desk_settings.dock_pos == 0
                       ? DOCK_H
                       : 0;
        *py = (int)fb_height() - TASKBAR_H - dock - 10 - *ph;
    }
    /* 動き: 開閉中は下へずらす (描画・当たり判定共通)。 */
    *py += launcher_anim_dy();
}

static int64_t launch_cell_x(int px, int i) {
    return px + LAUNCH_PAD +
           (i % LAUNCH_COLS) * (LAUNCH_CELL_W + LAUNCH_GAP);
}

static int64_t launch_cell_y(int py, int i) {
    return py + LAUNCH_PAD + LAUNCH_HEAD_H +
           (i / LAUNCH_COLS) * (LAUNCH_CELL_H + LAUNCH_GAP);
}

/* 小フォントの表示幅の目安: ASCII は 6px、それ以外の
 * 文字は 12px として数える (ラベルの中央寄せ用)。 */
static int small_text_w(const char *s) {
    int w = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (((uint8_t)s[i] & 0xC0) != 0x80) {
            w += ((uint8_t)s[i] < 0x80) ? 6 : 12;
        }
    }
    return w;
}

/* スタートメニュー上部の検索欄のヒットテスト。 */
static int launcher_search_at(int x, int y) {
    int pw, ph, px, py;
    launcher_geometry(&pw, &ph, &px, &py);
    (void)ph;
    return x >= px + LAUNCH_PAD && x < px + pw - LAUNCH_PAD &&
           y >= py + LAUNCH_PAD &&
           y < py + LAUNCH_PAD + LAUNCH_SEARCH_H;
}

static const char *launcher_label(int idx, desktop_mode *app_out) {
    int apps = desk_visible_count();
    if (idx < apps) {
        *app_out = desk_visible_mode(idx);
        return mode_name(*app_out);
    }
    *app_out = DESK_TERMINAL;
    if (idx < apps + WIN_COUNT) {
        /* 小型ウィンドウのタイルはアプリと同名だと行き先が
         * 分からないため、スタート上だけ別名にする (B3)。 */
        int kind = idx - apps;
        if (kind == WIN_NOTES) {
            return L("Quick Notes", "クイックメモ");
        }
        if (kind == WIN_CLOCK) {
            return L("Mini Clock", "ミニ時計");
        }
        return win_name(kind);
    }
    return L("Widgets", "ウィジェット");
}

/* 電源ボタンの矩形 (パネルフッター右端)。 */
static void launcher_power_btn_rect(int *bx, int *by, int *bw,
                                    int *bh) {
    int pw, ph, px, py;
    launcher_geometry(&pw, &ph, &px, &py);
    *bw = 120;
    *bh = 32;
    *bx = px + pw - LAUNCH_PAD - *bw;
    *by = py + ph - LAUNCH_FOOT_H + 6;
}

/* 展開した電源メニューの行のヒットテスト。 */
static int launcher_power_row_at(int x, int y) {
    if (!launcher_power_open) {
        return -1;
    }
    int bx, by, bw, bh;
    launcher_power_btn_rect(&bx, &by, &bw, &bh);
    int mw = 190;
    int mx = bx + bw - mw;
    int mh = POWER_COUNT * 28 + 8;
    int my = by - 6 - mh;
    if (x < mx || x >= mx + mw || y < my + 4 ||
        y >= my + mh - 4) {
        return -1;
    }
    int row = (y - my - 4) / 28;
    return row >= 0 && row < POWER_COUNT ? row : -1;
}

static int launcher_power_btn_at(int x, int y) {
    int bx, by, bw, bh;
    launcher_power_btn_rect(&bx, &by, &bw, &bh);
    return x >= bx && x < bx + bw && y >= by && y < by + bh;
}

static void widgets_open_panel(void);

static void launcher_activate(int idx) {
    int apps = desk_visible_count();
    launcher_active = 0;
    launcher_closing = 0;
    if (idx < apps) {
        desktop_mode app = desk_visible_mode(idx);
        serial_write("launcher: ");
        serial_write_line(mode_name(app));
        switch_mode(app);
    } else if (idx < apps + WIN_COUNT) {
        win_open_kind(idx - apps);
    } else if (idx == apps + WIN_COUNT) {
        widgets_open_panel();
    }
    desktop_redraw();
}

/* ---- デスクトップウィジェット (バッチ4 項目21) ----
 * ランチャーから開くパネル。カレンダーは RTC の
 * ローカルデータ、天気・ニュースは設定で指定した
 * URL のプレーンテキストフィードから取る。 */
static int widgets_open;
static char widgets_weather[3][56];
static int widgets_weather_count;
static int widgets_weather_state; /* 0=未設定 1=ok -1=失敗 */
static char widgets_news[5][56];
static int widgets_news_count;
static int widgets_news_state;
static char widgets_buf[8192];

/* フィード本文を行に分解する (タグは読み飛ばす)。 */
static void widgets_set_lines(const char *body, size_t len,
                              char lines[][56], int max_lines,
                              int *out_count) {
    int count = 0;
    size_t i = 0;
    while (i < len && count < max_lines) {
        /* 行頭の空白と空行を飛ばす。 */
        while (i < len &&
               (body[i] == ' ' || body[i] == '\t' ||
                body[i] == '\r' || body[i] == '\n')) {
            i++;
        }
        if (i >= len) {
            break;
        }
        if (body[i] == '<') {
            /* タグは次の '>' まで読み飛ばす。 */
            while (i < len && body[i] != '>') {
                i++;
            }
            if (i < len) {
                i++;
            }
            continue;
        }
        size_t p = 0;
        while (i < len && body[i] != '\n' && body[i] != '\r' &&
               body[i] != '<') {
            if (p + 1 < 56) {
                lines[count][p++] = body[i];
            }
            i++;
        }
        /* 行末の空白を落とす。 */
        while (p > 0 && lines[count][p - 1] == ' ') {
            p--;
        }
        lines[count][p] = '\0';
        if (p > 0) {
            count++;
        }
    }
    *out_count = count;
}

static int widgets_fetch_one(const char *url, char lines[][56],
                             int max_lines, int *out_count) {
    if (url[0] == '\0') {
        *out_count = 0;
        return 0;
    }
    size_t len = 0;
    int status = 0;
    char final_url[256];
    if (br_fetch_buf(url, widgets_buf, sizeof(widgets_buf), &len,
                     &status, final_url, sizeof(final_url)) != 0) {
        *out_count = 0;
        return -1;
    }
    widgets_set_lines(widgets_buf, len, lines, max_lines, out_count);
    return 1;
}

static void widgets_fetch(void) {
    widgets_weather_state = widgets_fetch_one(
        desk_settings.feed_weather, widgets_weather, 3,
        &widgets_weather_count);
    serial_write_line(widgets_weather_state == 1
                          ? "widgets: weather ok"
                          : (widgets_weather_state == 0
                                 ? "widgets: weather not set"
                                 : "widgets: weather failed"));
    widgets_news_state = widgets_fetch_one(
        desk_settings.feed_news, widgets_news, 5,
        &widgets_news_count);
    serial_write_line(widgets_news_state == 1
                          ? "widgets: news ok"
                          : (widgets_news_state == 0
                                 ? "widgets: news not set"
                                 : "widgets: news failed"));
}

static void widgets_open_panel(void) {
    widgets_open = 1;
    widgets_fetch();
    serial_write_line("widgets: opened");
}

/* 「設定を開く」ボタンの矩形 (天気/ニュースの未設定時)。 */
static int widgets_btn_y[2];

static void draw_widgets(void) {
    widgets_btn_y[0] = -1;
    widgets_btn_y[1] = -1;
    if (!widgets_open) {
        return;
    }
    uint64_t px = 8;
    uint64_t py = 56;
    uint64_t pw = 440;
    uint64_t ph = fb_height() - DOCK_H - 64;
    fb_fill_rect_alpha(px, py, pw, ph, col_taskbar(), 232);
    uint32_t fg = col_text();
    uint32_t bg = col_taskbar();
    uint32_t acc = col_accent();
    uint64_t x = px + 14;
    uint64_t y = py + 12;
    draw_text_small(x, y, L("Widgets", "ウィジェット"), acc, bg);
    y += CELL_H + 6;
    fb_fill_rect(x, y - 4, pw - 28, 1, col_dim());
    /* カレンダー (RTC のローカルデータ)。セルは文字セル
     * より大きいピッチで並べる (B5)。 */
    prism_rtc_time t;
    if (rtc_read(&t) == 0) {
        int year = 2000 + t.year;
        int month = t.month;
        char title[32];
        size_t tp = 0;
        title[tp++] = (char)('0' + (year / 1000) % 10);
        title[tp++] = (char)('0' + (year / 100) % 10);
        title[tp++] = (char)('0' + (year / 10) % 10);
        title[tp++] = (char)('0' + year % 10);
        title[tp++] = '/';
        title[tp++] = (char)('0' + (month / 10) % 10);
        title[tp++] = (char)('0' + month % 10);
        title[tp] = '\0';
        draw_text_small(x, y, title, fg, bg);
        y += CELL_H + 2;
        static const char *const wd_en[7] = {
            "Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"};
        static const char *const wd_ja[7] = {
            "日", "月", "火", "水", "木", "金", "土"};
        for (int i = 0; i < 7; i++) {
            draw_text_small(x + (uint64_t)i * 38 + 4, y,
                            desk_settings.language ? wd_ja[i]
                                                   : wd_en[i],
                            col_dim(), bg);
        }
        y += CELL_H + 2;
        int first = rtc_weekday(year, month, 1);
        int days = rtc_days_in_month(year, month);
        int cell = 0;
        for (int d = 1; d <= days; d++) {
            int pos = first + d - 1;
            int cx = (int)x + (pos % 7) * 38;
            int cy = (int)y + (pos / 7) * (int)(CELL_H + 4);
            char db[4];
            db[0] = d >= 10 ? (char)('0' + d / 10) : ' ';
            db[1] = (char)('0' + d % 10);
            db[2] = '\0';
            if (d == t.day) {
                fb_fill_rect((uint64_t)cx, (uint64_t)cy, 30,
                             CELL_H, acc);
                draw_text_small((uint64_t)cx + 4, (uint64_t)cy,
                                db, rgb(0xFFFFFF), acc);
            } else {
                draw_text_small((uint64_t)cx + 4, (uint64_t)cy,
                                db, fg, bg);
            }
            cell = pos;
        }
        y += (uint64_t)((cell / 7 + 1) * (CELL_H + 4)) + 12;
    }
    /* 天気。 */
    draw_text_small(x, y, L("Weather", "天気"), acc, bg);
    y += CELL_H + 4;
    if (widgets_weather_state == 0) {
        draw_text_small(x, y,
                        L("(feed URL not set in Settings)",
                          "(設定でフィードURLが未設定です)"),
                        col_dim(), bg);
        y += CELL_H + 4;
        widgets_btn_y[0] = (int)y;
        {
            uint32_t face =
                ui_hover((int)x, (int)y, 150, (int)CELL_H + 6)
                    ? col_hover()
                    : col_window_bg();
            fb_fill_rect(x, y, 150, CELL_H + 6, face);
            draw_text_small(x + 10, y + 3,
                            L("Open Settings", "設定を開く"), fg,
                            face);
        }
        y += CELL_H + 10;
    } else if (widgets_weather_state < 0) {
        draw_text_small(x, y,
                        L("(could not fetch the feed)",
                          "(フィードを取得できませんでした)"),
                        col_dim(), bg);
        y += CELL_H + 4;
    } else {
        for (int i = 0; i < widgets_weather_count; i++) {
            draw_text_small(x, y, widgets_weather[i], fg, bg);
            y += CELL_H;
        }
        y += 4;
    }
    y += 8;
    /* ニュース。 */
    draw_text_small(x, y, L("News", "ニュース"), acc, bg);
    y += CELL_H + 4;
    if (widgets_news_state == 0) {
        draw_text_small(x, y,
                        L("(feed URL not set in Settings)",
                          "(設定でフィードURLが未設定です)"),
                        col_dim(), bg);
        y += CELL_H + 4;
        widgets_btn_y[1] = (int)y;
        {
            uint32_t face =
                ui_hover((int)x, (int)y, 150, (int)CELL_H + 6)
                    ? col_hover()
                    : col_window_bg();
            fb_fill_rect(x, y, 150, CELL_H + 6, face);
            draw_text_small(x + 10, y + 3,
                            L("Open Settings", "設定を開く"), fg,
                            face);
        }
        y += CELL_H + 10;
    } else if (widgets_news_state < 0) {
        draw_text_small(x, y,
                        L("(could not fetch the feed)",
                          "(フィードを取得できませんでした)"),
                        col_dim(), bg);
        y += CELL_H + 4;
    } else {
        for (int i = 0; i < widgets_news_count; i++) {
            draw_text_small(x, y, widgets_news[i], fg, bg);
            y += CELL_H;
        }
        y += 4;
    }
    draw_text_small(x, py + ph - CELL_H - 4,
                    L("R = refresh  Esc = close",
                      "R = 更新  Esc = 閉じる"),
                    col_dim(), bg);
}

/* タイルのラベル: 収まれば 1 行、長ければ文字境界で
 * 2 行に分けて中央寄せする (B2)。 */
static void draw_launcher_label(int64_t cx, int64_t cy,
                                const char *name, uint32_t fg,
                                uint32_t bg) {
    int px = aa_px_caption();
    uint64_t maxw = LAUNCH_CELL_W - 6;
    uint64_t w = fb_text_aa_width(name, px, 0);
    if (w <= maxw) {
        int64_t tx = cx + (int64_t)(LAUNCH_CELL_W - w) / 2;
        fb_draw_text_aa(tx, (int64_t)(cy + 46) + px * 13 / 16, name,
                        fg, (int32_t)bg, px, 0);
        return;
    }
    /* 幅が半分に近づく文字境界で分割する。 */
    int nch = 0;
    for (const char *p = name; *p != '\0'; p++) {
        if (((uint8_t)*p & 0xC0) != 0x80) {
            nch++;
        }
    }
    int best = 1;
    uint64_t bestdiff = (uint64_t)-1;
    for (int cand = 1; cand < nch; cand++) {
        char tmp[64];
        size_t tp = 0;
        int ci = 0;
        for (const char *q = name; *q != '\0'; q++) {
            if (((uint8_t)*q & 0xC0) != 0x80) {
                if (ci == cand) {
                    break;
                }
                ci++;
            }
            if (tp + 1 < sizeof(tmp)) {
                tmp[tp++] = *q;
            }
        }
        tmp[tp] = '\0';
        uint64_t w1 = fb_text_aa_width(tmp, px, 0);
        uint64_t d = w1 > w / 2 ? w1 - w / 2 : w / 2 - w1;
        if (d < bestdiff) {
            bestdiff = d;
            best = cand;
        }
    }
    char first[64];
    size_t fp = 0;
    {
        int ci = 0;
        const char *q = name;
        while (*q != '\0' && fp + 1 < sizeof(first)) {
            if (((uint8_t)*q & 0xC0) != 0x80) {
                if (ci == best) {
                    break;
                }
                ci++;
            }
            first[fp++] = *q++;
        }
        first[fp] = '\0';
        uint64_t w1 = fb_text_aa_width(first, px, 0);
        int64_t t1 = cx + (int64_t)(LAUNCH_CELL_W - w1) / 2;
        if (t1 < cx + 2) {
            t1 = cx + 2;
        }
        fb_draw_text_aa(t1, (int64_t)(cy + 42) + px * 13 / 16, first,
                        fg, (int32_t)bg, px, 0);
        uint64_t w2 = fb_text_aa_width(q, px, 0);
        int64_t t2 = cx + (int64_t)(LAUNCH_CELL_W - w2) / 2;
        if (t2 < cx + 2) {
            t2 = cx + 2;
        }
        fb_draw_text_aa(t2, (int64_t)(cy + 62) + px * 13 / 16, q,
                        fg, (int32_t)bg, px, 0);
    }
}

static void draw_launcher(void) {
    if (!launcher_active) {
        return;
    }
    int pw, ph, px, py;
    launcher_geometry(&pw, &ph, &px, &py);
    uint32_t panel = col_taskbar();
    /* パネル (T6): 角丸 8 + 影 + 1px 輪郭 + 半透明の
     * 素材 (下がほんのり透ける)。 */
    if (ui_shadow_pass) {
        fb_shadow_round_rect(px, py, pw, ph, UI_R_WIN, 6);
    }
    fb_fill_round_rect_alpha(px, py, pw, ph, UI_R_WIN, panel,
                             launcher_panel_alpha());
    fb_stroke_round_rect(px, py, pw, ph, UI_R_WIN, col_border());
    /* 検索欄: クリック (または文字キー) で検索パネルへ。 */
    {
        int64_t sx = px + LAUNCH_PAD;
        int64_t sy = py + LAUNCH_PAD;
        int64_t sw = pw - LAUNCH_PAD * 2;
        fb_fill_round_rect(sx, sy, sw, LAUNCH_SEARCH_H, UI_R_CTL,
                           col_window_bg());
        fb_stroke_round_rect(sx, sy, sw, LAUNCH_SEARCH_H, UI_R_CTL,
                             col_border());
        /* 虫眼鏡 (円と持ち手)。 */
        int64_t mx = sx + 15;
        int64_t my = sy + LAUNCH_SEARCH_H / 2 - 2;
        static const int ring[16][2] = {
            {0, -5}, {2, -5}, {4, -4}, {5, -2}, {5, 0}, {5, 2},
            {4, 4},  {2, 5},  {0, 5},  {-2, 5}, {-4, 4}, {-5, 2},
            {-5, 0}, {-5, -2}, {-4, -4}, {-2, -5}};
        for (int i = 0; i < 16; i++) {
            fb_put_pixel((uint64_t)(mx + ring[i][0]),
                         (uint64_t)(my + ring[i][1]), col_dim());
        }
        fb_draw_line(mx + 4, my + 4, mx + 9, my + 9, col_dim());
        draw_text_small((uint64_t)(sx + 30), (uint64_t)(sy + 12),
                        L("Search apps, files, settings",
                          "アプリ・ファイル・設定を検索"),
                        col_dim(), col_window_bg());
    }
    /* 見出しとピン留めグリッド (タイル: アイコン + 名前)。 */
    draw_text_small((uint64_t)(px + LAUNCH_PAD),
                    (uint64_t)(py + LAUNCH_PAD + LAUNCH_SEARCH_H + 14),
                    L("Pinned", "ピン留め"), col_text(), panel);
    int n = launcher_entries();
    for (int i = 0; i < n; i++) {
        int64_t cx = launch_cell_x(px, i);
        int64_t cy = launch_cell_y(py, i);
        uint32_t fill = i == launcher_selected ? col_accent()
                                               : col_window_bg();
        if (i != launcher_selected &&
            ui_hover((int)cx, (int)cy, LAUNCH_CELL_W,
                     LAUNCH_CELL_H)) {
            fill = col_hover();
        }
        uint32_t label = i == launcher_selected ? rgb(0xFFFFFF)
                                                : col_text();
        fb_fill_round_rect(cx, cy, LAUNCH_CELL_W, LAUNCH_CELL_H,
                           UI_R_CTL, fill);
        if (i != launcher_selected) {
            fb_stroke_round_rect(cx, cy, LAUNCH_CELL_W,
                                 LAUNCH_CELL_H, UI_R_CTL,
                                 col_border());
        }
        desktop_mode app;
        const char *name = launcher_label(i, &app);
        int apps = desk_visible_count();
        int icon = i < apps
                       ? (int)app
                       : i < apps + WIN_COUNT
                           ? (ICON_WIN_NOTES + (i - apps))
                           : ICON_WIDGETS;
        draw_app_icon((desktop_mode)icon,
                      (uint64_t)(cx + (LAUNCH_CELL_W - 32) / 2),
                      (uint64_t)(cy + 8), 2, fill);
        draw_launcher_label(cx, cy, name, label, fill);
    }
    /* フッター: ユーザー表示 + 電源ボタン (B8)。 */
    {
        int fy = py + ph - LAUNCH_FOOT_H;
        fb_fill_rect((uint64_t)(px + LAUNCH_PAD), (uint64_t)fy,
                     (uint64_t)(pw - LAUNCH_PAD * 2), 1, col_dim());
        const char *un = shell_current_user_name();
        fb_fill_round_rect(px + LAUNCH_PAD, fy + 8, 28, 28,
                           UI_R_CTL, col_accent());
        char ini[2];
        ini[0] = un[0] >= 'a' && un[0] <= 'z'
                     ? (char)(un[0] - 'a' + 'A')
                     : un[0];
        ini[1] = '\0';
        draw_text_small((uint64_t)(px + LAUNCH_PAD + 8),
                        (uint64_t)(fy + 12), ini, rgb(0xFFFFFF),
                        col_accent());
        draw_text_small((uint64_t)(px + LAUNCH_PAD + 38),
                        (uint64_t)(fy + 12), un, col_text(), panel);
        int bx, by, bw, bh;
        launcher_power_btn_rect(&bx, &by, &bw, &bh);
        int active = launcher_power_focus || launcher_power_open;
        uint32_t bfill = active ? col_accent() : col_window_bg();
        fb_fill_round_rect(bx, by, bw, bh, UI_R_CTL, bfill);
        if (!active) {
            fb_stroke_round_rect(bx, by, bw, bh, UI_R_CTL,
                                 col_border());
        }
        draw_app_icon((desktop_mode)ICON_SHUTDOWN,
                      (uint64_t)(bx + 10), (uint64_t)(by + 8), 1,
                      bfill);
        draw_text_small((uint64_t)(bx + 34), (uint64_t)(by + 6),
                        L("Power", "電源"),
                        active ? rgb(0xFFFFFF) : col_text(), bfill);
    }
    /* 展開した電源メニュー (B8)。 */
    if (launcher_power_open) {
        int bx, by, bw, bh;
        launcher_power_btn_rect(&bx, &by, &bw, &bh);
        int mw = 190;
        int mh = POWER_COUNT * 28 + 8;
        int mx = bx + bw - mw;
        int my = by - 6 - mh;
        uint32_t mbg = col_window_bg();
        fb_fill_round_rect_alpha(mx, my, mw, mh, UI_R_WIN, mbg,
                                 238);
        fb_stroke_round_rect(mx, my, mw, mh, UI_R_WIN,
                             col_border());
        for (int i = 0; i < POWER_COUNT; i++) {
            int ry = my + 4 + i * 28;
            int sel = i == launcher_power_sel;
            uint32_t face = mbg;
            if (sel) {
                fb_fill_round_rect(mx + 3, ry, mw - 6, 28,
                                   UI_R_CTL, col_accent());
                face = col_accent();
            } else if (ui_hover(mx + 3, ry, mw - 6, 28)) {
                fb_fill_round_rect(mx + 3, ry, mw - 6, 28,
                                   UI_R_CTL, col_hover());
                face = col_hover();
            }
            draw_app_icon((desktop_mode)(ICON_LOCK + i),
                          (uint64_t)(mx + 10), (uint64_t)(ry + 6),
                          1, face);
            draw_text_small((uint64_t)(mx + 36), (uint64_t)(ry + 4),
                            power_label(i),
                            sel ? rgb(0xFFFFFF) : col_text(), face);
        }
    }
}

static int launcher_cell_at(int x, int y) {
    int pw, ph, px, py;
    launcher_geometry(&pw, &ph, &px, &py);
    (void)pw;
    (void)ph;
    int n = launcher_entries();
    for (int i = 0; i < n; i++) {
        int64_t cx = launch_cell_x(px, i);
        int64_t cy = launch_cell_y(py, i);
        if (x >= cx && x < cx + LAUNCH_CELL_W && y >= cy &&
            y < cy + LAUNCH_CELL_H) {
            return i;
        }
    }
    return -1;
}

/* ================= Context menu ================= */

#define MENU_W 256
#define MENU_ROW_H 24
#define MENU_PAD 6

/* 右クリックメニューの文脈 (kind 1 = Files)。
 * menu_ctx: 0=ファイル, 1=フォルダ行, 2=ゴミ箱内。 */
static int menu_ctx;

static int menu_item_count(void) {
    if (menu_kind == 3) {
        return 2; /* ランチャー: 開く / アンインストール */
    }
    if (menu_kind == 1) {
        if (menu_ctx == 2) {
            return 3;
        }
        if (menu_ctx == 1) {
            return 3;
        }
        return 7;
    }
    return 5;
}

static const char *menu_item_label(int kind, int idx) {
    if (kind == 3) {
        if (desk_settings.language) {
            static const char *const items[2] = {
                "開く", "アンインストール"};
            return items[idx];
        }
        static const char *const items[2] = {"Open", "Uninstall"};
        return items[idx];
    }
    if (kind == 1) {
        if (menu_ctx == 2) {
            if (desk_settings.language) {
                static const char *const items[3] = {
                    "元に戻す", "完全に削除", "ゴミ箱を空にする"};
                return items[idx];
            }
            static const char *const items[3] = {
                "Restore", "Delete permanently", "Empty trash"};
            return items[idx];
        }
        if (menu_ctx == 1) {
            if (desk_settings.language) {
                static const char *const items[3] = {
                    "開く", "新規ファイル", "新規フォルダ"};
                return items[idx];
            }
            static const char *const items[3] = {
                "Open", "New file", "New folder"};
            return items[idx];
        }
        if (desk_settings.language) {
            static const char *const items[7] = {
                "開く", "名前をコピー", "コピー", "名前を変更",
                "新規ファイル", "新規フォルダ", "削除"};
            return items[idx];
        }
        static const char *const items[7] = {
            "Open", "Copy name", "Copy file", "Rename",
            "New file", "New folder", "Delete"};
        return items[idx];
    }
    if (desk_settings.language) {
        static const char *const items[5] = {
            "設定", "テーマ切替", "壁紙を変更", "ウィジェット",
            "ターミナル"};
        return items[idx];
    }
    static const char *const items[5] = {
        "Settings", "Toggle theme", "Change wallpaper", "Widgets",
        "Terminal"};
    return items[idx];
}

static void menu_open(int kind, int x, int y, int file_row) {
    menu_active = 1;
    menu_kind = kind;
    menu_file_row = file_row;
    menu_ctx = 0;
    if (kind == 1) {
        files_build_rows();
        if (files_in_trash()) {
            menu_ctx = 2;
        } else if (file_row >= 0 && file_row < files_row_count &&
                   files_rows[file_row] < 0) {
            menu_ctx = 1;
        }
    }
    int mh = MENU_PAD * 2 + menu_item_count() * MENU_ROW_H;
    if (x + MENU_W > (int)fb_width()) {
        x = (int)fb_width() - MENU_W - 4;
    }
    if (y + mh > (int)fb_height()) {
        y = (int)fb_height() - mh - 4;
    }
    menu_x = x;
    menu_y = y;
    serial_write_line(kind == 1 ? "menu: files"
                                : (kind == 3 ? "menu: launcher"
                                             : "menu: desktop"));
    desktop_redraw();
}

static void menu_activate(int idx) {
    serial_write("menu: ");
    serial_write_line(menu_item_label(menu_kind, idx));
    int kind = menu_kind;
    int row = menu_file_row;
    menu_active = 0;
    if (kind == 3) {
        /* ランチャーのアプリセル (row = セル番号)。 */
        if (row < 0 || row >= desk_visible_count()) {
            desktop_redraw();
            return;
        }
        desktop_mode m = desk_visible_mode(row);
        if (idx == 0) {
            launcher_activate(row);
            return;
        }
        if (app_set_hidden(m, 1) == 0) {
            desktop_notify(L("App uninstalled",
                             "アプリをアンインストールしました"));
        } else {
            desktop_notify(L("This app cannot be removed",
                             "このアプリは外せません"));
        }
        launcher_active = 0;
        if (desk_mode == m) {
            switch_mode(DESK_TERMINAL);
        }
        desktop_redraw();
        return;
    }
    if (kind == 1) {
        files_build_rows();
        if (row < 0 || row >= files_row_count) {
            desktop_redraw();
            return;
        }
        int vrow = files_rows[row];
        if (menu_ctx == 2) {
            /* ゴミ箱内: 復元 / 完全削除 / 空にする。 */
            if (idx == 2) {
                files_confirm = 1;
                desktop_redraw();
                return;
            }
            if (vrow < 0) {
                desktop_redraw();
                return;
            }
            const char *full = vfs_file_name(vrow);
            const char *base = full;
            if (full[0] == 't' && full[1] == 'r' && full[2] == 'a' &&
                full[3] == 's' && full[4] == 'h' && full[5] == '/') {
                base = full + 6;
            }
            if (idx == 0) {
                char btmp[28];
                size_t bp = 0;
                while (base[bp] != '\0' && bp + 1 < sizeof(btmp)) {
                    btmp[bp] = base[bp];
                    bp++;
                }
                btmp[bp] = '\0';
                if (files_trash_restore(btmp) == 0) {
                    desktop_notify(L("Restored", "元に戻しました"));
                } else {
                    desktop_notify(L("Could not restore",
                         "戻せませんでした (同名あり?)"));
                }
            } else if (idx == 1) {
                files_confirm = 2;
                size_t cp = 0;
                while (full[cp] != '\0' &&
                       cp + 1 < sizeof(files_confirm_name)) {
                    files_confirm_name[cp] = full[cp];
                    cp++;
                }
                files_confirm_name[cp] = '\0';
            }
            files_build_rows();
            desktop_redraw();
            return;
        }
        if (vrow < 0) {
            /* ディレクトリ行: 開く / 新規ファイル / 新規フォルダ。 */
            files_selected = row;
            if (idx == 0) {
                files_activate_row();
            } else if (idx == 1) {
                files_prompt_start(2, NULL);
            } else if (idx == 2) {
                files_prompt_start(3, NULL);
            }
            desktop_redraw();
            return;
        }
        const char *name = vfs_file_name(vrow);
        const char *base = name;
        for (const char *bp2 = name; *bp2 != '\0'; bp2++) {
            if (*bp2 == '/') {
                base = bp2 + 1;
            }
        }
        files_selected = row;
        if (idx == 0) {
            files_viewing = vrow;
        } else if (idx == 1) {
            desktop_clipboard_set(name, strlen(name));
            desktop_notify(L("Name copied", "名前をコピーしました"));
        } else if (idx == 2) {
            files_prompt_start(4, base);
        } else if (idx == 3) {
            files_prompt_start(1, base);
        } else if (idx == 4) {
            files_prompt_start(2, NULL);
        } else if (idx == 5) {
            files_prompt_start(3, NULL);
        } else if (idx == 6) {
            char tmp[32];
            size_t p = 0;
            while (name[p] != '\0' && p + 1 < sizeof(tmp)) {
                tmp[p] = name[p];
                p++;
            }
            tmp[p] = '\0';
            if (files_trash_file(tmp) == 0) {
                desktop_notify(L("Moved to trash", "ゴミ箱へ移動しました"));
            } else {
                desktop_notify(L("Could not trash it",
                     "ゴミ箱へ移動できませんでした"));
            }
            files_build_rows();
        }
        desktop_redraw();
        return;
    }
    if (idx == 0) {
        switch_mode(DESK_SETTINGS);
    } else if (idx == 1) {
        desk_settings.dark_mode = !desk_settings.dark_mode;
        settings_autosave();
        desktop_notify(desk_settings.dark_mode
                           ? L("Dark theme", "ダークテーマ")
                           : L("Light theme", "ライトテーマ"));
        desktop_redraw();
    } else if (idx == 2) {
        /* 壁紙の様式を順に切り替える。 */
        desk_settings.wallpaper_image =
            (desk_settings.wallpaper_image + 1) % 3;
        settings_autosave();
        desktop_notify(desk_settings.wallpaper_image == 2
                           ? L("Wallpaper: custom image",
                               "壁紙: カスタム画像")
                           : desk_settings.wallpaper_image == 1
                           ? L("Wallpaper: image",
                               "壁紙: 画像")
                           : L("Wallpaper: drawn",
                               "壁紙: 描画"));
        desktop_redraw();
    } else if (idx == 3) {
        widgets_open_panel();
        desktop_redraw();
    } else {
        switch_mode(DESK_TERMINAL);
    }
}

/* メニュー項目のアイコン (B6)。 */
static void menu_draw_icon(int i, uint64_t x, uint64_t y,
                           uint32_t bg) {
    if (menu_kind == 3) {
        if (i == 0 && menu_file_row >= 0 &&
            menu_file_row < desk_visible_count()) {
            draw_app_icon(desk_visible_mode(menu_file_row), x, y,
                          1, bg);
        } else {
            draw_file_icon(x, y, 16, FK_ARCHIVE);
        }
        return;
    }
    if (menu_kind == 1) {
        static const int f0[7] = {FK_DIR, FK_TEXT, FK_TEXT,
                                  FK_CODE, FK_TEXT, FK_DIR,
                                  FK_ARCHIVE};
        static const int f1[3] = {FK_DIR, FK_TEXT, FK_DIR};
        static const int f2[3] = {FK_DIR, FK_ARCHIVE, FK_ARCHIVE};
        int k = menu_ctx == 2 ? f2[i]
                : menu_ctx == 1 ? f1[i]
                                : f0[i];
        draw_file_icon(x, y, 16, k);
        return;
    }
    switch (i) {
        case 0:
            draw_app_icon(DESK_SETTINGS, x, y, 1, bg);
            break;
        case 1:
            /* テーマ: 半分ずつ明暗の円。 */
            fb_fill_rect(x + 2, y + 2, 6, 12, rgb(0xFFFFFF));
            fb_fill_rect(x + 8, y + 2, 6, 12, rgb(0x202226));
            break;
        case 2:
            draw_file_icon(x, y, 16, FK_IMAGE);
            break;
        case 3:
            draw_app_icon((desktop_mode)ICON_WIDGETS, x, y, 1, bg);
            break;
        default:
            draw_app_icon(DESK_TERMINAL, x, y, 1, bg);
            break;
    }
}

/* この項目の上に区切り線を引くか (B6)。 */
static int menu_separator_before(int i) {
    if (menu_kind == 1 && menu_ctx == 0) {
        return i == 6; /* 削除の上 */
    }
    if (menu_kind == 0) {
        return i == 2 || i == 4;
    }
    return 0;
}

static void draw_menu(void) {
    if (!menu_active) {
        return;
    }
    int mh = MENU_PAD * 2 + menu_item_count() * MENU_ROW_H;
    if (ui_shadow_pass) {
        fb_shadow_round_rect(menu_x, menu_y, MENU_W, mh, UI_R_WIN,
                             4);
    }
    fb_fill_round_rect_alpha(menu_x, menu_y, MENU_W, mh, UI_R_WIN,
                             col_taskbar(), 238);
    fb_stroke_round_rect(menu_x, menu_y, MENU_W, mh, UI_R_WIN,
                         col_border());
    for (int i = 0; i < menu_item_count(); i++) {
        uint64_t ry = (uint64_t)(menu_y + MENU_PAD +
                                 i * MENU_ROW_H);
        if (menu_separator_before(i)) {
            fb_fill_rect((uint64_t)(menu_x + 10), ry,
                         MENU_W - 20, 1, col_dim());
        }
        menu_draw_icon(i, (uint64_t)(menu_x + 10), ry + 4,
                       col_taskbar());
        draw_text_small((uint64_t)(menu_x + 34), ry + 2,
                        menu_item_label(menu_kind, i), col_text(),
                        col_taskbar());
    }
}

static int menu_item_at(int x, int y) {
    if (x < menu_x || x >= menu_x + MENU_W) {
        return -1;
    }
    int rel = y - menu_y - MENU_PAD;
    if (rel < 0) {
        return -1;
    }
    int idx = rel / MENU_ROW_H;
    if (idx >= menu_item_count()) {
        return -1;
    }
    return idx;
}

/* Everything drawn above the app window and the Dock:
 * floating windows, the launcher, the context menu and the
 * notification toasts. */
static void draw_drag_chip(void);

/* タスクバーのホバーツールチップ (B4)。 */
static void draw_tooltip(void) {
    if (launcher_active || menu_active || widgets_open ||
        net_panel_open || taskbar_vertical()) {
        return;
    }
    const char *label = NULL;
    char datebuf[64];
    char netbuf[96];
    int btn = taskbar_app_at(mouse_x, mouse_y);
    if (btn == -2) {
        label = L("Start", "スタート");
    } else if (btn >= 0) {
        label = mode_name(tb_button_app(btn));
    } else if (mouse_x >= net_icon_x() &&
               mouse_x < net_icon_x() + 40 &&
               mouse_y >= (int)taskbar_y() + 4 &&
               mouse_y < (int)taskbar_y() + 4 + TB_BTN_H) {
        /* トレイのネットワークアイコン: 名前 + 状態。 */
        size_t p = 0;
        netbuf[0] = '\0';
        buf_cat(netbuf, sizeof(netbuf), &p,
                L("Network: ", "ネットワーク: "));
        buf_cat(netbuf, sizeof(netbuf), &p, wifi_state_text());
        label = netbuf;
    } else if (mouse_y >= (int)taskbar_y() &&
               mouse_x >= (int)fb_width() - 150) {
        /* トレイ: 曜日つきの完全な日付を出す。 */
        static const char *const wd_en[7] = {
            "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"};
        static const char *const wd_ja[7] = {
            "日", "月", "火", "水", "木", "金", "土"};
        prism_rtc_time t;
        size_t p = 0;
        const char *d = date_text;
        while (*d != '\0' && p + 1 < sizeof(datebuf)) {
            datebuf[p++] = *d++;
        }
        if (rtc_read(&t) == 0) {
            int wd = rtc_weekday(2000 + t.year, t.month, t.day);
            const char *w = desk_settings.language ? wd_ja[wd]
                                                   : wd_en[wd];
            datebuf[p++] = ' ';
            datebuf[p++] = '(';
            while (*w != '\0' && p + 1 < sizeof(datebuf)) {
                datebuf[p++] = *w++;
            }
            datebuf[p++] = ')';
        }
        datebuf[p] = '\0';
        label = datebuf;
    }
    if (label == NULL) {
        return;
    }
    uint64_t w = fb_text_aa_width(label, 16 * text_scale_now(),
                                   0) +
                 16;
    uint64_t x = (uint64_t)mouse_x + 10;
    if (x + w > fb_width()) {
        x = fb_width() - w - 4;
    }
    uint64_t y = desk_settings.taskbar_top
                     ? taskbar_y() + TASKBAR_H + 6
                     : taskbar_y() - 32;
    fb_fill_rect_alpha(x, y, w, 28, col_taskbar(), 232);
    fb_fill_rect(x, y, w, 1, col_accent());
    fb_fill_rect(x, y + 27, w, 1, col_accent());
    draw_text_small(x + 8, y + 2, label, col_text(), -1);
}

static void draw_overlays(void) {
    draw_windows();
    draw_launcher();
    draw_widgets();
    draw_menu();
    draw_net_panel();
    draw_wifi_dialog();
    draw_notifications();
    draw_osk();
    draw_narrator_caption();
    draw_drag_chip();
    draw_tooltip();
}

/* アプリのフォルトを封じ込めた後の共通処理: アプリを
 * 閉じて (ターミナルに戻し) 通知を出し、監査に残す。 */
static void desk_contain_fault(const char *where) {
    serial_write("[appguard] contained a fault in a built-in app (");
    serial_write(where);
    serial_write_line("); the app was closed");
    audit_log_event("app-crash", where);
    desk_mode = DESK_TERMINAL;
    const char *msg =
        L("The app crashed and was closed.",
          "アプリが異常終了したため閉じました。");
    size_t p = 0;
    while (msg[p] != '\0' && p + 1 < sizeof(desk_notice)) {
        desk_notice[p] = msg[p];
        p++;
    }
    desk_notice[p] = '\0';
}

/* アプリ描画の武装つき呼び出し。 */
static void draw_window_guarded(void) {
    if (appguard_enter() != 0) {
        desk_contain_fault("draw");
        return;
    }
    draw_window();
    appguard_leave();
}

void desktop_redraw(void) {
    if (!desk_ok) {
        return;
    }
    if (desk_locked) {
        draw_lock_screen();
        fb_flush();
        return;
    }
    ui_shadow_pass = 1;
    draw_wallpaper();
    if (!desk_win_min) {
        draw_window_guarded();
    }
    /* 許可リストのお知らせ (あれば、画面の下の行に出す)。 */
    if (!desk_win_min && desk_notice[0] != '\0') {
        draw_text_small(text_x(),
                        text_y() +
                            (uint64_t)((text_rows() - 1) * CELL_H),
                        desk_notice, col_accent(), col_window_bg());
    }
    if (dock_visible_now()) {
        draw_dock();
    }
    draw_taskbar();
    draw_overlays();
    draw_cursor();
    ui_shadow_pass = 0;
}

void desktop_refresh_console(void) {
    if (!desk_ok) {
        return;
    }
    if (desk_locked) {
        draw_lock_screen();
        fb_flush();
        return;
    }
    draw_window_guarded();
    if (dock_visible_now()) {
        draw_dock();
    }
    draw_taskbar();
    draw_overlays();
    draw_cursor();
}

void desktop_tick(void) {
    if (!desk_ok) {
        return;
    }
    tick_counter++;
    /* 動き (stage 4): アニメーションの間は再描画を駆動し、
     * 閉じアニメーションが終わったら確定させる。 */
    if (ui_motion_on()) {
        if (launcher_closing) {
            if (ui_now_ms() - launcher_close_t0 >= UI_ANIM_MS) {
                launcher_active = 0;
                launcher_closing = 0;
            }
            desktop_redraw();
        } else if (launcher_active &&
                   ui_now_ms() - launcher_anim_t0 < UI_ANIM_MS) {
            desktop_redraw();
        }
        if (win_anim_offset() != 0) {
            desktop_redraw();
        }
    }
    /* 音楽の再生終了を見張る (C8)。進捗バーのために
     * 再生中はときどき描き直す。 */
    if ((tick_counter & 0x3FF) == 0) {
        music_poll();
        clock_poll();
        rec_poll();
        cam_poll();
        if (music_play_state == 1 && desk_mode == DESK_MUSIC) {
            desktop_redraw();
        }
    }
    /* Shooter enemy AI: once per RTC second, while playing.
     * Checked every 1024 idle-loop iterations (far more often
     * than once a second, so the second change is never missed). */
    if ((tick_counter & 0x3FF) == 0 && desk_mode == DESK_SHOOTER &&
        shooter_game_state.phase == 1) {
        prism_rtc_time st;
        if (rtc_read(&st) == 0 && st.second != shooter_last_ai_second) {
            shooter_last_ai_second = st.second;
            int hp_before = shooter_game_state.health;
            shooter_enemy_tick(&shooter_game_state, st.second);
            if (shooter_game_state.health < hp_before) {
                serial_write("shooter: hit by enemy, health=");
                shooter_serial_num(shooter_game_state.health);
                serial_write_line("");
            }
            if (shooter_game_state.phase == 3) {
                serial_write_line("shooter: game over");
            }
            desktop_redraw();
        }
    }
    /* Photos のスライドショー: 3 秒ごとに次の写真へ。 */
    if ((tick_counter & 0x3FF) == 0 && desk_mode == DESK_PHOTOS &&
        photos_slideshow && photos_viewing >= 0) {
        prism_rtc_time pt;
        if (rtc_read(&pt) == 0 && pt.second != photos_slide_second) {
            photos_slide_second = pt.second;
            photos_slide_count++;
            if (photos_slide_count >= 3) {
                photos_slide_count = 0;
                int list[PRISM_VFS_MAX_FILES];
                int count = photos_list(list, PRISM_VFS_MAX_FILES);
                if (count > 0) {
                    photos_viewing =
                        (photos_viewing + 1) % count;
                    photos_selected = photos_viewing;
                    photos_zoom = 0;
                    photos_rot = 0;
                    serial_write_line("photos: slideshow next");
                    desktop_redraw();
                }
            }
        }
    }
    /* ダブルクリック判定用に、RTC の秒変化から
     * tick_counter の 1 秒あたりの進みを較正する
     * (ビデオ再生の較正と同じ方法)。 */
    if ((tick_counter & 0x3FF) == 0) {
        prism_rtc_time ct;
        if (rtc_read(&ct) == 0 && ct.second != desk_cal_second) {
            if (desk_cal_second >= 0) {
                desk_ticks_per_sec =
                    tick_counter - desk_tick_at_last_second;
            }
            desk_cal_second = ct.second;
            desk_tick_at_last_second = tick_counter;
        }
    }
    /* Video playback: calibrate the loop rate from the RTC's
     * second changes, then advance the frame at 4 fps. */
    if ((tick_counter & 0x3FF) == 0 && desk_mode == DESK_VIDEO) {
        prism_rtc_time vt;
        if (rtc_read(&vt) == 0 && vt.second != video_last_second) {
            if (video_last_second >= 0) {
                video_ticks_per_sec =
                    (int64_t)(tick_counter - video_tick_at_last_second);
                video_calibrated = 1;
                if (video_player_state.playing) {
                    video_arm_next_tick();
                }
            }
            video_last_second = vt.second;
            video_tick_at_last_second = (int64_t)tick_counter;
        }
        if (video_calibrated &&
            video_tick(&video_player_state, (int64_t)tick_counter,
                       &video_next_tick,
                       video_ticks_per_frame(video_ticks_per_sec))) {
            desktop_redraw();
            if (video_play_frame_audio()) {
                /* 音声がフレームの表示時間そのものなので、
                 * 次のフレームは音声が終わり次第進める。 */
                video_next_tick = (int64_t)tick_counter;
            }
        }
    }
    if ((tick_counter & 0xFFF) != 0) {
        return;
    }
    prism_rtc_time t;
    if (rtc_read(&t) != 0) {
        return;
    }
    if (t.second == last_clock_second) {
        return;
    }
    last_clock_second = t.second;
    rtc_format_hhmm(&t, clock_text);
    clock_update_date(&t);
    int notify_changed = 0;
    for (int i = 0; i < NOTIFY_MAX; i++) {
        if (notify_ttl[i] > 0) {
            notify_ttl[i]--;
            if (notify_ttl[i] == 0) {
                notify_changed = 1;
            }
        }
    }
    int any_win = 0;
    for (int i = 0; i < WIN_COUNT; i++) {
        if (win_open[i]) {
            any_win = 1;
        }
    }
    if (notify_changed || (any_win && desk_mode == DESK_TERMINAL)) {
        desktop_redraw();
    } else if (desk_locked) {
        /* ロック中はタスクバーを描かない (A4)。時計の更新は
         * 秒が変わったときだけ再描画する。 */
        static int lock_last_sec = -1;
        prism_rtc_time lt;
        if (rtc_read(&lt) == 0 && lt.second != lock_last_sec) {
            lock_last_sec = lt.second;
            draw_lock_screen();
            fb_flush();
        }
    } else {
        draw_taskbar();
        draw_cursor();
    }
}

void desktop_init(void) {
    if (!fb_ready()) {
        return;
    }
    ui_clock_init();
    settings_defaults(&desk_settings);
    /* Load saved settings, if a previous run in this boot saved
     * them to the file system. The file system lives in RAM,
     * so this only survives within one boot. */
    size_t len = 0;
    const char *saved = vfs_read_ptr("settings.txt", &len);
    if (saved != NULL && len > 0) {
        settings_parse(&desk_settings, saved, len);
    }
    sb16_set_volume(desk_settings.volume);
    mouse_set_speed(desk_settings.mouse_speed);
    keyboard_set_repeat(desk_settings.key_repeat);
    /* 通知履歴を前回起動から引き継ぐ。 */
    notify_hist_load();
    /* 保存された解像度があれば適用する (res コマンド /
     * 設定画面の解像度切替の永続化)。失敗したら既定の
     * モードのままにする。 */
    if (desk_settings.res_w > 0 && desk_settings.res_h > 0) {
        if (vbe_set_mode((uint32_t)desk_settings.res_w,
                         (uint32_t)desk_settings.res_h) == 0) {
            mouse_set_bounds(desk_settings.res_w,
                             desk_settings.res_h);
            mouse_set_position(desk_settings.res_w / 2,
                               desk_settings.res_h / 2);
            serial_write("[boot] desktop: resolution restored ");
            serial_write_num((uint64_t)desk_settings.res_w);
            serial_write("x");
            serial_write_num((uint64_t)desk_settings.res_h);
            serial_write_line("");
        }
    }
    /* 許可リストを読む。止められたアプリがあれば報告する。 */
    desk_load_allowlist();
    {
        int denied = 0;
        for (int i = 0; i < SEC_APP_COUNT; i++) {
            if (!desk_allowed[i]) {
                denied++;
            }
        }
        if (denied > 0) {
            serial_write("[boot] desktop: allowlist denies ");
            {
                char num[4];
                int v = denied;
                int d = 0;
                char tmp[4];
                if (v == 0) {
                    tmp[d++] = '0';
                } else {
                    while (v > 0) {
                        tmp[d++] = (char)('0' + (v % 10));
                        v /= 10;
                    }
                }
                int q = 0;
                while (d > 0) {
                    num[q++] = tmp[--d];
                }
                num[q] = '\0';
                serial_write(num);
            }
            serial_write_line(" app(s).");
        }
    }
    if (desk_settings.install_profile) {
        serial_write_line(
            "[boot] desktop: minimal profile (4 apps).");
    }
    /* グリッドは標準セル (12x16) の寸法で確保する。
     * 起動時の文字サイズが大きくても、後から標準へ
     * 戻したときにグリッドが不足しないようにするため。 */
    {
        uint64_t w = win_w();
        uint64_t h = win_h();
        int max_cols = w >= 16 ? (int)((w - 16) / 12) : 0;
        int max_rows =
            h >= TITLE_H + 16 ? (int)((h - TITLE_H - 16) / 16) : 0;
        console_cells = max_cols * max_rows;
    }
    console_cols = text_cols();
    console_rows = text_rows();
    console_col = 0;
    console_row = 0;
    console_grid = NULL;
    console_ok = 0;
    if (console_cols > 0 && console_rows > 0 && console_cells > 0) {
        console_grid = (uint32_t *)kmalloc(
            (size_t)console_cells * sizeof(uint32_t));
        if (console_grid != NULL) {
            for (int i = 0; i < console_cells; i++) {
                console_grid[i] = ' ';
            }
            console_ok = 1;
            console_hist = (uint32_t *)kmalloc(
                (size_t)CONSOLE_HIST_LINES *
                (size_t)console_cols * sizeof(uint32_t));
            if (console_hist != NULL) {
                console_hist_cols = console_cols;
                for (int i = 0; i < CONSOLE_HIST_LINES * console_cols;
                     i++) {
                    console_hist[i] = ' ';
                }
            }
        }
    }
    desk_ok = 1;
    /* Parse the embedded wallpaper image once. */
    wallpaper_ok =
        wallpaper_parse(prism_wallpaper_data,
                        (size_t)(prism_wallpaper_end - prism_wallpaper_data),
                        &wallpaper_image) == 0;
    /* 自分の壁紙が設定されていれば読み込む (設定は復号済みの
     * ファイルから読んだ後なので、この時点で中身が揃う)。 */
    wp_custom_load();
    search_active = 0;
    search_count = 0;
    search_selected = 0;
    search_len = 0;
    search_query[0] = '\0';
    /* The mouse cursor starts in the middle of the screen. */
    mouse_set_bounds((int)fb_width(), (int)fb_height());
    mouse_x = (int)(fb_width() / 2);
    mouse_y = (int)(fb_height() / 2);
    mouse_prev_buttons = 0;
    mouse_set_position(mouse_x, mouse_y);
    files_selected = 0;
    files_viewing = -1;
    photos_selected = 0;
    photos_viewing = -1;
    music_selected = 0;
    music_checked = 0;
    music_has_device = 0;
    music_state = 0;
    cards_phase = 0;
    cards_game = 0;
    cards_wins = 0;
    cards_losses = 0;
    cards_pushes = 0;
    cards_player_n = 0;
    cards_dealer_n = 0;
    shooter_new_game(&shooter_game_state);
    shooter_hitmark = 0;
    shooter_last_ai_second = -1;
    sheet_clear(&sheet_grid);
    sheet_sel_col = 0;
    sheet_sel_row = 0;
    sheet_edit_len = 0;
    sheet_editing = 0;
    sheet_loaded = 0;
    sheet_dirty = 0;
    video_init(&video_player_state, 0);
    video_frame_count = 0;
    video_next_tick = 0;
    video_ticks_per_sec = 0;
    video_tick_at_last_second = 0;
    video_last_second = -1;
    video_calibrated = 0;
    video_is_pv1 = 0;
    video_decoded_frame = -1;
    video_pv1_w = 0;
    video_pv1_h = 0;
    settings_saved = 0;
    browser_state = 0;
    browser_status = 0;
    browser_scroll = 0;
    notes_buf = NULL;
    notes_len = 0;
    notes_cursor = 0;
    notes_loaded = 0;
    notes_dirty = 0;
    notes_saved = 0;
    cal_offset = 0;
    prism_rtc_time t;
    if (rtc_read(&t) == 0) {
        last_clock_second = t.second;
        rtc_format_hhmm(&t, clock_text);
        clock_update_date(&t);
    }
    desktop_redraw();
    serial_write_line("[boot] desktop: ready (screen apps on framebuffer).");
}

int desktop_ready(void) {
    return desk_ok;
}

static void console_scroll(void) {
    if (!console_ok) {
        return;
    }
    /* 流れ出る最上行を履歴へ残す。 */
    if (console_hist != NULL && console_hist_cols == console_cols) {
        int slot = console_hist_count % CONSOLE_HIST_LINES;
        for (int i = 0; i < console_cols; i++) {
            console_hist[slot * console_cols + i] =
                console_grid[i];
        }
        console_hist_count++;
    }
    size_t row_cells = (size_t)console_cols;
    memmove(console_grid, console_grid + row_cells,
            row_cells * (size_t)(console_rows - 1) * sizeof(uint32_t));
    for (int i = 0; i < console_cols; i++) {
        console_grid[(console_rows - 1) * console_cols + i] = ' ';
    }
    console_row = console_rows - 1;
}

static void console_next_row(void) {
    console_col = 0;
    console_row++;
    if (console_row >= console_rows) {
        console_scroll();
    }
}

static void console_place(uint32_t cp) {
    int wide = jfont_is_wide(cp);
    if (console_col + (wide ? 2 : 1) > console_cols) {
        console_next_row();
    }
    console_grid[console_row * console_cols + console_col] = cp;
    console_col++;
    if (wide) {
        console_grid[console_row * console_cols + console_col] =
            CONSOLE_WIDE_TAIL;
        console_col++;
    }
    if (console_col >= console_cols) {
        console_next_row();
    }
}

void desktop_console_putc(int c) {
    if (!console_ok) {
        return;
    }
    /* 新しい出力が来たら表示は最下部へ戻る。 */
    console_view_offset = 0;
    unsigned char b = (unsigned char)c;
    if (b == '\r') {
        console_pending_len = 0;
        console_col = 0;
        return;
    }
    if (b == '\n') {
        console_pending_len = 0;
        console_next_row();
        return;
    }
    if (b == '\b') {
        console_pending_len = 0;
        if (console_col > 0) {
            console_col--;
            if (console_grid[console_row * console_cols + console_col] ==
                CONSOLE_WIDE_TAIL) {
                console_grid[console_row * console_cols + console_col] =
                    ' ';
                if (console_col > 0) {
                    console_col--;
                }
            }
            console_grid[console_row * console_cols + console_col] = ' ';
        }
        return;
    }
    if (console_pending_len == 0) {
        if (b < 32 || b == 127) {
            return;
        }
        if (b < 0x80) {
            console_place(b);
            return;
        }
        if (b >= 0xC2 && b <= 0xDF) {
            console_pending_need = 2;
        } else if (b >= 0xE0 && b <= 0xEF) {
            console_pending_need = 3;
        } else if (b >= 0xF0 && b <= 0xF4) {
            console_pending_need = 4;
        } else {
            console_place(0xFFFD);
            return;
        }
        console_pending[0] = b;
        console_pending_len = 1;
        return;
    }
    /* Continuation byte of a pending sequence. */
    if ((b & 0xC0) != 0x80) {
        console_pending_len = 0;
        console_place(0xFFFD);
        return;
    }
    console_pending[console_pending_len++] = b;
    if (console_pending_len >= console_pending_need) {
        uint32_t cp = 0xFFFD;
        jfont_utf8_decode((const char *)console_pending,
                          (size_t)console_pending_len, &cp);
        console_pending_len = 0;
        console_place(cp);
    }
}

void desktop_console_write(const char *s) {
    if (s == NULL) {
        return;
    }
    while (*s != '\0') {
        desktop_console_putc((unsigned char)*s);
        s++;
    }
}

void desktop_console_clear(void) {
    if (!console_ok) {
        return;
    }
    for (int i = 0; i < console_cols * console_rows; i++) {
        console_grid[i] = ' ';
    }
    console_col = 0;
    console_row = 0;
    desktop_redraw();
}

static void switch_mode(desktop_mode m) {
    /* 許可リストで止められたアプリは開かない。 */
    if (!sec_app_allowed(desk_allowed, (int)m)) {
        serial_write("desktop: app '");
        serial_write(mode_name(m));
        serial_write_line("' is not allowed by the administrator.");
        size_t p = 0;
        const char *a = L("App '", "アプリ「");
        while (*a != '\0' && p + 1 < sizeof(desk_notice)) {
            desk_notice[p++] = *a++;
        }
        const char *nm = mode_name(m);
        while (*nm != '\0' && p + 1 < sizeof(desk_notice)) {
            desk_notice[p++] = *nm++;
        }
        const char *b = L("' is not allowed.", "」は許可されていません");
        while (*b != '\0' && p + 1 < sizeof(desk_notice)) {
            desk_notice[p++] = *b++;
        }
        desk_notice[p] = '\0';
        desktop_redraw();
        return;
    }
    desk_notice[0] = '\0';
    desk_win_max = 0;
    desk_win_min = 0;
    desk_mode = m;
    win_anim_t0 = ui_now_ms();
    narrator_say(mode_name(m));
    files_viewing = -1;
    settings_saved = 0;
    if (m == DESK_INSTALLER) {
        installer_refresh();
    }
    if (m == DESK_MAIL) {
        mail_rebuild();
        if (!mail_configured()) {
            /* 未設定なら初回設定フォームに誘導する。 */
            mail_setup_open();
        }
    }
    if (m == DESK_SETTINGS) {
        settings_gui_enter();
    }
    if (m == DESK_NOTIF) {
        notif_scroll = 0;
        serial_write("notiflog: opened, ");
        serial_write_num(notify_hist_count);
        serial_write_line(" entries");
    }
    desktop_redraw();
}

/* Which Dock button (0-15) is at (x, y), or -1. The geometry
 * mirrors draw_dock(). */
static int dock_button_at(int x, int y) {
    if (!dock_visible_now()) {
        return -1;
    }
    const int bw = dock_btn_w();
    const int bh = dock_btn_h();
    const int gap = 4;
    int64_t start = 0;
    int64_t cross = 0;
    int count = dock_layout(&start, &cross);
    for (int i = 0; i < count; i++) {
        int64_t bx = desk_settings.dock_pos == 1 ? cross
                                                 : start + i * (bw + gap);
        int64_t by = desk_settings.dock_pos == 1
                         ? start + i * (bh + gap)
                         : cross;
        if (x >= bx && x < bx + bw && y >= by && y < by + bh) {
            return i;
        }
    }
    return -1;
}
/* A left click at screen position (x, y). */
/* 設定アプリのマウス操作 (項目10)。行クリックで
 * 選択し、選択中の行の再クリックは Enter と同じ
 * (決定/切り替え)。見た目ページは項目キーそのものを
 * 実行する。他アプリと同じく、実際の処理はキー処理に
 * 集約されているので、ここは行→キーの対応だけを持つ。 */
static void settings_mouse_click(int x, int y) {
    if (pin_dialog_open) {
        /* ダイアログのボタン (B9)。 */
        if (y >= pin_btn_y && y < pin_btn_y + (int)CELL_H + 10) {
            if (x >= pin_btn_x[0] && x < pin_btn_x[0] + 110) {
                pin_dialog_key('\n');
            } else if (x >= pin_btn_x[1] &&
                       x < pin_btn_x[1] + 110) {
                pin_dialog_key(0x1B);
            }
        }
        return;
    }
    if (y < (int)text_y()) {
        return;
    }
    /* サイドバー (T4): 検索ボックスとページ一覧。 */
    if (x < (int)(set_x() - 10)) {
        int ly = y - (int)text_y();
        if (ly >= 0 && ly < 32) {
            /* 検索ボックス: 全体検索を開く。 */
            search_active = 1;
            search_len = 0;
            search_query[0] = '\0';
            search_rebuild();
            desktop_redraw();
            return;
        }
        int idx = (ly - SET_SIDE_TOP) / set_side_row_h();
        if (ly >= SET_SIDE_TOP && idx >= 0 && idx < 8) {
            settings_page = idx;
            desktop_redraw();
        }
        return;
    }
    int row = (int)((y - (int)text_y()) / CELL_H);
    if (settings_page == 0) {
        /* カードのヒット表からキー操作へ変換する。 */
        int sub = -1;
        int id = set_hit_at(x, y, &sub);
        if (id == 100) {
            if (sub >= 0 && sub < PRISM_ACCENT_COUNT) {
                desktop_handle_key('1' + sub);
            }
            return;
        }
        static const char keys[19] = {
            'k', 't', 'm', 'w', 'p', 'z', 'h', 'g',
            'j', 'x', 'b', 'o', 'n', 'r', 'e', 'i', 'u', 'c', 'a'
        };
        if (id >= 0 && id < 19) {
            desktop_handle_key(keys[id]);
        }
        return;
    }
    if (settings_page == 1) {
        int id = set_hit_at(x, y, NULL);
        if (id == PRISM_BIND_COUNT) {
            desktop_handle_key('0');
            return;
        }
        if (id >= 0 && id < PRISM_BIND_COUNT) {
            if (id == bind_selected) {
                desktop_handle_key('\n');
            } else {
                bind_selected = id;
                desktop_redraw();
            }
        }
        return;
    }
    if (settings_page == 2) {
        if (acct_mode != ACCT_MODE_LIST) {
            return;
        }
        int id = set_hit_at(x, y, NULL);
        if (id >= 0 && id < acct_user_count + 2) {
            if (id == acct_selected) {
                desktop_handle_key('\n');
            } else {
                acct_selected = id;
                desktop_redraw();
            }
        }
        return;
    }
    if (settings_page == 3) {
        int id = set_hit_at(x, y, NULL);
        if (id >= 0 && id < 6 + SEC_APP_COUNT) {
            if (id == sec_selected) {
                desktop_handle_key('\n');
            } else {
                sec_selected = id;
                desktop_redraw();
            }
        }
        return;
    }
    if (settings_page == 4) {
        int id = set_hit_at(x, y, NULL);
        if (id >= 0 && id <= 4) {
            if (id == upd_selected) {
                desktop_handle_key('\n');
            } else {
                upd_selected = id;
                desktop_redraw();
            }
        }
        return;
    }
    if (settings_page == 5) {
        int id = set_hit_at(x, y, NULL);
        if (id >= 0 && id <= 2) {
            if (id == clk_row) {
                desktop_handle_key('\n');
            } else {
                clk_row = id;
                desktop_redraw();
            }
        }
        return;
    }
    if (settings_page == 6) {
        int sub = -1;
        int id = set_hit_at(x, y, &sub);
        if (id < 0) {
            return;
        }
        if (sub == 1) {
            /* 保存済みカードの削除ゾーン。 */
            wifi_ui_forget_idx(id - net_saved_base());
            return;
        }
        if (id == 8) {
            /* Wi-Fi トグルはクリックで即切り替え。 */
            net_row = 8;
            wifi_ui_toggle();
            return;
        }
        if (id == net_row) {
            desktop_handle_key('\n');
        } else {
            net_row = id;
            desktop_redraw();
        }
        return;
    }
    if (settings_page == 7) {
        if (adm_form) {
            return;
        }
        /* 分類タブ (ピル): クリックでその分類へ。 */
        int tab = adm_tab_at(x, y);
        if (tab >= 0) {
            adm_section = tab;
            adm_selected = 0;
            adm_refresh();
            desktop_redraw();
            return;
        }
        /* 本文のカード: クリックで選択、選択中の再クリックで
         * 実行 (他ページと同じ流儀)。 */
        int aid = adm_hit_at(x, y);
        if (aid >= 0) {
            if (aid == adm_selected) {
                desktop_handle_key('\n');
            } else {
                adm_selected = aid;
                desktop_redraw();
            }
        }
        return;
    }
}

static int desktop_handle_key_inner(int c);

/* ファイルのツールバーのボタン番号→キー相当アクション。 */
static void files_toolbar_click(int idx) {
    if (files_in_trash()) {
        static const char keys[5] = {'r', 'x', 'e', 'o', 'v'};
        if (idx >= 0 && idx < 5) {
            desktop_handle_key_inner(keys[idx]);
        }
        return;
    }
    static const char keys[7] = {'n', 'm', 'r', 'c', 'd', 'o', 'v'};
    if (idx >= 0 && idx < 7) {
        desktop_handle_key_inner(keys[idx]);
    }
}

static void desktop_mouse_click(int x, int y) {
    /* Wi-Fi 接続ダイアログはモーダル: 開いている間は
     * すべてのクリックをダイアログが受ける。 */
    if (wifi_dlg_click(x, y)) {
        return;
    }
    /* The on-screen keyboard takes clicks on its panel first:
     * the key goes through the same path as a physical key. */
    if (desk_settings.osk && y >= (int)osk_panel_y()) {
        int code = osk_key_at(x, y);
        if (code >= 0) {
            if (osk_queue_len < OSK_QUEUE_MAX) {
                osk_queue[osk_queue_len++] = code;
            }
            serial_write_line("osk: key pressed");
        }
        return;
    }
    /* トースト: ×印で閉じ、本体クリックで通知履歴を
     * 開く (B7)。 */
    for (int i = 0; i < NOTIFY_MAX; i++) {
        if (notify_rw[i] > 0 && x >= notify_rx[i] &&
            x < notify_rx[i] + notify_rw[i] &&
            y >= notify_ry[i] && y < notify_ry[i] + notify_rh[i]) {
            int open_hist = x < notify_rx[i] + notify_rw[i] - 30;
            notify_ttl[i] = 0;
            notify_rw[i] = 0;
            serial_write_line(open_hist ? "notify: open history"
                                        : "notify: dismissed");
            if (open_hist) {
                switch_mode(DESK_NOTIF);
            } else {
                desktop_redraw();
            }
            return;
        }
    }
    /* 検索パネルの結果行クリックで開く (B3)。 */
    if (search_active) {
        int64_t row_y = (int64_t)text_y() + 3 * CELL_H;
        if (y >= row_y) {
            int row = (int)((y - row_y) / CELL_H);
            if (row >= 0 && row < search_count &&
                x >= (int)text_x() &&
                x < (int)(win_x() + win_w() - 12)) {
                search_selected = row;
                search_activate();
            }
        }
        return;
    }
    /* IME 候補ポップアップの候補行クリックで選択 (E1)。 */
    if (ime_popup_rows > 0 && x >= ime_popup_x &&
        x < ime_popup_x + ime_popup_w && y >= ime_popup_y) {
        int row = (y - ime_popup_y - 4) / (int)CELL_H;
        if (row >= 1 && row - 1 < ime_popup_rows) {
            if (ime_select_candidate(row - 1)) {
                serial_write("ime: candidate ");
                serial_write_num(row);
                serial_write_line(" (click)");
            }
            desktop_refresh_console();
            return;
        }
    }
    /* Open panels and windows take clicks first. */
    if (menu_active) {
        int idx = menu_item_at(x, y);
        if (idx >= 0) {
            menu_activate(idx);
        } else {
            menu_active = 0;
            desktop_redraw();
        }
        return;
    }
    if (widgets_open) {
        /* 「設定を開く」ボタン (B5)。 */
        for (int i = 0; i < 2; i++) {
            if (widgets_btn_y[i] >= 0 && x >= 22 && x < 172 &&
                y >= widgets_btn_y[i] &&
                y < widgets_btn_y[i] + (int)CELL_H + 6) {
                widgets_open = 0;
                serial_write_line("widgets: open settings");
                switch_mode(DESK_SETTINGS);
                return;
            }
        }
        /* パネルの外をクリックしたら閉じる。 */
        if (!(x >= 8 && x < 448 && y >= 56)) {
            widgets_open = 0;
            serial_write_line("widgets: closed");
            desktop_redraw();
        }
        return;
    }
    if (launcher_active) {
        if (launcher_closing) {
            /* 閉じアニメーション中のクリックは閉じを完了させ
             * て受ける (裏のアプリを誤って押さない)。 */
            launcher_active = 0;
            launcher_closing = 0;
            desktop_redraw();
            return;
        }
        if (launcher_power_open) {
            int row = launcher_power_row_at(x, y);
            if (row >= 0) {
                launcher_power_open = 0;
                launcher_active = 0;
                serial_write("launcher: ");
                serial_write_line(power_label(row));
                power_action(row);
                return;
            }
            launcher_power_open = 0;
            desktop_redraw();
            return;
        }
        if (launcher_power_btn_at(x, y)) {
            launcher_power_open = 1;
            launcher_power_sel = 0;
            desktop_redraw();
            return;
        }
        if (launcher_search_at(x, y)) {
            launcher_active = 0;
            search_open();
            desktop_redraw();
            return;
        }
        int cell = launcher_cell_at(x, y);
        if (cell >= 0) {
            launcher_activate(cell);
        } else {
            launcher_request_close();
            desktop_redraw();
        }
        return;
    }
    /* ネットワークのクイックパネル / トレイアイコン
     * (横タスクバーのみ)。パネル表示中はアイコンの
     * 再クリックと外側クリックで閉じる。 */
    if (!taskbar_vertical()) {
        if (net_panel_open) {
            if (net_panel_click(x, y)) {
                return;
            }
            net_panel_open = 0;
            serial_write_line("wifi: quick panel closed");
            desktop_redraw();
            return;
        }
        if (x >= net_icon_x() && x < net_icon_x() + 40 &&
            y >= (int)taskbar_y() + 4 &&
            y < (int)taskbar_y() + 4 + TB_BTN_H) {
            net_panel_toggle();
            return;
        }
    }
    /* 縦タスクバーのスタートボタンがランチャーを開閉する。 */
    if (taskbar_vertical()) {
        uint64_t bx = desk_settings.taskbar_side == 1
                          ? 0
                          : fb_width() - TASKBAR_W;
        if (x >= (int)bx + 10 && x < (int)bx + TASKBAR_W - 10 &&
            y >= 40 && y < 64) {
            if (launcher_active) {
                launcher_request_close();
                serial_write_line("launcher: closed");
            } else {
                launcher_active = 1;
                launcher_closing = 0;
                launcher_anim_t0 = ui_now_ms();
                serial_write_line("launcher: opened");
            }
            launcher_selected = 0;
            launcher_power_open = 0;
            launcher_power_focus = 0;
            desktop_redraw();
            return;
        }
    }
    if (!taskbar_vertical()) {
        int btn = taskbar_app_at(x, y);
        if (btn == -2) {
            net_panel_close_on_start();
            if (launcher_active) {
                launcher_request_close();
                serial_write_line("launcher: closed");
            } else {
                launcher_active = 1;
                launcher_closing = 0;
                launcher_anim_t0 = ui_now_ms();
                serial_write_line("launcher: opened");
            }
            launcher_selected = 0;
            launcher_power_open = 0;
            launcher_power_focus = 0;
            desktop_redraw();
            return;
        }
        if (btn >= 0) {
            desktop_mode app = tb_button_app(btn);
            serial_write("desktop: mouse click -> ");
            serial_write_line(mode_name(app));
            switch_mode(app);
            return;
        }
    }
    /* 最小化中: タスクバー以外へのクリックで復帰する
     * (タスクバーの操作は上の処理で済んでいる)。 */
    if (desk_win_min) {
        desk_win_min = 0;
        serial_write_line("window: restored");
        desktop_redraw();
        return;
    }
    /* タイトルバーのボタン (最小化 / 最大化 / 閉じる)。
     * 閉じる = ターミナルへ戻る (フォールト封じ込めと同じ
     * 意味づけ)。 */
    {
        int ctl = win_ctl_at(x, y);
        if (ctl == 2) {
            serial_write("window: closed ");
            serial_write_line(mode_name(desk_mode));
            switch_mode(DESK_TERMINAL);
            return;
        }
        if (ctl == 1) {
            desk_win_max = !desk_win_max;
            serial_write_line(desk_win_max ? "window: maximized"
                                           : "window: restored");
            desktop_redraw();
            return;
        }
        if (ctl == 0) {
            desk_win_min = 1;
            serial_write_line("window: minimized");
            desktop_redraw();
            return;
        }
    }
    if (desk_mode == DESK_SETTINGS) {
        settings_mouse_click(x, y);
        return;
    }
    if (desk_mode == DESK_TERMINAL) {
        int w = win_at(x, y);
        if (w >= 0) {
            if (x >= win_px[w] + win_w_of(w) - 24 &&
                y < win_py[w] + 24) {
                win_close(w);
                return;
            }
            win_z[w] = ++win_z_top;
            win_focus = w;
            if (y < win_py[w] + 24) {
                win_drag = w;
                win_drag_dx = x - win_px[w];
                win_drag_dy = y - win_py[w];
            }
            desktop_redraw();
            return;
        }
        if (win_focus >= 0) {
            win_focus = -1; /* clicked the terminal itself */
            desktop_redraw();
        }
    }
    int dock = dock_button_at(x, y);
    if (dock >= 0) {
        desktop_mode app = desk_visible_mode(dock);
        serial_write("desktop: mouse click -> ");
        serial_write_line(mode_name(app));
        switch_mode(app);
        return;
    }
    if (desk_mode == DESK_BROWSER) {
        br_tabs_ensure();
        /* タブバーのクリック: 本体=切替、右端=閉じる、+=新規。 */
        int64_t taby = (int64_t)text_y();
        if (y >= taby && y < taby + (int)BR_TAB_H) {
            for (int i = 0; i < br_tab_count; i++) {
                if (x >= br_tab_x[i] &&
                    x < br_tab_x[i] + br_tab_w[i] - 4) {
                    if (x >= br_tab_x[i] + br_tab_w[i] - 4 - 18) {
                        br_tab_close(i);
                    } else {
                        br_tab_switch(i);
                    }
                    return;
                }
            }
            if (br_tab_plus_x >= 0 && x >= br_tab_plus_x &&
                x < br_tab_plus_x + (int)BR_TAB_H) {
                br_tab_new();
                return;
            }
        }
        /* パネル表示中はパネル内のクリックだけを受ける。 */
        if (br_panel) {
            uint64_t pw = win_w() - 16;
            if (pw > 640) {
                pw = 640;
            }
            if (y >= br_panel_list_y && br_panel_rows > 0 &&
                x >= (int)text_x() &&
                x < (int)(text_x() + pw)) {
                int r = (int)((y - br_panel_list_y) /
                              br_panel_row_h);
                if (r >= 0 && r < br_panel_rows) {
                    br_panel_sel = br_panel_top + r;
                    br_panel_activate();
                    return;
                }
            }
            br_panel = 0;
            desktop_redraw();
            return;
        }
        /* アドレスバーのボタン。 */
        int64_t bary = (int64_t)BR_TOOL_Y(text_y());
        if (y >= bary && y < bary + (int)BR_TOOL_H) {
            for (int i = 0; i < 6; i++) {
                if (x >= br_btn_x[i] &&
                    x < br_btn_x[i] + br_btn_w[i]) {
                    if (i == 0) {
                        br_hist_go(-1);
                    } else if (i == 1) {
                        br_hist_go(1);
                    } else if (i == 2) {
                        if (br_is_download_url(browser_url)) {
                            br_download(browser_url);
                        } else if (browser_url_len > 0) {
                            browser_load();
                            desktop_redraw();
                        }
                    } else if (i == 3) {
                        br_bmk_toggle();
                    } else if (i == 4) {
                        br_panel_open(1);
                    } else if (i == 5) {
                        br_panel_open(2);
                    }
                    return;
                }
            }
        }
    }
    if (desk_mode == DESK_BROWSER && browser_state == 1) {
        /* Clicking a link segment follows it; clicking a
         * form control focuses or submits it. */
        int64_t row_y = (int64_t)BR_CONTENT_TOP(text_y());
        if (y >= row_y) {
            int yy = (int)row_y;
            for (int li = browser_scroll; li < br_line_count;
                 li++) {
                br_line *ln = &br_lines[li];
                if (y < yy + ln->h_px) {
                    int lx = x - (int)text_x() - ln->xoff;
                    int done = 0;
                    for (int si = 0; si < ln->nsegs; si++) {
                        br_seg *s = &ln->segs[si];
                        if (lx >= s->x && lx < s->x + s->w) {
                            if (s->ctrl >= 0) {
                                br_ctrl_click(s->ctrl);
                                done = 1;
                            } else if (s->link >= 0) {
                                br_navigate(br_links[s->link]);
                                done = 1;
                            }
                            break;
                        }
                    }
                    if (!done && br_ctrl_focus >= 0) {
                        br_ctrl_focus = -1;
                        desktop_redraw();
                    }
                    break;
                }
                yy += ln->h_px;
            }
        }
        return;
    }
    if (desk_mode == DESK_FILES && files_viewing < 0) {
        files_build_rows();
        int64_t row_y = (int64_t)text_y() + 2 * CELL_H;
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H) {
            /* パンくずの区間クリックで移動。 */
            uint64_t cx = text_x() + 22;
            int nseg = files_crumb_count();
            const char *seg = files_dir;
            for (int sgi = 0; sgi < nseg; sgi++) {
                char part[28];
                size_t pp = 0;
                if (sgi == 0) {
                    const char *rt = L("Root", "ルート");
                    while (rt[pp] != '\0' && pp + 1 < sizeof(part)) {
                        part[pp] = rt[pp];
                        pp++;
                    }
                } else {
                    while (seg[pp] != '\0' && seg[pp] != '/' &&
                           pp + 1 < sizeof(part)) {
                        part[pp] = seg[pp];
                        pp++;
                    }
                }
                part[pp] = '\0';
                uint64_t w = fb_text_aa_width(part, aa_px_body(),
                                              0);
                if ((uint64_t)x >= cx && (uint64_t)x < cx + w) {
                    files_goto_crumb(sgi);
                    return;
                }
                cx += w + CELL_W + 4;
                while (*seg != '\0' && *seg != '/') {
                    seg++;
                }
                if (*seg == '/') {
                    seg++;
                }
            }
            return;
        }
        if (y >= (int)text_y() + (int)CELL_H && y < row_y) {
            /* ツールバーのボタンクリック。 */
            for (int i = 0; i < files_tool_n; i++) {
                if (x >= files_tool_x[i] &&
                    x < files_tool_x[i] + files_tool_w[i]) {
                    files_toolbar_click(i);
                    return;
                }
            }
            return;
        }
        if (y >= row_y && x < (int)files_x() - 8) {
            /* 場所サイドバーのクリック。 */
            files_places_build();
            int idx = (int)((y - row_y) / FILES_ROW_H);
            if (idx >= 0 && idx < files_places_count) {
                files_goto_place(idx);
            }
            return;
        }
        if (files_grid && y >= row_y) {
            /* グリッドのタイルクリック。 */
            uint64_t fx = files_x();
            int cols = (int)((win_x() + win_w() - 12 - fx) / 108);
            if (cols < 1) {
                cols = 1;
            }
            if (x >= (int)fx) {
                int col = (x - (int)fx) / 108;
                int grow = (int)((y - row_y) / 96);
                int idx = grow * cols + col;
                if (col < cols && idx >= 0 &&
                    idx < files_row_count &&
                    x < (int)fx + col * 108 + 100) {
                    if (idx == files_selected &&
                        idx == files_last_click_row) {
                        files_activate_row();
                        files_last_click_row = -1;
                    } else {
                        files_selected = idx;
                        files_last_click_row = idx;
                        files_last_click_tick = tick_counter;
                    }
                    desktop_refresh_console();
                }
            }
            return;
        }
        int row = files_top + (int)((y - row_y) / FILES_ROW_H);
        if (row >= 0 && row < files_row_count &&
            x >= (int)files_x() &&
            x < (int)(win_x() + win_w() - 12)) {
            /* 選択済みの行の再クリックは、ダブルクリック
             * 間隔 (設定値) の中だけ「開く」にする。
             * 較正前は従来どおり常時開く。 */
            unsigned long win_ticks =
                desk_ticks_per_sec *
                (unsigned long)desk_settings.dblclick_ms / 1000;
            if (row == files_selected &&
                row == files_last_click_row &&
                (win_ticks == 0 ||
                 tick_counter - files_last_click_tick <=
                     win_ticks)) {
                files_activate_row();
                files_last_click_row = -1;
            } else {
                files_selected = row;
                files_last_click_row = row;
                files_last_click_tick = tick_counter;
            }
            desktop_refresh_console();
        }
    }
    if (desk_mode == DESK_STORE && !store_srv_mode &&
        !store_apps_view) {
        /* ストアのボタンとタイル (C20)。 */
        if (store_ui_count == 0) {
            int64_t by = (int64_t)text_y() + 4 * CELL_H;
            if (y >= by && y < by + (int)CELL_H + 6) {
                if (x >= store_btn_x[0] &&
                    x < store_btn_x[0] + store_btn_w[0]) {
                    store_srv_open();
                    desktop_redraw();
                    return;
                }
                if (x >= store_btn_x[1] &&
                    x < store_btn_x[1] + store_btn_w[1]) {
                    desktop_handle_key_inner('r');
                    return;
                }
            }
            return;
        }
        for (int i = 0; i < store_ui_count; i++) {
            if (x >= store_tile_btn_x[i] &&
                x < store_tile_btn_x[i] + store_tile_btn_w[i] &&
                y >= store_tile_btn_y[i] &&
                y < store_tile_btn_y[i] + (int)CELL_H) {
                store_ui_sel = i;
                desktop_handle_key_inner('\n');
                return;
            }
            uint64_t tx = text_x() + (uint64_t)(i % 3) * 240;
            uint64_t ty = text_y() + (uint64_t)(2 * CELL_H) +
                          (uint64_t)(i / 3) * 76;
            if (x >= (int)tx && x < (int)tx + 228 && y >= (int)ty &&
                y < (int)ty + 68) {
                store_ui_sel = i;
                desktop_redraw();
                return;
            }
        }
        return;
    }
    if (desk_mode == DESK_EDITOR && editor_stage == 0) {
        /* 保存ボタン (C18)。 */
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H &&
            x >= editor_btn_x && x < editor_btn_x + editor_btn_w) {
            editor_save();
            desktop_redraw();
            return;
        }
        /* 開くボタン: Ctrl+G (0xB6) と同じ経路。 */
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H &&
            x >= editor_btn2_x &&
            x < editor_btn2_x + editor_btn2_w) {
            desktop_handle_key_inner(0xB6);
            return;
        }
        return;
    }
    if (desk_mode == DESK_CONTACTS && contacts_stage == 0) {
        /* 追加ボタンと行クリック (C17)。 */
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H &&
            x >= contacts_btn_x &&
            x < contacts_btn_x + contacts_btn_w) {
            desktop_handle_key_inner('n');
            return;
        }
        int row = (y - (int)text_y()) / (int)CELL_H - 2;
        if (row >= 0 && row < contacts_count()) {
            if (row == contacts_sel) {
                desktop_handle_key_inner('\n');
            } else {
                contacts_sel = row;
                desktop_redraw();
            }
            return;
        }
        return;
    }
    if (desk_mode == DESK_CAMERA) {
        /* 開始/停止・撮影・形式切替ボタン (D3)。 */
        if (y >= cam_btn_y && y < cam_btn_y + (int)CELL_H + 10) {
            for (int i = 0; i < 3; i++) {
                if (x >= cam_btn_x[i] &&
                    x < cam_btn_x[i] + cam_btn_w[i]) {
                    if (i == 0) {
                        if (cam_streaming) {
                            cam_stop_stream();
                        } else {
                            cam_start_stream();
                        }
                    } else if (i == 1) {
                        cam_capture();
                    } else {
                        (void)cam_handle_key(DESK_KEY_RIGHT);
                    }
                    desktop_redraw();
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_RECORDER) {
        /* 録音ボタン (D4)。 */
        int ry = (int)(text_y() + 3 * CELL_H);
        if (y >= ry && y < ry + (int)CELL_H + 10 &&
            x >= rec_btn_x[0] && x < rec_btn_x[0] + rec_btn_w[0]) {
            rec_do_record();
            return;
        }
        /* 一覧の行クリックで選択。 */
        int ly = (int)(text_y() + 9 * CELL_H);
        if (y >= ly) {
            int row = (y - ly) / (int)CELL_H;
            int list[PRISM_VFS_MAX_FILES];
            int count = rec_list(list, PRISM_VFS_MAX_FILES);
            if (row >= 0 && row < count) {
                rec_sel = row;
                desktop_redraw();
                return;
            }
        }
        /* 再生 / 停止 / 削除ボタン。 */
        if (y >= rec_btn_y && y < rec_btn_y + (int)CELL_H + 10) {
            for (int i = 0; i < 3; i++) {
                if (x >= rec_btn_x[1 + i] &&
                    x < rec_btn_x[1 + i] + rec_btn_w[1 + i]) {
                    if (i == 0) {
                        rec_do_play();
                    } else if (i == 1) {
                        if (rec_playing) {
                            sb16_stop();
                            rec_playing = 0;
                            serial_write_line("recorder: stopped");
                        }
                    } else {
                        (void)rec_handle_key('d');
                    }
                    desktop_redraw();
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_CLOCK) {
        /* タブ (D5)。 */
        int ty = (int)(text_y() + 2 * CELL_H);
        if (y >= ty && y < ty + (int)CELL_H + 8) {
            for (int i = 0; i < 4; i++) {
                if (x >= clock_tab_x[i] &&
                    x < clock_tab_x[i] + clock_tab_w[i]) {
                    clock_tab = i;
                    desktop_redraw();
                    return;
                }
            }
        }
        if (clock_tab == 1) {
            /* アラームのオン/オフピル。 */
            int by = (int)(text_y() + 5 * CELL_H);
            if (y >= by && y < by + (int)CELL_H + 8 &&
                x >= clock_big_x + 270 && x < clock_big_x + 400) {
                clock_alarm_on = !clock_alarm_on;
                serial_write_line(clock_alarm_on
                                      ? "clock: alarm on"
                                      : "clock: alarm off");
                desktop_redraw();
            }
            return;
        }
        if ((clock_tab == 2 || clock_tab == 3) &&
            y >= clock_btn_y && y < clock_btn_y + (int)CELL_H + 10) {
            for (int i = 0; i < 2; i++) {
                if (x >= clock_btn_x[i] &&
                    x < clock_btn_x[i] + clock_btn_w[i]) {
                    if (i == 0) {
                        if (clock_tab == 2) {
                            clock_timer_toggle();
                        } else {
                            clock_sw_toggle();
                        }
                    } else if (clock_tab == 2) {
                        clock_timer_state = 0;
                        serial_write_line("clock: timer reset");
                    } else {
                        clock_sw_state = 0;
                        clock_sw_accum = 0;
                        serial_write_line("clock: stopwatch reset");
                    }
                    desktop_redraw();
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_NOTIF) {
        /* すべて消去ボタン (C21)。 */
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H &&
            x >= notif_clear_x && x < notif_clear_x + notif_clear_w) {
            notify_hist_count = 0;
            notify_hist_save();
            serial_write_line("notify: history cleared");
            desktop_redraw();
        }
        return;
    }
    if (desk_mode == DESK_VIDEO && video_frame_count > 0) {
        /* シークバーと再生ボタン (C12)。 */
        if (y >= video_seek_y && y < video_seek_y + 10 &&
            x >= video_seek_x && x < video_seek_x + video_seek_w) {
            int f = (x - video_seek_x) * video_frame_count /
                    video_seek_w;
            if (f < 0) {
                f = 0;
            }
            if (f >= video_frame_count) {
                f = video_frame_count - 1;
            }
            video_player_state.frame = f;
            video_arm_next_tick();
            desktop_redraw();
            return;
        }
        if (y >= video_btn_y && y < video_btn_y + (int)CELL_H) {
            static const int vkeys[4] = {'p', ' ', 'n', 'r'};
            for (int i = 0; i < 4; i++) {
                if (x >= video_btn_x[i] &&
                    x < video_btn_x[i] + video_btn_w[i]) {
                    desktop_handle_key_inner(vkeys[i]);
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_SHEET && !sheet_chart) {
        /* ツールバーとセル選択のクリック (C11)。 */
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H) {
            for (int i = 0; i < 3; i++) {
                if (x >= sheet_btn_x[i] &&
                    x < sheet_btn_x[i] + sheet_btn_w[i]) {
                    if (i == 0) {
                        sheet_save();
                    } else if (i == 1) {
                        sheet_chart = 1;
                    } else {
                        desktop_handle_key_inner(
                            PRISM_KEY_CTRL_LETTER_BASE +
                            ('f' - 'a'));
                        return;
                    }
                    desktop_redraw();
                    return;
                }
            }
        }
        int64_t gy = (int64_t)SHEET_GRID_Y(text_y());
        int64_t gx = (int64_t)text_x() + SHEET_GUTTER;
        if (y >= gy && x >= gx) {
            int col = (int)((x - gx) / SHEET_COL_W);
            int row = (int)((y - gy) / SHEET_ROW_H);
            if (col >= 0 && col < SHEET_VIEW_COLS && row >= 0 &&
                row < SHEET_VIEW_ROWS) {
                sheet_commit_edit();
                sheet_sel_col = sheet_view_col + col;
                sheet_sel_row = sheet_view_row + row;
                desktop_refresh_console();
            }
        }
        return;
    }
    if (desk_mode == DESK_CALENDAR) {
        /* 前月/次月ボタン (B6)。 */
        int64_t nby = (int64_t)text_y() - 2;
        if (y >= nby && y < nby + (int)CELL_H + 4) {
            for (int i = 0; i < 2; i++) {
                if (x >= cal_nav_x[i] &&
                    x < cal_nav_x[i] + 36) {
                    cal_offset += i == 0 ? -1 : 1;
                    desktop_redraw();
                    return;
                }
            }
        }
        /* 日のクリックで選択 (C6)。 */
        int gx = x - cal_grid_x;
        int gy = y - (cal_grid_y + (int)CELL_H);
        if (gx >= 0 && gy >= 0 && cal_pitch > 0) {
            int c = gx / cal_pitch;
            int r = gy / cal_rpitch;
            int d = r * 7 + c - cal_first + 1;
            if (c < 7 && d >= 1 && d <= cal_days) {
                cal_sel_day = d;
                desktop_redraw();
            }
        }
        return;
    }
    if (desk_mode == DESK_NOTES) {
        /* ツールバーのクリック (C5+B4): 保存は直接、
         * 他はキーコード (Ctrl+Z/Y/F/H) と同じ経路。 */
        int64_t by = (int64_t)text_y() + CELL_H + 2;
        if (y >= by && y < by + (int)CELL_H) {
            static const char nkeys[5] = {0, (char)0xC9,
                                          (char)0xC8, (char)0xB5,
                                          (char)0xB7};
            for (int i = 0; i < 5; i++) {
                if (x >= notes_btn_x[i] &&
                    x < notes_btn_x[i] + notes_btn_w[i]) {
                    if (i == 0) {
                        notes_save();
                        desktop_redraw();
                    } else {
                        desktop_handle_key_inner(nkeys[i]);
                    }
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_MUSIC) {
        /* 再生ボタンのクリック (C8)。 */
        int64_t by = (int64_t)text_y() +
                     (text_rows() - 4) * CELL_H;
        if (y >= by && y < by + (int)CELL_H) {
            for (int i = 0; i < 3; i++) {
                if (x >= music_btn_x[i] &&
                    x < music_btn_x[i] + music_btn_w[i]) {
                    if (i == 0) {
                        music_play_selected();
                    } else if (i == 1) {
                        music_pause_toggle();
                    } else {
                        music_stop();
                    }
                    desktop_redraw();
                    return;
                }
            }
            /* 音量 -/+ ボタン (B8)。 */
            for (int i = 0; i < 2; i++) {
                if (x >= music_vol_x[i] &&
                    x < music_vol_x[i] + music_vol_w[i]) {
                    volume_adjust(i == 0 ? -10 : 10);
                    desktop_redraw();
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_SLIDES && !slides_show) {
        /* 発表ボタンと左一覧のクリック (C16)。 */
        if (y >= (int)text_y() && y < (int)text_y() + (int)CELL_H + 2 &&
            x >= slides_btn_x && x < slides_btn_x + slides_btn_w) {
            slides_commit_edit();
            slides_show = 1;
            desktop_redraw();
            return;
        }
        /* 新規/保存ボタン (B5): 全体キー処理と同じ経路。 */
        if (y >= (int)text_y() &&
            y < (int)text_y() + (int)CELL_H + 2) {
            for (int i = 0; i < 2; i++) {
                if (x >= slides_btn2_x[i] &&
                    x < slides_btn2_x[i] + slides_btn2_w[i]) {
                    desktop_handle_key_inner(
                        i == 0 ? DESK_KEY_CTRL_N : DESK_KEY_F6);
                    return;
                }
            }
        }
        int64_t ly = (int64_t)text_y() + 2 * CELL_H;
        if (x >= (int)text_x() && x < (int)text_x() + 140 &&
            y >= ly) {
            int idx = (int)((y - ly) / 60);
            if (idx >= 0 && idx < slides_deck.count &&
                y < ly + idx * 60 + 54) {
                slides_commit_edit();
                slides_current = idx;
                slides_field = 0;
                slides_editing = 0;
                desktop_redraw();
                return;
            }
        }
        return;
    }
    if (desk_mode == DESK_DOCS) {
        /* ツールバーのクリック (C15)。 */
        int64_t by = (int64_t)text_y() + CELL_H + 2;
        if (y >= by && y < by + (int)CELL_H) {
            for (int i = 0; i < 7; i++) {
                if (x >= docs_btn_x[i] &&
                    x < docs_btn_x[i] + docs_btn_w[i]) {
                    if (i <= 4) {
                        static const doc_line_type kinds[5] = {
                            DOC_LINE_H1, DOC_LINE_H2,
                            DOC_LINE_H3, DOC_LINE_BULLET,
                            DOC_LINE_PLAIN};
                        docs_history_push();
                        doc_set_line_type(&docs_doc, kinds[i]);
                        docs_dirty = 1;
                        docs_saved = 0;
                    } else if (i == 5) {
                        docs_save();
                    } else {
                        docs_export();
                    }
                    desktop_redraw();
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_MAIL && mail_setup_mode) {
        /* 設定フォームのクリック (C14)。 */
        if (y >= mail_save_btn_y &&
            y < mail_save_btn_y + (int)CELL_H + 4 &&
            x >= mail_save_btn_x &&
            x < mail_save_btn_x + mail_save_btn_w) {
            mail_setup_field = 12;
            desktop_handle_key_inner('\n');
            return;
        }
        int row = (y - (int)text_y()) / (int)CELL_H;
        int f = row - 3;
        if (f >= 0 && f < 12) {
            mail_setup_field = f;
            if (f >= 9) {
                desktop_handle_key_inner('\n');
            } else {
                desktop_redraw();
            }
            return;
        }
        return;
    }
    if (desk_mode == DESK_INSTALLER &&
        inst_step != INSTALL_STEP_CONFIRM &&
        inst_step != INSTALL_STEP_INSTALLING) {
        /* ナビボタン (A3): 記録されたキーへ流す。 */
        if (y >= inst_nav_y &&
            y < inst_nav_y + (int)CELL_H + 6) {
            for (int i = 0; i < inst_nav_n; i++) {
                if (x >= inst_nav_x[i] &&
                    x < inst_nav_x[i] + inst_nav_w[i]) {
                    desktop_handle_key_inner(inst_nav_key[i]);
                    return;
                }
            }
        }
        /* ディスク対象の選択ボタン (a/d/w)。 */
        if (inst_step == INSTALL_STEP_DISK && inst_has_disk) {
            int64_t ty2 = (int64_t)text_y() + 12 * CELL_H;
            if (y >= ty2 && y < ty2 + (int)CELL_H + 6) {
                static const char tkeys[3] = {'a', 'd', 'w'};
                for (int i = 0; i < 3; i++) {
                    if (x >= inst_tgt_x[i] &&
                        x < inst_tgt_x[i] + inst_tgt_w[i]) {
                        desktop_handle_key_inner(tkeys[i]);
                        return;
                    }
                }
            }
        }
        /* プロファイルの2行はクリックで選択 (1/2)。 */
        if (inst_step == INSTALL_STEP_PROFILE) {
            int64_t ry = (int64_t)text_y();
            if (y >= ry + 2 * CELL_H && y < ry + 3 * CELL_H &&
                x >= (int)text_x()) {
                desktop_handle_key_inner('1');
                return;
            }
            if (y >= ry + 3 * CELL_H && y < ry + 4 * CELL_H &&
                x >= (int)text_x()) {
                desktop_handle_key_inner('2');
                return;
            }
        }
    }
    if (desk_mode == DESK_INSTALLER &&
        inst_step == INSTALL_STEP_CONFIRM) {
        /* 確認ボタンのクリック (C13)。 */
        if (y >= inst_btn_y && y < inst_btn_y + (int)CELL_H + 6) {
            if (x >= inst_btn_x[0] &&
                x < inst_btn_x[0] + inst_btn_w[0]) {
                desktop_handle_key_inner('y');
                return;
            }
            if (x >= inst_btn_x[1] &&
                x < inst_btn_x[1] + inst_btn_w[1]) {
                desktop_handle_key_inner(0x1B);
                return;
            }
        }
        return;
    }
    if (desk_mode == DESK_CARDS && cards_game == 0) {
        /* メニューのタイルクリック (C9)。 */
        for (int g = 1; g <= 7; g++) {
            if (x >= cards_tile_x(g) && x < cards_tile_x(g) + 190 &&
                y >= cards_tile_y(g) &&
                y < cards_tile_y(g) + 108) {
                cards_select_game(g);
                desktop_redraw();
                return;
            }
        }
        return;
    }
    if (desk_mode == DESK_PAINT) {
        /* パレット行のクリック (C19)。 */
        int64_t by = (int64_t)text_y() + CELL_H + 2;
        if (y >= by && y < by + 26) {
            for (int i = 0; i < 13; i++) {
                if (x >= paint_btn_x[i] &&
                    x < paint_btn_x[i] + paint_btn_w[i]) {
                    if (i < 8) {
                        paint_color = i;
                    } else if (i < 11) {
                        paint_brush = i - 7;
                    } else if (i == 11) {
                        for (int j = 0; j < PAINT_W * PAINT_H;
                             j++) {
                            paint_cells[j] = 0;
                        }
                        inst_copy(paint_status,
                                  sizeof(paint_status),
                                  L("Cleared.", "消去しました"));
                    } else {
                        paint_save_bmp();
                    }
                    desktop_redraw();
                    return;
                }
            }
        }
        /* キャンバスのクリックで塗る。 */
        int64_t cx0 = (int64_t)paint_cx0();
        int64_t cy0 = (int64_t)paint_cy0();
        if (x >= cx0 && x < cx0 + PAINT_W * PAINT_CELL &&
            y >= cy0 && y < cy0 + PAINT_H * PAINT_CELL) {
            paint_cx = (x - cx0) / PAINT_CELL;
            paint_cy = (y - cy0) / PAINT_CELL;
            paint_apply(paint_cx, paint_cy);
            desktop_redraw();
        }
        return;
    }
    if (desk_mode == DESK_MAIL && mail_viewing < 0 &&
        !mail_composing && !mail_setup_mode) {
        /* ツールバーボタン (A2): 既存のキー処理へ流す。
         * 移動モード中は行1が入力行になるので無効。 */
        if (!mail_move_mode) {
            int64_t tby = (int64_t)text_y() + CELL_H;
            if (y >= tby && y < tby + (int)CELL_H) {
                static const char mkeys[5] = {'c', 'r', 'm',
                                              'd', 'o'};
                for (int i = 0; i < 5; i++) {
                    if (x >= mail_btn_x[i] &&
                        x < mail_btn_x[i] + mail_btn_w[i]) {
                        desktop_handle_key_inner(mkeys[i]);
                        return;
                    }
                }
            }
        }
        int top = mail_pane_top();
        if (y >= top) {
            /* フォルダペイン: クリックで切替。 */
            if (x >= (int)text_x() &&
                x < (int)text_x() + MAIL_FOLDER_W) {
                int row = (y - top) / UI_LIST_ROW;
                char names[8][24];
                int nn = mail_folder_list(names, 8);
                if (row >= 0 && row < nn) {
                    inst_copy(mail_folder, sizeof(mail_folder),
                              names[row]);
                    mail_selected = 0;
                    mail_viewing = -1;
                    mail_list_top = 0;
                    mail_rebuild();
                    serial_write("mail: folder ");
                    serial_write_line(mail_folder_cur());
                    desktop_refresh_console();
                }
            }
            /* 一覧ペイン: クリックで選択、再クリックで開く。 */
            if (x >= mail_list_x() &&
                x < mail_list_x() + mail_list_w()) {
                int row = mail_list_top +
                          (y - top) / UI_LIST_ROW;
                if (row >= 0 && row < mail_list_count) {
                    if (row == mail_selected) {
                        mail_viewing = row;
                        mail_scroll = 0;
                    } else {
                        mail_selected = row;
                    }
                    desktop_refresh_console();
                }
            }
        }
    }
    if (desk_mode == DESK_PHOTOS && photos_viewing >= 0) {
        /* ビューアのボタン (C7): キー操作と同じ経路。 */
        int64_t by = (int64_t)text_y() +
                     (text_rows() - 3) * CELL_H;
        if (y >= by && y < by + (int)CELL_H) {
            static const int bkeys[6] = {
                DESK_KEY_LEFT, DESK_KEY_RIGHT, '+', '-',
                'r', 'w'};
            for (int i = 0; i < 6; i++) {
                if (x >= photos_btn_x[i] &&
                    x < photos_btn_x[i] + photos_btn_w[i]) {
                    desktop_handle_key_inner(bkeys[i]);
                    return;
                }
            }
        }
        return;
    }
    if (desk_mode == DESK_PHOTOS && photos_viewing < 0) {
        /* サムネイルグリッドのクリック (C7)。 */
        int list[PRISM_VFS_MAX_FILES];
        int count = photos_list(list, PRISM_VFS_MAX_FILES);
        int cols = (int)((win_w() - 16) / 128);
        if (cols < 1) {
            cols = 1;
        }
        int64_t gy = (int64_t)text_y() + 2 * CELL_H;
        if (y >= gy && x >= (int)text_x()) {
            int col = (x - (int)text_x()) / 128;
            int grow = (int)((y - gy) / 104);
            int idx = grow * cols + col;
            if (col < cols && idx >= 0 && idx < count &&
                x < (int)text_x() + col * 128 + 120) {
                if (idx == photos_selected) {
                    photos_viewing = idx;
                    photos_zoom = 0;
                    photos_rot = 0;
                } else {
                    photos_selected = idx;
                }
                desktop_refresh_console();
            }
        }
    }
}

/* ドラッグの落下処理 (項目18)。 */
static void drag_drop_at(int x, int y) {
    const char *base = drag_name;
    for (const char *p = drag_name; *p != '\0'; p++) {
        if (*p == '/') {
            base = p + 1;
        }
    }
    if (desk_mode == DESK_FILES && files_viewing < 0 &&
        !files_grid) {
        files_build_rows();
        int64_t row_y = (int64_t)text_y() + 2 * CELL_H;
        int row = files_top + (int)((y - row_y) / FILES_ROW_H);
        if (row >= 0 && row < files_row_count &&
            x >= (int)files_x() &&
            x < (int)(win_x() + win_w() - 12)) {
            int v = files_rows[row];
            if (v <= -2 || v == -1) {
                /* フォルダ行 (または親) へ移動する。
                 * バッファは最長パス (親 31 + '/' + フォルダ名
                 * 27、宛先はさらに '/' + 名前 31) が収まる大きさ
                 * にし、組み立て前に長さを確認して、途中で
                 * 切れた先へは動かさない (監査 L7)。 */
                char dirpath[64];
                size_t dp = 0;
                if (v == -1) {
                    /* 親フォルダ = files_dir の末尾を落とす。 */
                    size_t n = 0;
                    while (files_dir[n] != '\0') {
                        n++;
                    }
                    while (n > 0 && files_dir[n - 1] != '/') {
                        n--;
                    }
                    if (n > 0) {
                        n--;
                    }
                    while (dp < n && dp + 1 < sizeof(dirpath)) {
                        dirpath[dp] = files_dir[dp];
                        dp++;
                    }
                } else {
                    const char *dn = files_dirnames[-2 - v];
                    if (strcmp(dn, "trash") == 0) {
                        if (files_trash_file(drag_name) == 0) {
                            serial_write("drag: trashed ");
                            serial_write_line(drag_name);
                            desktop_notify(L("Moved to trash",
                                             "ゴミ箱へ移動しました"));
                            persist_maybe_sync();
                        } else {
                            serial_write_line("drag: cancelled");
                        }
                        files_build_rows();
                        desktop_redraw();
                        return;
                    }
                    size_t need = strlen(files_dir) +
                                  (files_dir[0] != '\0' ? 1 : 0) +
                                  strlen(dn);
                    if (need + 1 > sizeof(dirpath)) {
                        serial_write_line("drag: cancelled");
                        desktop_redraw();
                        return;
                    }
                    size_t q = 0;
                    while (files_dir[q] != '\0' &&
                           dp + 1 < sizeof(dirpath)) {
                        dirpath[dp++] = files_dir[q++];
                    }
                    if (dp > 0 && dp + 1 < sizeof(dirpath)) {
                        dirpath[dp++] = '/';
                    }
                    q = 0;
                    while (dn[q] != '\0' && dp + 1 < sizeof(dirpath)) {
                        dirpath[dp++] = dn[q++];
                    }
                }
                dirpath[dp] = '\0';
                char dst[96];
                if (strlen(dirpath) + 1 + strlen(base) + 1 >
                    sizeof(dst)) {
                    serial_write_line("drag: cancelled");
                    desktop_redraw();
                    return;
                }
                size_t p = 0;
                while (dirpath[p] != '\0' && p + 1 < sizeof(dst)) {
                    dst[p] = dirpath[p];
                    p++;
                }
                if (p > 0 && p + 1 < sizeof(dst)) {
                    dst[p++] = '/';
                }
                size_t q = 0;
                while (base[q] != '\0' && p + 1 < sizeof(dst)) {
                    dst[p++] = base[q++];
                }
                dst[p] = '\0';
                if (strcmp(dst, drag_name) == 0 ||
                    vfs_exists(dst)) {
                    serial_write_line("drag: cancelled");
                    desktop_redraw();
                    return;
                }
                size_t len = 0;
                const char *content = vfs_read_ptr(drag_name, &len);
                if (content != NULL &&
                    vfs_write(dst, content, len) == 0) {
                    (void)vfs_delete(drag_name);
                    serial_write("drag: moved ");
                    serial_write(drag_name);
                    serial_write(" -> ");
                    serial_write_line(dst);
                    desktop_notify(L("Moved", "移動しました"));
                    persist_maybe_sync();
                } else {
                    serial_write_line("drag: cancelled");
                }
                files_build_rows();
                desktop_redraw();
                return;
            }
        }
    }
    /* Dock の対応アプリで開く。 */
    int di = dock_button_at(x, y);
    if (di >= 0) {
        desktop_mode m = desk_visible_mode(di);
        if (m == DESK_PHOTOS &&
            name_ends_with(drag_name, ".bmp")) {
            int list[PRISM_VFS_MAX_FILES];
            int count = photos_list(list, PRISM_VFS_MAX_FILES);
            for (int i = 0; i < count; i++) {
                if (strcmp(vfs_file_name(list[i]), drag_name) ==
                    0) {
                    photos_viewing = i;
                    photos_selected = i;
                    photos_zoom = 0;
                    photos_rot = 0;
                    switch_mode(DESK_PHOTOS);
                    serial_write("drag: opened ");
                    serial_write_line(drag_name);
                    desktop_redraw();
                    return;
                }
            }
        }
        if (m == DESK_EDITOR) {
            size_t q = 0;
            while (drag_name[q] != '\0' &&
                   q + 1 < sizeof(editor_name)) {
                editor_name[q] = drag_name[q];
                q++;
            }
            editor_name[q] = '\0';
            editor_loaded = 0;
            switch_mode(DESK_EDITOR);
            serial_write("drag: opened ");
            serial_write_line(drag_name);
            desktop_redraw();
            return;
        }
    }
    serial_write_line("drag: cancelled");
    desktop_redraw();
}

/* ドラッグ中のチップ表示。 */
static void draw_drag_chip(void) {
    if (!drag_active) {
        return;
    }
    uint64_t w = 16 + fb_text_aa_width(drag_name, aa_px_body(),
                                       0);
    uint64_t cx = (uint64_t)(mouse_x + 12);
    uint64_t cy = (uint64_t)(mouse_y + 14);
    if (cx + w > fb_width()) {
        cx = fb_width() - w;
    }
    if (cy + 20 > fb_height()) {
        cy = fb_height() - 20;
    }
    fb_fill_rect(cx, cy, w, 20, col_accent());
    draw_text_small(cx + 6, cy + 2, drag_name, rgb(0xFFFFFF),
                    col_accent());
}

/* ---- 内蔵アプリのフォルト封じ込め (appguard) ----
 * 入力ディスパッチの武装つきラッパー。封じ込めの共通
 * 処理は desk_contain_fault (描画側と共用)。 */
static void desktop_mouse_poll_inner(void);

void desktop_mouse_poll(void) {
    if (appguard_enter() != 0) {
        desk_contain_fault("mouse");
        return;
    }
    desktop_mouse_poll_inner();
    appguard_leave();
}

static void desktop_mouse_poll_inner(void) {
    if (!desk_ok || desk_locked) {
        return;
    }
    int dx = 0;
    int dy = 0;
    int buttons = 0;
    int have = mouse_poll(&dx, &dy, &buttons);
    if (!have) {
        /* virtio タブレット (絶対座標) が動いていれば、
         * カーソルをその位置へ置いてボタン状態を使う。 */
        int ax = 0;
        int ay = 0;
        int ab = 0;
        if (vinput_poll(&ax, &ay, &ab, (int)fb_width(),
                        (int)fb_height())) {
            mouse_set_position(ax, ay);
            buttons = ab;
            have = 1;
        }
    }
    if (!have) {
        return;
    }
    if (desk_mode == DESK_SHOOTER) {
        /* In the shooter the mouse aims: horizontal movement
         * turns the player, a left click shoots. The cursor
         * itself stays where it is. */
        int steps = dx / 2;
        if (steps > 32) {
            steps = 32;
        }
        if (steps < -32) {
            steps = -32;
        }
        if (steps != 0 && shooter_game_state.phase == 1) {
            shooter_turn(&shooter_game_state, steps);
        }
        int left_pressed = (buttons & 1) && !(mouse_prev_buttons & 1);
        mouse_prev_buttons = buttons;
        if (left_pressed) {
            shooter_fire();
        }
        desktop_redraw();
        return;
    }
    mouse_position(&mouse_x, &mouse_y);
    int left_pressed = (buttons & 1) && !(mouse_prev_buttons & 1);
    int right_pressed = (buttons & 2) && !(mouse_prev_buttons & 2);
    mouse_prev_buttons = buttons;
    if (win_drag >= 0) {
        if (buttons & 1) {
            int nx = mouse_x - win_drag_dx;
            int ny = mouse_y - win_drag_dy;
            if (nx < 0) {
                nx = 0;
            }
            if (ny < 0) {
                ny = 0;
            }
            if (nx > (int)fb_width() - 60) {
                nx = (int)fb_width() - 60;
            }
            if (ny > (int)fb_height() - 40) {
                ny = (int)fb_height() - 40;
            }
            win_px[win_drag] = nx;
            win_py[win_drag] = ny;
        } else {
            win_drag = -1;
        }
    }
    /* ドラッグ&ドロップの開始・追跡・落下 (項目18)。 */
    if (left_pressed && desk_mode == DESK_FILES &&
        files_viewing < 0 && !files_grid && !menu_active &&
        !launcher_active && !widgets_open) {
        files_build_rows();
        int64_t row_y = (int64_t)text_y() + 2 * CELL_H;
        int row = files_top +
                  (int)((mouse_y - row_y) / FILES_ROW_H);
        if (row >= 0 && row < files_row_count &&
            files_rows[row] >= 0 && mouse_x >= (int)files_x() &&
            mouse_x < (int)(win_x() + win_w() - 12)) {
            const char *nm = vfs_file_name(files_rows[row]);
            if (nm != NULL) {
                size_t q = 0;
                while (nm[q] != '\0' && q + 1 < sizeof(drag_name)) {
                    drag_name[q] = nm[q];
                    q++;
                }
                drag_name[q] = '\0';
                drag_pending = 1;
                drag_start_x = mouse_x;
                drag_start_y = mouse_y;
            }
        }
    }
    if (drag_pending && (buttons & 1)) {
        int dx = mouse_x - drag_start_x;
        int dy = mouse_y - drag_start_y;
        if (dx > 8 || dx < -8 || dy > 8 || dy < -8) {
            drag_pending = 0;
            drag_active = 1;
            serial_write("drag: started ");
            serial_write_line(drag_name);
        }
    }
    if (drag_active && !(buttons & 1)) {
        drag_active = 0;
        drag_drop_at(mouse_x, mouse_y);
    } else if (drag_pending && !(buttons & 1)) {
        drag_pending = 0;
    }
    /* ペイントのドラッグ連続描画 (C19)。 */
    if ((buttons & 1) && desk_mode == DESK_PAINT &&
        !menu_active && !launcher_active && !widgets_open) {
        int64_t pcx0 = (int64_t)paint_cx0();
        int64_t pcy0 = (int64_t)paint_cy0();
        if (mouse_x >= pcx0 &&
            mouse_x < pcx0 + PAINT_W * PAINT_CELL &&
            mouse_y >= pcy0 &&
            mouse_y < pcy0 + PAINT_H * PAINT_CELL) {
            paint_cx = (int)((mouse_x - pcx0) / PAINT_CELL);
            paint_cy = (int)((mouse_y - pcy0) / PAINT_CELL);
            paint_apply(paint_cx, paint_cy);
            desktop_redraw();
        }
    }
    if (right_pressed) {
        if (menu_active) {
            menu_active = 0;
            desktop_redraw();
        } else if (launcher_active) {
            int cell = launcher_cell_at(mouse_x, mouse_y);
            if (cell >= 0 && cell < desk_visible_count()) {
                menu_open(3, mouse_x, mouse_y, cell);
            } else {
                launcher_active = 0;
                desktop_redraw();
            }
        } else if (desk_mode == DESK_FILES && files_viewing < 0) {
            files_build_rows();
            int64_t row_y = (int64_t)text_y() + 2 * CELL_H;
            int row;
            if (files_grid) {
                int cols = (int)((win_x() + win_w() - 12 -
                                  files_x()) / 108);
                if (cols < 1) {
                    cols = 1;
                }
                int col = (mouse_x - (int)files_x()) / 108;
                int grow = (int)((mouse_y - row_y) / 96);
                row = (mouse_x >= (int)files_x() && col < cols)
                          ? grow * cols + col
                          : -1;
            } else {
                row = files_top +
                      (int)((mouse_y - row_y) / FILES_ROW_H);
            }
            if (row >= 0 && row < files_row_count &&
                mouse_x >= (int)files_x() &&
                mouse_x < (int)(win_x() + win_w() - 12)) {
                files_selected = row;
                menu_open(1, mouse_x, mouse_y, row);
            } else {
                /* 行の外 (サイドバーや空白) でも、現在の
                 * フォルダ向けメニューを出す (B6)。 */
                int drow = -1;
                for (int r = 0; r < files_row_count; r++) {
                    if (files_rows[r] < 0) {
                        drow = r;
                        break;
                    }
                }
                if (drow >= 0) {
                    menu_open(1, mouse_x, mouse_y, drow);
                } else {
                    menu_open(0, mouse_x, mouse_y, -1);
                }
            }
        } else {
            menu_open(0, mouse_x, mouse_y, -1);
        }
    }
    if (left_pressed) {
        desktop_mouse_click(mouse_x, mouse_y);
    }
    desktop_redraw();
}

/* アクション (アプリ起動) を実行する。割り当てキーの判定は
 * desktop_handle_key が行い、ここは起動そのものだけをする。
 * 各アプリの起動手順は従来のキー別処理と同一。 */
static void launch_action(int a) {
    switch (a) {
    case PRISM_ACT_TERMINAL:
        switch_mode(DESK_TERMINAL);
        break;
    case PRISM_ACT_FILES:
        switch_mode(DESK_FILES);
        break;
    case PRISM_ACT_SETTINGS:
        switch_mode(DESK_SETTINGS);
        break;
    case PRISM_ACT_BROWSER:
        switch_mode(DESK_BROWSER);
        break;
    case PRISM_ACT_NOTES:
        if (!desk_mode_visible(DESK_NOTES)) {
            break;
        }
        notes_load();
        switch_mode(DESK_NOTES);
        break;
    case PRISM_ACT_CALENDAR:
        if (!desk_mode_visible(DESK_CALENDAR)) {
            break;
        }
        cal_offset = 0;
        switch_mode(DESK_CALENDAR);
        break;
    case PRISM_ACT_PHOTOS:
        if (!desk_mode_visible(DESK_PHOTOS)) {
            break;
        }
        switch_mode(DESK_PHOTOS);
        break;
    case PRISM_ACT_MUSIC:
        if (!desk_mode_visible(DESK_MUSIC)) {
            break;
        }
        if (!music_checked) {
            music_checked = 1;
            music_has_device = sb16_present();
        }
        switch_mode(DESK_MUSIC);
        break;
    case PRISM_ACT_CARDS:
        if (!desk_mode_visible(DESK_CARDS)) {
            break;
        }
        switch_mode(DESK_CARDS);
        break;
    case PRISM_ACT_SHOOTER:
        if (!desk_mode_visible(DESK_SHOOTER)) {
            break;
        }
        switch_mode(DESK_SHOOTER);
        break;
    case PRISM_ACT_SHEET:
        if (!desk_mode_visible(DESK_SHEET)) {
            break;
        }
        if (!sheet_loaded) {
            sheet_load();
        }
        switch_mode(DESK_SHEET);
        break;
    case PRISM_ACT_VIDEO:
        if (!desk_mode_visible(DESK_VIDEO)) {
            break;
        }
        video_rebuild();
        switch_mode(DESK_VIDEO);
        break;
    case PRISM_ACT_INSTALLER:
        if (!desk_mode_visible(DESK_INSTALLER)) {
            break;
        }
        switch_mode(DESK_INSTALLER);
        break;
    case PRISM_ACT_MAIL:
        if (!desk_mode_visible(DESK_MAIL)) {
            break;
        }
        mail_rebuild();
        switch_mode(DESK_MAIL);
        serial_write_line("mail: opened");
        break;
    case PRISM_ACT_DOCS:
        if (!desk_mode_visible(DESK_DOCS)) {
            break;
        }
        docs_load();
        switch_mode(DESK_DOCS);
        break;
    case PRISM_ACT_SLIDES:
        if (!desk_mode_visible(DESK_SLIDES)) {
            break;
        }
        if (desk_mode == DESK_SLIDES) {
            /* スライド表示中はショーの切り替え (従来の Ctrl+P)。 */
            slides_commit_edit();
            slides_show = !slides_show;
            desktop_redraw();
            break;
        }
        slides_load();
        switch_mode(DESK_SLIDES);
        break;
    case PRISM_ACT_CONTACTS:
        if (!desk_mode_visible(DESK_CONTACTS)) {
            break;
        }
        contacts_status[0] = '\0';
        switch_mode(DESK_CONTACTS);
        break;
    case PRISM_ACT_EDITOR:
        if (!desk_mode_visible(DESK_EDITOR)) {
            break;
        }
        editor_loaded = 0;
        switch_mode(DESK_EDITOR);
        break;
    case PRISM_ACT_PAINT:
        if (!desk_mode_visible(DESK_PAINT)) {
            break;
        }
        switch_mode(DESK_PAINT);
        break;
    case PRISM_ACT_STORE:
        if (!desk_mode_visible(DESK_STORE)) {
            break;
        }
        switch_mode(DESK_STORE);
        serial_write_line("store-ui: opened");
        break;
    case PRISM_ACT_CLOCK:
        if (!desk_mode_visible(DESK_CLOCK)) {
            break;
        }
        switch_mode(DESK_CLOCK);
        serial_write_line("clock: opened");
        break;
    case PRISM_ACT_RECORDER:
        if (!desk_mode_visible(DESK_RECORDER)) {
            break;
        }
        switch_mode(DESK_RECORDER);
        serial_write_line("recorder: opened");
        break;
    case PRISM_ACT_CAMERA:
        if (!desk_mode_visible(DESK_CAMERA)) {
            break;
        }
        switch_mode(DESK_CAMERA);
        serial_write_line("camera: opened");
        break;
    default:
        break;
    }
}

/* 音量を変更し、即適用して自動保存する
 * (Music / Video 共用)。 */
static void volume_adjust(int delta) {
    int v = desk_settings.volume + delta;
    if (v < 0) {
        v = 0;
    }
    if (v > 100) {
        v = 100;
    }
    desk_settings.volume = v;
    sb16_set_volume(v);
    settings_autosave();
    serial_write("settings: volume ");
    serial_write_num(v);
    serial_write_line("");
    char msg[48];
    size_t p = 0;
    const char *h = L("Volume: ", "音量: ");
    while (*h != '\0' && p + 1 < sizeof(msg)) {
        msg[p++] = *h++;
    }
    char num[8];
    int ni = 0;
    if (v == 0) {
        num[ni++] = '0';
    } else {
        char rev[4];
        int ri = 0;
        int x = v;
        while (x > 0 && ri < 3) {
            rev[ri++] = (char)('0' + x % 10);
            x /= 10;
        }
        while (ri > 0) {
            num[ni++] = rev[--ri];
        }
    }
    num[ni++] = '%';
    num[ni] = '\0';
    for (int k = 0; num[k] != '\0' && p + 1 < sizeof(msg); k++) {
        msg[p++] = num[k];
    }
    msg[p] = '\0';
    desktop_notify(msg);
}

/* メール作成への IME 確定文字列の挿入 (件名と本文
 * のみ。宛先と添付名は ASCII のまま)。 */
static void mail_insert_text(const char *text) {
    if (mail_field == 1) {
        size_t n = 0;
        while (mail_subject[n] != '\0') {
            n++;
        }
        for (size_t i = 0; text[i] != '\0'; i++) {
            if (n + 1 < sizeof(mail_subject)) {
                mail_subject[n++] = text[i];
            }
        }
        mail_subject[n] = '\0';
    } else if (mail_field == 2) {
        for (size_t i = 0; text[i] != '\0'; i++) {
            if (mail_body_len + 1 < sizeof(mail_body)) {
                mail_body[mail_body_len++] = text[i];
                mail_body[mail_body_len] = '\0';
            }
        }
    }
}

/* ---- スクリーンショット ----
 * Ctrl+U で現在の画面を 24 ビット BMP (原寸) に保存する。
 * 1280x800 なら 54 + 1280*800*3 = 3072054 バイト。
 * VFS と diskfs は版5 で 4MB まで扱える。 */
#define SHOT_MAX_W 1280
#define SHOT_MAX_H 800
#define SHOT_BUF_SIZE (54 + (size_t)SHOT_MAX_W * SHOT_MAX_H * 3)
static uint8_t shot_buf[SHOT_BUF_SIZE];

static void desktop_screenshot(void) {
    if (!fb_ready()) {
        return;
    }
    uint64_t fw = fb_width();
    uint64_t fh = fb_height();
    if (fw == 0 || fh == 0 || fw > SHOT_MAX_W || fh > SHOT_MAX_H) {
        desktop_notify(L("Screenshot too large",
                         "画面が大きすぎて保存できません"));
        return;
    }
    char name[16];
    const char *base = "shot.bmp";
    size_t bp = 0;
    while (base[bp] != '\0' && bp + 1 < sizeof(name)) {
        name[bp] = base[bp];
        bp++;
    }
    name[bp] = '\0';
    if (vfs_exists(name)) {
        int found = 0;
        for (int i = 1; i <= 9 && !found; i++) {
            /* "shotN.bmp" の形にする (監査 L4: 以前は index 4
             * の '.' を数字で上書きして "shot1bmp" になり、
             * 拡張子判定に載らなかった)。 */
            name[4] = (char)('0' + i);
            name[5] = '.';
            name[6] = 'b';
            name[7] = 'm';
            name[8] = 'p';
            name[9] = '\0';
            if (!vfs_exists(name)) {
                found = 1;
            }
        }
        if (!found) {
            desktop_notify(L("Too many screenshots",
                             "スクリーンショットが多すぎます"));
            return;
        }
    }
    /* BMP (24 ビット、パレット無し、行は 4 バイト境界)。 */
    uint32_t stride = (uint32_t)((fw * 3 + 3) & ~(uint64_t)3);
    uint32_t total = 54 + stride * (uint32_t)fh;
    uint8_t *b = shot_buf;
    for (size_t i = 0; i < total; i++) {
        b[i] = 0;
    }
    b[0] = 'B';
    b[1] = 'M';
    b[2] = (uint8_t)total;
    b[3] = (uint8_t)(total >> 8);
    b[4] = (uint8_t)(total >> 16);
    b[5] = (uint8_t)(total >> 24);
    b[10] = 54; /* データ開始 */
    b[14] = 40; /* BITMAPINFOHEADER */
    b[18] = (uint8_t)fw;
    b[19] = (uint8_t)(fw >> 8);
    b[20] = (uint8_t)(fw >> 16);
    b[21] = (uint8_t)(fw >> 24);
    b[22] = (uint8_t)fh;
    b[23] = (uint8_t)(fh >> 8);
    b[24] = (uint8_t)(fh >> 16);
    b[25] = (uint8_t)(fh >> 24);
    b[26] = 1;  /* プレーン数 */
    b[28] = 24; /* 24bpp */
    b[34] = (uint8_t)(stride * (uint32_t)fh);
    b[35] = (uint8_t)((stride * (uint32_t)fh) >> 8);
    b[36] = (uint8_t)((stride * (uint32_t)fh) >> 16);
    b[37] = (uint8_t)((stride * (uint32_t)fh) >> 24);
    for (uint64_t y = 0; y < fh; y++) {
        uint64_t sy = fh - 1 - y; /* BMP は下から上へ */
        for (uint64_t x = 0; x < fw; x++) {
            uint32_t rgb = fb_get_pixel_rgb(x, sy);
            size_t off = 54 + (size_t)y * stride + (size_t)x * 3;
            b[off + 0] = (uint8_t)(rgb & 0xFF);        /* B */
            b[off + 1] = (uint8_t)((rgb >> 8) & 0xFF);  /* G */
            b[off + 2] = (uint8_t)((rgb >> 16) & 0xFF); /* R */
        }
    }
    if (vfs_write(name, (const char *)b, total) == 0) {
        persist_maybe_sync();
        serial_write("screenshot: saved ");
        serial_write_line(name);
        desktop_notify(L("Screenshot saved",
                         "スクリーンショットを保存しました"));
    } else {
        desktop_notify(L("Screenshot failed",
                         "スクリーンショットに失敗しました"));
    }
    desktop_redraw();
}

static int desktop_handle_key_inner(int c);

int desktop_handle_key(int c) {
    if (appguard_enter() != 0) {
        desk_contain_fault("key");
        return 1;
    }
    int rc = desktop_handle_key_inner(c);
    appguard_leave();
    return rc;
}

/* 自己テスト: 武装した領域の中でわざとフォルトを起こし、
 * 封じ込めが働くか (例外 → appguard_bail → ここへ戻る)
 * を確かめる。evil.elf がサンドボックスに対して果たす
 * 役割と同じ、封じ込め機構そのものの検証用。 */
void desktop_appguard_selftest(void) {
    if (appguard_enter() != 0) {
        serial_write_line(
            "[appguard] self-test: fault contained, desktop alive");
        return;
    }
    *(volatile uint8_t *)0 = 0x41; /* ページフォルトさせる */
    appguard_leave();
    serial_write_line(
        "[appguard] self-test: NO fault occurred (unexpected)");
}

static int desktop_handle_key_inner(int c) {
    if (!desk_ok) {
        return 0;
    }
    /* ロック中は解除キーだけを受ける。 */
    if (desk_locked) {
        return lock_key(c);
    }
    /* Ctrl+U: スクリーンショット (どのアプリでも)。 */
    if (c == PRISM_KEY_CTRL_LETTER_BASE + ('u' - 'a')) {
        desktop_screenshot();
        return 1;
    }
    /* ショートカットのキー取り込み中は、押された特殊キーを
     * そのまま割り当てにする (Esc は取り消し)。アプリ起動の
     * 割り当て判定より先に処理しないと、取り込みたいキーで
     * アプリが起動してしまう。 */
    if (desk_mode == DESK_SETTINGS && bind_capture) {
        if (c == 0x1B) {
            bind_capture = 0;
            desktop_redraw();
            return 1;
        }
        if (c >= 0x90 && c <= 0x93) {
            /* 矢印キーは設定画面の移動に使う予約キー。
             * 名前で保存できない (parse が戻せない) ので
             * 割り当てには使わない。取り込みは続ける。 */
            return 1;
        }
        if (c >= 0x81) {
            int a = bind_selected;
            /* 既に他のアクションが使っているキーなら入れ替える
             * (重複した割り当てを作らない)。 */
            for (int i = 0; i < PRISM_BIND_COUNT; i++) {
                if (i != a && desk_settings.binds[i] == (uint8_t)c) {
                    desk_settings.binds[i] = desk_settings.binds[a];
                }
            }
            desk_settings.binds[a] = (uint8_t)c;
            bind_capture = 0;
            settings_autosave();
            desktop_redraw();
        }
        return 1;
    }
    /* Wi-Fi 接続ダイアログが開いている間はキーを占有する
     * (パスワード入力を他の画面へ漏らさない)。 */
    if (wifi_dlg_is_open()) {
        return wifi_dlg_key(c);
    }
    /* 最小化中はどのキーでもウィンドウを復帰させる
     * (押されたキー自体は消費する)。 */
    if (desk_win_min) {
        desk_win_min = 0;
        serial_write_line("window: restored");
        desktop_redraw();
        return 1;
    }
    /* 検索アクションの割り当てキーが検索 / ウィンドウ一覧を
     * 開閉する (既定は F8)。 */
    if (c == desk_settings.binds[PRISM_ACT_SEARCH]) {
        if (search_active) {
            search_active = 0;
            desktop_redraw();
        } else {
            search_active = 1;
            search_len = 0;
            search_query[0] = '\0';
            search_rebuild();
            desktop_redraw();
        }
        return 1;
    }
    if (search_active) {
        if (c == DESK_KEY_F9) {
            int on = ime_toggle();
            desktop_notify(on ? L("IME on", "IME オン")
                              : L("IME off", "IME オフ"));
            desktop_redraw();
            return 1;
        }
        if (c == 0x1B) {
            if (ime_active()) {
                char dummy[8];
                ime_feed(0x1B, dummy, sizeof(dummy));
                desktop_redraw();
                return 1;
            }
            search_active = 0;
            desktop_redraw();
            return 1;
        }
        if (ime_key_common(c, search_insert_text)) {
            return 1;
        }
        if (c == '\n' || c == '\r') {
            search_activate();
            return 1;
        }
        if (c == DESK_KEY_UP) {
            if (search_selected > 0) {
                search_selected--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            if (search_selected + 1 < search_count) {
                search_selected++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            if (search_len > 0) {
                search_len--;
                search_query[search_len] = '\0';
                search_rebuild();
                desktop_refresh_console();
            }
            return 1;
        }
        if (c >= 32 && c <= 126 &&
            search_len + 1 < (int)sizeof(search_query)) {
            search_query[search_len++] = (char)c;
            search_query[search_len] = '\0';
            search_rebuild();
            desktop_refresh_console();
            return 1;
        }
        return 1; /* Other keys while searching: consumed. */
    }
    /* ネットワークのクイックパネルは Esc で閉じる。 */
    if (net_panel_open && c == 0x1B) {
        net_panel_open = 0;
        serial_write_line("wifi: quick panel closed");
        desktop_redraw();
        return 1;
    }
    /* ランチャーとメニューが開いている間はキーを占有する。 */
    if (launcher_active && launcher_closing) {
        /* 閉じアニメーション中のキーは閉じを完了させてから
         * 通常処理する (入力を取りこぼさない)。 */
        launcher_active = 0;
        launcher_closing = 0;
    }
    if (launcher_active) {
        int n = launcher_entries();
        if (launcher_power_open) {
            /* 電源メニュー展開中 (B8)。 */
            if (c == 0x1B || c == DESK_KEY_LEFT ||
                c == DESK_KEY_RIGHT) {
                launcher_power_open = 0;
            } else if (c == DESK_KEY_UP) {
                launcher_power_sel =
                    (launcher_power_sel + POWER_COUNT - 1) %
                    POWER_COUNT;
            } else if (c == DESK_KEY_DOWN) {
                launcher_power_sel =
                    (launcher_power_sel + 1) % POWER_COUNT;
            } else if (c == '\n' || c == '\r') {
                int w = launcher_power_sel;
                launcher_power_open = 0;
                launcher_active = 0;
                serial_write("launcher: ");
                serial_write_line(power_label(w));
                power_action(w);
            }
            desktop_redraw();
            return 1;
        }
        if (launcher_power_focus) {
            /* 電源ボタンにフォーカス (B8)。 */
            if (c == '\n' || c == '\r') {
                launcher_power_open = 1;
                launcher_power_sel = 0;
                desktop_redraw();
                return 1;
            }
            if (c == DESK_KEY_UP) {
                launcher_power_focus = 0;
                desktop_redraw();
                return 1;
            }
            if (c == 0x1B) {
                launcher_request_close();
                launcher_power_focus = 0;
                desktop_redraw();
                return 1;
            }
            launcher_power_focus = 0;
        }
        if (c == 0x1B) {
            launcher_request_close();
            desktop_redraw();
        } else if (c == DESK_KEY_LEFT) {
            /* 端で循環する (B2)。 */
            launcher_selected = (launcher_selected + n - 1) % n;
            desktop_redraw();
        } else if (c == DESK_KEY_RIGHT) {
            launcher_selected = (launcher_selected + 1) % n;
            desktop_redraw();
        } else if (c == DESK_KEY_UP) {
            int rows = (n + LAUNCH_COLS - 1) / LAUNCH_COLS;
            int row = launcher_selected / LAUNCH_COLS;
            int col = launcher_selected % LAUNCH_COLS;
            row = (row + rows - 1) % rows;
            launcher_selected = row * LAUNCH_COLS + col;
            if (launcher_selected >= n) {
                launcher_selected = n - 1;
            }
            desktop_redraw();
        } else if (c == DESK_KEY_DOWN) {
            int rows = (n + LAUNCH_COLS - 1) / LAUNCH_COLS;
            int row = launcher_selected / LAUNCH_COLS;
            int col = launcher_selected % LAUNCH_COLS;
            if (row >= rows - 1) {
                /* 最下段から下は電源ボタンへ (B8)。 */
                launcher_power_focus = 1;
            } else {
                row++;
                launcher_selected = row * LAUNCH_COLS + col;
                if (launcher_selected >= n) {
                    launcher_selected = n - 1;
                }
            }
            desktop_redraw();
        } else if (c == '\n' || c == '\r') {
            launcher_activate(launcher_selected);
        } else if (c >= 32 && c <= 126) {
            /* 文字を打ち始めたら検索へ移る (その文字を
             * クエリの先頭にする)。 */
            launcher_active = 0;
            search_open();
            char first[2] = {(char)c, '\0'};
            search_insert_text(first);
            desktop_redraw();
        }
        return 1;
    }
    if (menu_active) {
        if (c == 0x1B) {
            menu_active = 0;
            desktop_redraw();
        }
        return 1;
    }
    if (widgets_open) {
        if (c == 0x1B) {
            widgets_open = 0;
            serial_write_line("widgets: closed");
            desktop_redraw();
        } else if (c == 'r' || c == 'R') {
            widgets_fetch();
            desktop_redraw();
        }
        return 1;
    }
    /* フォーカスのあるウィンドウが通常キーを先に受け取る
     * (F キー等の特殊コードは従来通りアプリ切替に回す)。 */
    if (desk_mode == DESK_TERMINAL && win_focus >= 0 &&
        win_open[win_focus]) {
        if (c == 0x1B) {
            win_close(win_focus);
            return 1;
        }
        if (c < 0x80 || c == 0xA2 || c == 0xB2 || c == 0xC7) {
            return win_key(win_focus, c);
        }
    }
    /* Notes では Ctrl+V は貼り付け (ビデオ起動より優先)。 */
    if (desk_mode == DESK_NOTES && c == 0xA2) {
        notes_load();
        if (notes_buf != NULL) {
            notes_undo_push(1);
            size_t n = 0;
            const char *clip = desktop_clipboard_get(&n);
            for (size_t i = 0; i < n; i++) {
                if (notes_len + 1 < PRISM_VFS_MAX_APP_FILE_SIZE) {
                    for (size_t j = notes_len; j > notes_cursor; j--) {
                        notes_buf[j] = notes_buf[j - 1];
                    }
                    notes_buf[notes_cursor++] = clip[i];
                    notes_len++;
                    notes_buf[notes_len] = '\0';
                    notes_dirty = 1;
                    notes_saved = 0;
                }
            }
            desktop_refresh_console();
        }
        return 1;
    }
    /* エディタ / Docs / メール作成でも Ctrl+V は貼り付け
     * (ビデオ起動より優先)。コピー側は従来どおり Notes の
     * 行コピーと Files の名前コピー。 */
    if (desk_mode == DESK_EDITOR && c == 0xA2 &&
        editor_stage == 0) {
        size_t n = 0;
        const char *clip = desktop_clipboard_get(&n);
        if (clip != NULL && n > 0) {
            char tmp[1024];
            size_t m = n < sizeof(tmp) - 1 ? n : sizeof(tmp) - 1;
            for (size_t i = 0; i < m; i++) {
                tmp[i] = clip[i];
            }
            tmp[m] = '\0';
            editor_insert_text(tmp);
            serial_write_line("editor: pasted");
        }
        desktop_redraw();
        return 1;
    }
    if (desk_mode == DESK_DOCS && c == 0xA2) {
        docs_load();
        size_t n = 0;
        const char *clip = desktop_clipboard_get(&n);
        if (clip != NULL && n > 0) {
            char tmp[1024];
            size_t m = n < sizeof(tmp) - 1 ? n : sizeof(tmp) - 1;
            for (size_t i = 0; i < m; i++) {
                tmp[i] = clip[i];
            }
            tmp[m] = '\0';
            docs_insert_text(tmp);
            serial_write_line("docs: pasted");
        }
        desktop_refresh_console();
        return 1;
    }
    if (desk_mode == DESK_MAIL && mail_composing && c == 0xA2) {
        size_t n = 0;
        const char *clip = desktop_clipboard_get(&n);
        if (clip != NULL && n > 0) {
            char *buf = NULL;
            size_t cap = 0;
            if (mail_field == 0) {
                buf = mail_to;
                cap = sizeof(mail_to);
            } else if (mail_field == 1) {
                buf = mail_subject;
                cap = sizeof(mail_subject);
            } else if (mail_field == 3) {
                buf = mail_attach_name;
                cap = sizeof(mail_attach_name);
            }
            if (buf != NULL) {
                size_t len = 0;
                while (buf[len] != '\0') {
                    len++;
                }
                for (size_t i = 0; i < n && len + 1 < cap; i++) {
                    if (clip[i] >= 32 && clip[i] < 127) {
                        buf[len++] = clip[i];
                    }
                }
                buf[len] = '\0';
            } else if (mail_field == 2) {
                for (size_t i = 0; i < n; i++) {
                    if (mail_body_len + 1 < sizeof(mail_body) &&
                        clip[i] >= 32 && clip[i] < 127) {
                        mail_body[mail_body_len++] = clip[i];
                        mail_body[mail_body_len] = '\0';
                    }
                }
            }
            serial_write_line("mail: pasted");
        }
        desktop_redraw();
        return 1;
    }
    /* テキスト入力アプリでは F9 は日本語入力 (IME) の
     * オン/オフ (アプリ起動キーより優先)。 */
    if ((desk_mode == DESK_NOTES || desk_mode == DESK_EDITOR ||
         desk_mode == DESK_DOCS || desk_mode == DESK_MAIL) &&
        c == DESK_KEY_F9) {
        int on = ime_toggle();
        desktop_notify(on ? L("IME on - romaji to kana (F9: off)", "IME オン - ローマ字かな変換 (F9: オフ)")
                          : L("IME off", "IME オフ"));
        desktop_refresh_console();
        return 1;
    }
    /* ブラウザ使用中はタブ/ブックマーク系の Ctrl キーを
     * アプリ起動キーより優先する (F9 の IME と同じ扱い)。 */
    if (desk_mode == DESK_BROWSER) {
        if (c == PRISM_KEY_CTRL_LETTER_BASE + ('t' - 'a')) {
            br_tab_new();
            return 1;
        }
        if (c == PRISM_KEY_CTRL_LETTER_BASE + ('w' - 'a')) {
            br_tab_close(br_tab_cur);
            return 1;
        }
        if (c == PRISM_KEY_CTRL_D) { /* ドライバは D を専用コードで返す */
            br_bmk_toggle();
            return 1;
        }
        if (c == PRISM_KEY_CTRL_LETTER_BASE + ('b' - 'a')) {
            if (br_panel == 1) {
                br_panel = 0;
                desktop_redraw();
            } else {
                br_panel_open(1);
            }
            return 1;
        }
        if (c == PRISM_KEY_CTRL_LETTER_BASE + ('h' - 'a')) {
            if (br_panel == 2) {
                br_panel = 0;
                desktop_redraw();
            } else {
                br_panel_open(2);
            }
            return 1;
        }
    }
    /* アプリ起動: 割り当てられたキーで launch_action へ。
     * 割り当ては設定画面のショートカットページで変更できる。 */
    for (int a = 0; a < PRISM_BIND_COUNT; a++) {
        if (a == PRISM_ACT_SEARCH) {
            continue;
        }
        if (c == desk_settings.binds[a]) {
            launch_action(a);
            return 1;
        }
    }
    if (c == DESK_KEY_CTRL_N) {
        if (desk_mode == DESK_SLIDES && !slides_show) {
            int was_editing = slides_editing;
            slides_commit_edit();
            if (!was_editing) {
                slides_history_push();
            }
            int n = slides_add(&slides_deck);
            if (n >= 0) {
                slides_current = n;
                slides_field = 0;
                slides_editing = 0;
                slides_dirty = 1;
                slides_saved = 0;
                desktop_redraw();
            }
        }
        return 1;
    }
    if (c == DESK_KEY_CTRL_E) {
        if (desk_mode == DESK_DOCS) {
            docs_export();
            desktop_refresh_console();
        } else if (desk_mode == DESK_SLIDES && !slides_show) {
            slides_export();
            desktop_refresh_console();
        }
        return 1;
    }
    if (c == DESK_KEY_CTRL_R) {
        if (desk_mode == DESK_DOCS) {
            docs_import();
            desktop_redraw();
        } else if (desk_mode == DESK_SLIDES && !slides_show) {
            slides_import();
            desktop_redraw();
        }
        return 1;
    }
    if (c == DESK_KEY_F6) {
        if (desk_mode == DESK_NOTES) {
            notes_save();
            desktop_refresh_console();
        }
        if (desk_mode == DESK_DOCS) {
            docs_save();
            desktop_refresh_console();
        }
        if (desk_mode == DESK_SLIDES) {
            slides_save();
            desktop_refresh_console();
        }
        if (desk_mode == DESK_EDITOR) {
            editor_save();
        }
        if (desk_mode == DESK_PAINT) {
            paint_save_bmp();
            desktop_redraw();
        }
        return 1;
    }
    if (c == 0x1B) { /* Esc */
        if ((desk_mode == DESK_NOTES || desk_mode == DESK_EDITOR ||
             desk_mode == DESK_DOCS || desk_mode == DESK_MAIL) &&
            ime_active()) {
            char dummy[8];
            ime_feed(0x1B, dummy, sizeof(dummy));
            desktop_refresh_console();
            return 1;
        }
        if (desk_mode == DESK_SLIDES && slides_show) {
            slides_show = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_CARDS && cards_game != 0) {
            cards_game = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_MAIL && mail_setup_mode) {
            mail_setup_mode = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_STORE && store_srv_mode) {
            store_srv_mode = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_MAIL && mail_composing) {
            mail_composing = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_MAIL && mail_viewing >= 0) {
            mail_viewing = -1;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_SHEET && sheet_editing) {
            /* Cancel the edit, keep the old cell content. */
            sheet_editing = 0;
            sheet_edit_len = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_SETTINGS &&
            (pin_dialog_open || acct_mode != ACCT_MODE_LIST)) {
            /* 設定のフォーム/ダイアログの Esc は取り消し。 */
            settings_cancel_modal();
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_FILES && (files_prompt || files_confirm)) {
            /* Files の入力/確認の Esc は取り消し。 */
            files_prompt = 0;
            files_confirm = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_FILES && files_viewing >= 0) {
            files_viewing = -1;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_BROWSER && br_panel) {
            br_panel = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_BROWSER && br_find_mode) {
            br_find_mode = 0;
            desktop_refresh_console();
            return 1;
        }
        if (desk_mode == DESK_SETTINGS && settings_page == 7 &&
            adm_form) {
            adm_form = 0;
            adm_pass1_len = 0;
            adm_pass2_len = 0;
            adm_pass1[0] = '\0';
            adm_pass2[0] = '\0';
            desktop_redraw();
            return 1;
        }
        if (desk_mode == DESK_PHOTOS && photos_viewing >= 0) {
            photos_viewing = -1;
            photos_slideshow = 0;
            photos_zoom = 0;
            photos_rot = 0;
            desktop_redraw();
            return 1;
        }
        if (desk_mode != DESK_TERMINAL) {
            switch_mode(DESK_TERMINAL);
            return 1;
        }
        return 1; /* Esc in the terminal: ignore it. */
    }
    if (desk_mode == DESK_FILES) {
        files_build_rows();
        if (files_prompt) {
            if (c == '\n' || c == '\r') {
                files_prompt_commit();
                return 1;
            }
            if (c == '\b' || c == 0x7f) {
                if (files_prompt_len > 0) {
                    files_prompt_len--;
                    files_prompt_buf[files_prompt_len] = '\0';
                }
                desktop_redraw();
                return 1;
            }
            if (c >= 0x20 && c < 0x7f && c != '/' &&
                files_prompt_len + 1 < (int)sizeof(files_prompt_buf)) {
                files_prompt_buf[files_prompt_len++] = (char)c;
                files_prompt_buf[files_prompt_len] = '\0';
                desktop_redraw();
                return 1;
            }
            return 1;
        }
        if (files_confirm) {
            if (c == 'y' || c == 'Y' || c == '\n' || c == '\r') {
                int cf = files_confirm;
                files_confirm = 0;
                if (cf == 1) {
                    files_trash_empty();
                    desktop_notify(L("Trash emptied", "ゴミ箱を空にしました"));
                } else {
                    (void)vfs_delete(files_confirm_name);
                    serial_write("files: deleted permanently ");
                    serial_write_line(files_confirm_name);
                    persist_maybe_sync();
                    desktop_notify(L("Deleted permanently", "完全に削除しました"));
                }
                files_build_rows();
                desktop_redraw();
                return 1;
            }
            if (c == 'n' || c == 'N') {
                files_confirm = 0;
                desktop_redraw();
                return 1;
            }
            return 1;
        }
        if (c == DESK_KEY_UP) {
            if (files_grid) {
                int cols = (int)((win_x() + win_w() - 12 -
                                  files_x()) / 108);
                if (cols < 1) {
                    cols = 1;
                }
                if (files_selected >= cols) {
                    files_selected -= cols;
                }
            } else if (files_selected > 0) {
                files_selected--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            if (files_grid) {
                int cols = (int)((win_x() + win_w() - 12 -
                                  files_x()) / 108);
                if (cols < 1) {
                    cols = 1;
                }
                if (files_selected + cols < files_row_count) {
                    files_selected += cols;
                }
            } else if (files_selected + 1 < files_row_count) {
                files_selected++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (files_grid && c == DESK_KEY_LEFT) {
            if (files_selected > 0) {
                files_selected--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (files_grid && c == DESK_KEY_RIGHT) {
            if (files_selected + 1 < files_row_count) {
                files_selected++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (files_viewing < 0 && c == 'v') {
            files_grid = !files_grid;
            serial_write_line(files_grid ? "files: view grid"
                                         : "files: view list");
            desktop_redraw();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            files_activate_row();
            return 1;
        }
        if (files_viewing < 0 && c == 'n') {
            files_prompt_start(2, NULL);
            return 1;
        }
        if (files_viewing < 0 && c == 'm') {
            files_prompt_start(3, NULL);
            return 1;
        }
        if (files_viewing < 0 && c == 'r') {
            if (files_selected >= 0 &&
                files_selected < files_row_count &&
                files_rows[files_selected] >= 0) {
                const char *nm =
                    vfs_file_name(files_rows[files_selected]);
                const char *bs = nm;
                for (const char *q2 = nm; *q2 != '\0'; q2++) {
                    if (*q2 == '/') {
                        bs = q2 + 1;
                    }
                }
                if (files_in_trash()) {
                    char btmp[28];
                    size_t bp = 0;
                    while (bs[bp] != '\0' && bp + 1 < sizeof(btmp)) {
                        btmp[bp] = bs[bp];
                        bp++;
                    }
                    btmp[bp] = '\0';
                    if (files_trash_restore(btmp) == 0) {
                        desktop_notify(L("Restored", "元に戻しました"));
                    } else {
                        desktop_notify(L("Could not restore",
                             "戻せませんでした (同名あり?)"));
                    }
                    files_build_rows();
                } else {
                    files_prompt_start(1, bs);
                }
            }
            desktop_redraw();
            return 1;
        }
        if (files_viewing < 0 && c == 'c' && !files_in_trash()) {
            if (files_selected >= 0 &&
                files_selected < files_row_count &&
                files_rows[files_selected] >= 0) {
                const char *nm =
                    vfs_file_name(files_rows[files_selected]);
                const char *bs = nm;
                for (const char *q2 = nm; *q2 != '\0'; q2++) {
                    if (*q2 == '/') {
                        bs = q2 + 1;
                    }
                }
                files_prompt_start(4, bs);
            }
            return 1;
        }
        if (files_viewing < 0 && c == 'o') {
            files_sort_mode = (files_sort_mode + 1) % 3;
            serial_write("files: sort ");
            serial_write_line(files_sort_mode == 1
                                  ? "date"
                                  : files_sort_mode == 2
                                  ? "size"
                                  : "name");
            desktop_redraw();
            return 1;
        }
        if (files_viewing < 0 && files_in_trash() && c == 'x') {
            if (files_selected >= 0 &&
                files_selected < files_row_count &&
                files_rows[files_selected] >= 0) {
                const char *nm =
                    vfs_file_name(files_rows[files_selected]);
                size_t cp = 0;
                while (nm[cp] != '\0' &&
                       cp + 1 < sizeof(files_confirm_name)) {
                    files_confirm_name[cp] = nm[cp];
                    cp++;
                }
                files_confirm_name[cp] = '\0';
                files_confirm = 2;
                desktop_redraw();
            }
            return 1;
        }
        if (files_viewing < 0 && files_in_trash() && c == 'e') {
            files_confirm = 1;
            desktop_redraw();
            return 1;
        }
        if (c == 'd' && !files_in_trash()) {
            if (files_selected >= 0 &&
                files_selected < files_row_count) {
                int rowv = files_rows[files_selected];
                if (rowv >= 0) {
                    const char *name = vfs_file_name(rowv);
                    char tmp[32];
                    size_t p = 0;
                    while (name[p] != '\0' && p + 1 < sizeof(tmp)) {
                        tmp[p] = name[p];
                        p++;
                    }
                    tmp[p] = '\0';
                    if (files_trash_file(tmp) == 0) {
                        serial_write("files: trashed ");
                        serial_write_line(tmp);
                        desktop_notify(L("Moved to trash", "ゴミ箱へ移動しました"));
                    } else {
                        desktop_notify(L("Could not trash it",
                     "ゴミ箱へ移動できませんでした"));
                    }
                } else if (rowv <= -2) {
                    /* 空のディレクトリだけ消せる。 */
                    char path[40];
                    size_t p = 0;
                    size_t q = 0;
                    while (files_dir[q] != '\0' &&
                           p + 1 < sizeof(path)) {
                        path[p++] = files_dir[q++];
                    }
                    if (p > 0 && p + 1 < sizeof(path)) {
                        path[p++] = '/';
                    }
                    const char *dn = files_dirnames[-2 - rowv];
                    q = 0;
                    while (dn[q] != '\0' && p + 1 < sizeof(path)) {
                        path[p++] = dn[q++];
                    }
                    /* 中身はマーカーだけか */
                    int count2 = vfs_file_count();
                    int only_marker = 1;
                    for (int i2 = 0; i2 < count2; i2++) {
                        const char *n2 = vfs_file_name(i2);
                        size_t k2 = 0;
                        while (k2 < p && n2[k2] == path[k2]) {
                            k2++;
                        }
                        if (k2 == p && n2[p] == '/' &&
                            strcmp(n2 + p + 1, ".dir") != 0) {
                            only_marker = 0;
                        }
                    }
                    if (only_marker) {
                        size_t mp = p;
                        const char *sfx = "/.dir";
                        size_t sq = 0;
                        while (sfx[sq] != '\0' &&
                               mp + 1 < sizeof(path)) {
                            /* path を一時的に使う */
                            sq++;
                            mp++;
                        }
                        char marker[48];
                        size_t m2 = 0;
                        while (m2 < p && m2 + 1 < sizeof(marker)) {
                            marker[m2] = path[m2];
                            m2++;
                        }
                        const char *sf2 = "/.dir";
                        size_t s2 = 0;
                        while (sf2[s2] != '\0' &&
                               m2 + 1 < sizeof(marker)) {
                            marker[m2++] = sf2[s2++];
                        }
                        marker[m2] = '\0';
                        (void)vfs_delete(marker);
                        desktop_notify(L("Directory removed", "フォルダを削除しました"));
                    } else {
                        desktop_notify(L("Directory not empty",
                     "フォルダが空ではありません"));
                    }
                }
                files_build_rows();
                desktop_refresh_console();
            }
            return 1;
        }
        return 1; /* Other keys in Files: consumed, not typed. */
    }
    if (desk_mode == DESK_SETTINGS) {
        /* 管理者 PIN ダイアログが開いている間はキーを占有する。 */
        if (pin_dialog_open) {
            return pin_dialog_key(c);
        }
        /* アカウントのフォーム表示中はキーを占有する
         * (Tab は入力欄の移動に使う)。 */
        if (settings_page == 2 && acct_mode != ACCT_MODE_LIST) {
            return acct_key(c);
        }
        /* 管理ページの FDE フォーム表示中も同様
         * (Tab は入力欄の移動)。 */
        if (settings_page == 7 && adm_form) {
            return adm_key(c);
        }
        /* カード列のページスクロール (全ページ共通)。
         * 選択があるページでは描画側が選択へ寄せる。 */
        if (c == DESK_KEY_PGUP || c == DESK_KEY_PGDN) {
            int d = set_view_h > 0 ? set_view_h : 400;
            set_scroll[settings_page] +=
                (c == DESK_KEY_PGDN) ? d : -d;
            if (set_scroll[settings_page] < 0) {
                set_scroll[settings_page] = 0;
            }
            desktop_refresh_console();
            return 1;
        }
        /* Tab でページ切り替え (見た目→ショートカット→
         * アカウント→セキュリティ→更新→時計→見た目)。 */
        if (c == '\t') {
            settings_page = (settings_page + 1) % 8;
            if (settings_page == 3 || settings_page == 4 ||
                settings_page == 5 || settings_page == 6) {
                settings_refresh_shared();
            }
            if (settings_page == 4) {
                upd_refresh_snaps();
            }
            if (settings_page == 5) {
                clk_refresh();
            }
            if (settings_page == 6) {
                net_refresh();
            }
            if (settings_page == 7) {
                adm_refresh();
            }
            desktop_redraw();
            return 1;
        }
        if (settings_page == 1) {
            /* ショートカットページ。 */
            if (c == DESK_KEY_UP) {
                if (bind_selected > 0) {
                    bind_selected--;
                }
                desktop_refresh_console();
                return 1;
            }
            if (c == DESK_KEY_DOWN) {
                if (bind_selected + 1 < PRISM_BIND_COUNT) {
                    bind_selected++;
                }
                desktop_refresh_console();
                return 1;
            }
            if (c == '\n' || c == '\r') {
                bind_capture = 1;
                desktop_redraw();
                return 1;
            }
            if (c == '0') {
                /* 割り当てを全部既定値に戻す。 */
                settings_binds_defaults(desk_settings.binds);
                settings_autosave();
                desktop_redraw();
                return 1;
            }
            if (c == 's') {
                if (save_desk_settings() == 0) {
                    settings_saved = 1;
                    desktop_notify(L("Settings saved", "設定を保存しました"));
                }
                desktop_refresh_console();
                return 1;
            }
            return 1; /* Other keys on the shortcuts page: consumed. */
        }
        if (settings_page == 2) {
            return acct_key(c);
        }
        if (settings_page == 3) {
            return sec_key(c);
        }
        if (settings_page == 4) {
            return upd_key(c);
        }
        if (settings_page == 5) {
            return clock_key(c);
        }
        if (settings_page == 6) {
            return net_key(c);
        }
        if (settings_page == 7) {
            return adm_key(c);
        }
        if (settings_page == 0 &&
            (c == DESK_KEY_UP || c == DESK_KEY_DOWN)) {
            /* 見た目ページ: カード列を 1 枚分スクロール。 */
            int step = set_card_h() + UI_CARD_GAP;
            set_scroll[0] += (c == DESK_KEY_DOWN) ? step : -step;
            if (set_scroll[0] < 0) {
                set_scroll[0] = 0;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c >= '1' && c <= '7') {
            desk_settings.accent_rgb = PRISM_ACCENTS[c - '1'];
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 't') {
            /* タスクバー位置: 下 → 上 → 左 → 右 → 下。 */
            if (desk_settings.taskbar_side == 1) {
                desk_settings.taskbar_side = 2;
            } else if (desk_settings.taskbar_side == 2) {
                desk_settings.taskbar_side = 0;
                desk_settings.taskbar_top = 0;
            } else if (desk_settings.taskbar_top) {
                desk_settings.taskbar_side = 1;
                desk_settings.taskbar_top = 0;
            } else {
                desk_settings.taskbar_top = 1;
            }
            settings_autosave();
            serial_write("settings: taskbar ");
            serial_write_line(desk_settings.taskbar_side == 1
                                  ? "left"
                                  : desk_settings.taskbar_side == 2
                                  ? "right"
                                  : desk_settings.taskbar_top
                                  ? "top"
                                  : "bottom");
            desktop_redraw();
            return 1;
        }
        if (c == 'c') {
            /* 横タスクバーのアイコン配置: 中央寄せ <-> 左寄せ。 */
            desk_settings.taskbar_center =
                !desk_settings.taskbar_center;
            settings_autosave();
            serial_write("settings: taskbar icons ");
            serial_write_line(desk_settings.taskbar_center
                                  ? "center"
                                  : "left");
            desktop_redraw();
            return 1;
        }
        if (c == 'm') {
            desk_settings.dark_mode = !desk_settings.dark_mode;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'w') {
            /* 描画 -> 標準画像 -> 自分の画像 (設定済みのとき)
             * -> 描画、の順に巡回する。 */
            int cur = desk_settings.wallpaper_image;
            int next;
            if (cur == 0) {
                next = 1;
            } else if (cur == 1) {
                next = desk_settings.wallpaper_file[0] != '\0' ? 2 : 0;
            } else {
                next = 0;
            }
            desk_settings.wallpaper_image = next;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'W') {
            /* 標準の壁紙画像に戻す。 */
            desk_settings.wallpaper_image = 1;
            settings_autosave();
            serial_write_line("settings: wallpaper reset to standard");
            desktop_redraw();
            return 1;
        }
        if (c == 'k') {
            desk_settings.dock_show = !desk_settings.dock_show;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'a') {
            desk_settings.ui_motion = !desk_settings.ui_motion;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'p') {
            desk_settings.dock_pos = !desk_settings.dock_pos;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'z') {
            desk_settings.dock_size = !desk_settings.dock_size;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'h') {
            desk_settings.dock_autohide = !desk_settings.dock_autohide;
            settings_autosave();
            desktop_redraw();
            return 1;
        }
        if (c == 'g') {
            desk_settings.language = !desk_settings.language;
            settings_autosave();
            desktop_notify(desk_settings.language
                               ? L("Language: Japanese", "言語: 日本語")
                               : L("Language: English", "言語: 英語"));
            desktop_redraw();
            return 1;
        }
        if (c == 'x') {
            desk_settings.high_contrast =
                !desk_settings.high_contrast;
            settings_autosave();
            desktop_notify(desk_settings.high_contrast
                               ? L("High contrast on",
                                   "ハイコントラスト オン")
                               : L("High contrast off",
                                   "ハイコントラスト オフ"));
            desktop_redraw();
            return 1;
        }
        if (c == 'b') {
            desk_settings.text_scale =
                desk_settings.text_scale >= 3
                    ? 1
                    : desk_settings.text_scale + 1;
            settings_autosave();
            console_refit();
            serial_write("settings: text size ");
            serial_write_num(desk_settings.text_scale);
            serial_write_line("");
            desktop_notify(desk_settings.text_scale >= 3
                               ? L("Text size: extra large",
                                   "文字サイズ: 特大")
                               : desk_settings.text_scale >= 2
                               ? L("Text size: large", "文字サイズ: 大")
                               : L("Text size: standard",
                                   "文字サイズ: 標準"));
            desktop_redraw();
            return 1;
        }
        if (c == 'o') {
            desk_settings.osk = !desk_settings.osk;
            settings_autosave();
            serial_write_line(desk_settings.osk
                                  ? "settings: on-screen keyboard on"
                                  : "settings: on-screen keyboard off");
            desktop_notify(desk_settings.osk
                               ? L("On-screen keyboard on",
                                   "画面キーボード オン")
                               : L("On-screen keyboard off",
                                   "画面キーボード オフ"));
            desktop_redraw();
            return 1;
        }
        if (c == 'n') {
            desk_settings.narrator = !desk_settings.narrator;
            settings_autosave();
            if (!desk_settings.narrator) {
                narrator_caption[0] = '\0';
            }
            serial_write_line(desk_settings.narrator
                                  ? "settings: narrator on"
                                  : "settings: narrator off");
            desktop_notify(desk_settings.narrator
                               ? L("Narrator on", "ナレーター オン")
                               : L("Narrator off", "ナレーター オフ"));
            desktop_redraw();
            return 1;
        }
        if (c == 'j') {
            desk_settings.kbd_layout = !desk_settings.kbd_layout;
            keyboard_set_layout(desk_settings.kbd_layout);
            settings_autosave();
            desktop_notify(desk_settings.kbd_layout
                               ? L("Keyboard: JIS", "キーボード: JIS")
                               : L("Keyboard: US", "キーボード: US"));
            desktop_redraw();
            return 1;
        }
        if (c == 'r') {
            /* 解像度をプリセット順に切り替える (シェルの
             * res と同じ処理。設定に保存して永続化する)。 */
            static const uint16_t modes[4][2] = {
                {1280, 800}, {1024, 768}, {800, 600}, {640, 480}};
            uint32_t cw = fb_width();
            uint32_t chh = fb_height();
            int next = 0;
            for (int i = 0; i < 4; i++) {
                if (modes[i][0] == cw && modes[i][1] == chh) {
                    next = (i + 1) % 4;
                }
            }
            if (vbe_set_mode(modes[next][0], modes[next][1]) == 0) {
                mouse_set_bounds(modes[next][0], modes[next][1]);
                mouse_set_position(modes[next][0] / 2,
                                   modes[next][1] / 2);
                /* 解像度を永続化する (シェルの res と同じ)。 */
                desk_settings.res_w = modes[next][0];
                desk_settings.res_h = modes[next][1];
                settings_autosave();
                serial_write("settings: resolution ");
                serial_write_num(modes[next][0]);
                serial_write("x");
                serial_write_num(modes[next][1]);
                serial_write_line("");
                desktop_notify(L("Resolution changed",
                                 "解像度を変更しました"));
            } else {
                serial_write_line("settings: resolution failed");
                desktop_notify(L("Resolution change failed",
                                 "解像度を変更できませんでした"));
            }
            desktop_redraw();
            return 1;
        }
        if (c == 'e') {
            /* マウス速度をプリセット順に切り替える。 */
            static const int speeds[5] = {50, 75, 100, 150, 200};
            int next = 100;
            for (int i = 0; i < 5; i++) {
                if (desk_settings.mouse_speed == speeds[i]) {
                    next = speeds[(i + 1) % 5];
                }
            }
            desk_settings.mouse_speed = next;
            mouse_set_speed(next);
            settings_autosave();
            serial_write("settings: mouse speed ");
            serial_write_num(next);
            serial_write_line("");
            desktop_redraw();
            return 1;
        }
        if (c == 'i') {
            desk_settings.key_repeat =
                (desk_settings.key_repeat + 1) % 3;
            keyboard_set_repeat(desk_settings.key_repeat);
            settings_autosave();
            serial_write("settings: key repeat ");
            serial_write_num(desk_settings.key_repeat);
            serial_write_line("");
            desktop_redraw();
            return 1;
        }
        if (c == 'u') {
            static const int intervals[5] = {200, 350, 500, 700,
                                             900};
            int next = 500;
            for (int i = 0; i < 5; i++) {
                if (desk_settings.dblclick_ms == intervals[i]) {
                    next = intervals[(i + 1) % 5];
                }
            }
            desk_settings.dblclick_ms = next;
            settings_autosave();
            serial_write("settings: dblclick ");
            serial_write_num(next);
            serial_write_line("");
            desktop_redraw();
            return 1;
        }
        if (c == 's') {
            if (save_desk_settings() == 0) {
                settings_saved = 1;
                desktop_notify(L("Settings saved", "設定を保存しました"));
            }
            desktop_refresh_console();
            return 1;
        }
        return 1; /* Other keys in Settings: consumed, not typed. */
    }
    if (desk_mode == DESK_INSTALLER) {
        if (inst_step == INSTALL_STEP_INSTALLING) {
            return 1; /* Installing: ignore keys. */
        }
        if (c == 0x1B) { /* Esc */
            int back = install_step_back(inst_step);
            if (back >= 0) {
                inst_step = (install_step)back;
                inst_error[0] = '\0';
                serial_write_line("installer: step back");
                desktop_redraw();
            } else {
                switch_mode(DESK_TERMINAL);
            }
            return 1;
        }
        if (inst_step == INSTALL_STEP_WELCOME) {
            if (c == '\n' || c == '\r') {
                int next =
                    install_step_next(inst_step, inst_has_disk, 0, 0);
                if (next >= 0) {
                    inst_step = (install_step)next;
                    serial_write_line("installer: step disk");
                    desktop_redraw();
                }
            }
            return 1;
        }
        if (inst_step == INSTALL_STEP_DISK) {
            if (c == 'a') {
                inst_target = 0;
                inst_error[0] = '\0';
                desktop_redraw();
            } else if (c == 'd') {
                if (inst_kind == INSTALL_DISK_BOOTABLE) {
                    inst_target = 1;
                    inst_error[0] = '\0';
                } else {
                    inst_copy(inst_error, sizeof(inst_error),
                              L("No data partition on this disk.", "このディスクにデータパーティションがありません"));
                }
                desktop_redraw();
            } else if (c == 'w') {
                if (inst_kind == INSTALL_DISK_BOOTABLE) {
                    inst_copy(inst_error, sizeof(inst_error),
                              L("Whole disk would erase the boot partition.", "ディスク全体だと起動パーティションも消えます"));
                } else {
                    /* 起動可能なディスクは作れない: 起動ファイルは
                     * インストール媒体にあり、OS からは読めない
                     * (CD の読み取り手段がなく、ディスクは 1 台
                     * しか扱えないため、写す元もない)。選んでも
                     * データ用パーティションへのインストールに
                     * すり替えることはしない。 */
                    inst_copy(inst_error, sizeof(inst_error),
                              L("Whole-disk install is not available yet.", "ディスク全体へのインストールはまだ使えません"));
                    serial_write_line(
                        "installer: whole-disk not available");
                }
                desktop_redraw();
            } else if (c == '\n' || c == '\r') {
                int next =
                    install_step_next(inst_step, inst_has_disk, 0, 0);
                if (next >= 0) {
                    inst_step = (install_step)next;
                    serial_write_line("installer: step profile");
                    desktop_redraw();
                }
            }
            return 1;
        }
        if (inst_step == INSTALL_STEP_PROFILE) {
            if (c == '1') {
                inst_profile = 0;
                desktop_redraw();
            } else if (c == '2') {
                inst_profile = 1;
                desktop_redraw();
            } else if (c == '\n' || c == '\r') {
                int next = install_step_next(inst_step, 1,
                                            inst_profile >= 0, 0);
                if (next >= 0) {
                    inst_step = (install_step)next;
                    serial_write_line("installer: step confirm");
                    desktop_redraw();
                }
            }
            return 1;
        }
        if (inst_step == INSTALL_STEP_CONFIRM) {
            if (c == 'y' || c == 'Y') {
                installer_run_install();
            }
            return 1;
        }
        if (inst_step == INSTALL_STEP_DONE) {
            if (c == 'r' || c == 'R') {
                shell_reboot_now();
            }
            return 1;
        }
        /* FAILED: only Esc (handled above) goes back. */
        return 1;
    }
    if (desk_mode == DESK_CONTACTS) {
        return contacts_handle_key(c);
    }
    if (desk_mode == DESK_EDITOR) {
        return editor_handle_key(c);
    }
    if (desk_mode == DESK_PAINT) {
        return paint_handle_key(c);
    }
    if (desk_mode == DESK_STORE) {
        return store_handle_key(c);
    }
    if (desk_mode == DESK_NOTIF) {
        if (c == DESK_KEY_UP) {
            if (notif_scroll > 0) {
                notif_scroll--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            notif_scroll++;
            desktop_refresh_console();
            return 1;
        }
        if (c == 0x1B) {
            switch_mode(DESK_TERMINAL);
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_CLOCK) {
        if (clock_handle_key(c)) {
            return 1;
        }
        if (c == 0x1B) {
            switch_mode(DESK_TERMINAL);
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_RECORDER) {
        if (rec_handle_key(c)) {
            return 1;
        }
        if (c == 0x1B) {
            switch_mode(DESK_TERMINAL);
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_CAMERA) {
        if (cam_handle_key(c)) {
            return 1;
        }
        if (c == 0x1B) {
            switch_mode(DESK_TERMINAL);
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_MAIL) {
        if (mail_setup_mode) {
            return mail_setup_key(c);
        }
        if (mail_composing) {
            if (c == '\t') {
                mail_field = (mail_field + 1) % 5;
                desktop_redraw();
                return 1;
            }
            if ((mail_field == 1 || mail_field == 2) &&
                ime_key_common(c, mail_insert_text)) {
                return 1;
            }
            if (c == '\b' || c == 0x7F) {
                if (mail_field == 0) {
                    size_t n = 0;
                    while (mail_to[n] != '\0') {
                        n++;
                    }
                    if (n > 0) {
                        mail_to[n - 1] = '\0';
                    }
                } else if (mail_field == 1) {
                    size_t n = 0;
                    while (mail_subject[n] != '\0') {
                        n++;
                    }
                    if (n > 0) {
                        mail_subject[n - 1] = '\0';
                    }
                } else if (mail_field == 2 && mail_body_len > 0) {
                    mail_body[--mail_body_len] = '\0';
                } else if (mail_field == 3) {
                    size_t n = 0;
                    while (mail_attach_name[n] != '\0') {
                        n++;
                    }
                    if (n > 0) {
                        mail_attach_name[n - 1] = '\0';
                    }
                }
                desktop_redraw();
                return 1;
            }
            if (c == '\n' || c == '\r') {
                if (mail_field == 4) {
                    mail_send_from_app();
                } else if (mail_field == 2) {
                    if (mail_body_len + 1 < sizeof(mail_body)) {
                        mail_body[mail_body_len++] = '\n';
                        mail_body[mail_body_len] = '\0';
                    }
                    desktop_redraw();
                } else {
                    mail_field++;
                    desktop_redraw();
                }
                return 1;
            }
            if (c >= 32 && c < 127) {
                if (mail_field == 0) {
                    size_t n = 0;
                    while (mail_to[n] != '\0') {
                        n++;
                    }
                    if (n + 1 < sizeof(mail_to)) {
                        mail_to[n] = (char)c;
                        mail_to[n + 1] = '\0';
                    }
                } else if (mail_field == 1) {
                    size_t n = 0;
                    while (mail_subject[n] != '\0') {
                        n++;
                    }
                    if (n + 1 < sizeof(mail_subject)) {
                        mail_subject[n] = (char)c;
                        mail_subject[n + 1] = '\0';
                    }
                } else if (mail_field == 2) {
                    if (mail_body_len + 1 < sizeof(mail_body)) {
                        mail_body[mail_body_len++] = (char)c;
                        mail_body[mail_body_len] = '\0';
                    }
                } else if (mail_field == 3) {
                    size_t n = 0;
                    while (mail_attach_name[n] != '\0') {
                        n++;
                    }
                    if (n + 1 < sizeof(mail_attach_name)) {
                        mail_attach_name[n] = (char)c;
                        mail_attach_name[n + 1] = '\0';
                    }
                }
                desktop_redraw();
                return 1;
            }
            return 1;
        }
        if (mail_viewing >= 0) {
            if (c == 'r' || c == 'R') {
                mail_start_reply(0);
                return 1;
            }
            if (c == 'f' || c == 'F') {
                mail_start_reply(1);
                return 1;
            }
            if (c == DESK_KEY_UP) {
                if (mail_scroll > 0) {
                    mail_scroll--;
                }
                desktop_refresh_console();
                return 1;
            }
            if (c == DESK_KEY_DOWN) {
                mail_scroll++;
                desktop_refresh_console();
                return 1;
            }
            return 1;
        }
        if (mail_search_mode) {
            if (c == '\n' || c == '\r') {
                mail_search_buf[mail_search_len] = '\0';
                inst_copy(mail_filter, sizeof(mail_filter),
                          mail_search_buf);
                mail_search_mode = 0;
                mail_selected = 0;
                mail_rebuild();
                serial_write("mail: filter ");
                serial_write_line(mail_filter);
                desktop_redraw();
            } else if (c == 0x1B) {
                mail_search_mode = 0;
                mail_filter[0] = '\0';
                mail_rebuild();
                desktop_redraw();
            } else if (c == '\b' || c == 0x7F) {
                if (mail_search_len > 0) {
                    mail_search_len--;
                }
                desktop_redraw();
            } else if (c >= 32 && c < 127) {
                if (mail_search_len + 1 < sizeof(mail_search_buf)) {
                    mail_search_buf[mail_search_len++] = (char)c;
                }
                desktop_redraw();
            }
            return 1;
        }
        if (mail_move_mode) {
            if (c == '\n' || c == '\r') {
                mail_move_buf[mail_move_len] = '\0';
                if (mail_list_count > 0 && mail_move_len > 0) {
                    mail_set_folder_of(
                        mail_num_of(mail_selected),
                        mail_move_buf);
                    desktop_notify(L("Mail moved", "メールを移動しました"));
                    serial_write("mail: moved to ");
                    serial_write_line(mail_move_buf);
                }
                mail_move_mode = 0;
                mail_rebuild();
                desktop_redraw();
            } else if (c == '\b' || c == 0x7F) {
                if (mail_move_len > 0) {
                    mail_move_len--;
                }
                desktop_redraw();
            } else if (c >= 32 && c < 127) {
                if (mail_move_len + 1 < sizeof(mail_move_buf)) {
                    mail_move_buf[mail_move_len++] = (char)c;
                }
                desktop_redraw();
            }
            return 1;
        }
        if (c == DESK_KEY_UP) {
            if (mail_selected > 0) {
                mail_selected--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            if (mail_selected + 1 < mail_list_count) {
                mail_selected++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (mail_list_count > 0) {
                mail_viewing = mail_selected;
                mail_scroll = 0;
                desktop_refresh_console();
            }
            return 1;
        }
        if (c == 'o' || c == 'O') {
            /* アカウント設定フォームを開く。 */
            mail_setup_open();
            desktop_redraw();
            return 1;
        }
        if (c == 'c' || c == 'C') {
            mail_composing = 1;
            mail_field = 0;
            mail_to[0] = '\0';
            mail_subject[0] = '\0';
            mail_attach_name[0] = '\0';
            mail_body_len = 0;
            mail_body[0] = '\0';
            desktop_redraw();
            return 1;
        }
        if (c == 'r' || c == 'R') {
            mail_receive_from_app();
            return 1;
        }
        if (c == '/') {
            mail_search_mode = 1;
            mail_search_len = 0;
            mail_search_buf[0] = '\0';
            serial_write_line("mail: search mode");
            desktop_redraw();
            return 1;
        }
        if (c == 'f' || c == 'F') {
            /* Cycle the folder view: Inbox, Sent, Trash,
             * then each custom folder in use. */
            char names[8][24];
            int nn = 0;
            inst_copy(names[nn++], 24, "Inbox");
            inst_copy(names[nn++], 24, "Sent");
            inst_copy(names[nn++], 24, "Trash");
            size_t flen = 0;
            const char *ft =
                vfs_read_ptr("mail-folders.txt", &flen);
            if (ft != NULL) {
                size_t i = 0;
                while (i < flen && nn < 8) {
                    size_t ls = i;
                    while (i < flen && ft[i] != '\n') {
                        i++;
                    }
                    for (size_t k = ls; k < i; k++) {
                        if (ft[k] == '=') {
                            char cand[24];
                            size_t cp = 0;
                            for (size_t m = k + 1;
                                 m < i && cp + 1 < sizeof(cand);
                                 m++) {
                                if (ft[m] != '\r') {
                                    cand[cp++] = ft[m];
                                }
                            }
                            cand[cp] = '\0';
                            int dup = 0;
                            for (int q = 0; q < nn; q++) {
                                if (strcmp(names[q], cand) ==
                                    0) {
                                    dup = 1;
                                }
                            }
                            if (!dup && cand[0] != '\0') {
                                inst_copy(names[nn++], 24,
                                          cand);
                            }
                            break;
                        }
                    }
                    i++;
                }
            }
            int cur = 0;
            for (int q = 0; q < nn; q++) {
                if (strcmp(names[q], mail_folder_cur()) == 0) {
                    cur = q;
                }
            }
            inst_copy(mail_folder, sizeof(mail_folder),
                      names[(cur + 1) % nn]);
            mail_selected = 0;
            mail_viewing = -1;
            mail_rebuild();
            serial_write("mail: folder ");
            serial_write_line(mail_folder_cur());
            desktop_redraw();
            return 1;
        }
        if (c == 'm' || c == 'M') {
            if (mail_list_count > 0 &&
                strcmp(mail_folder_cur(), "Sent") != 0) {
                mail_move_mode = 1;
                mail_move_len = 0;
                mail_move_buf[0] = '\0';
                desktop_redraw();
            }
            return 1;
        }
        if (c == 'd' || c == 'D') {
            if (mail_list_count > 0) {
                const char *name =
                    vfs_file_name(mail_list_idx[mail_selected]);
                char tmp[32];
                size_t p = 0;
                while (*name != '\0' && p + 1 < sizeof(tmp)) {
                    tmp[p++] = *name++;
                }
                tmp[p] = '\0';
                if (strcmp(mail_folder_cur(), "Trash") == 0 ||
                    strcmp(mail_folder_cur(), "Sent") == 0) {
                    (void)vfs_delete(tmp);
                } else {
                    mail_set_folder_of(
                        mail_num_of(mail_selected), "Trash");
                    desktop_notify(L("Mail moved to Trash", "メールをゴミ箱へ移動しました"));
                }
                mail_rebuild();
                desktop_refresh_console();
            }
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_BROWSER) {
        if (br_panel) {
            if (c == DESK_KEY_UP) {
                if (br_panel_sel > 0) {
                    br_panel_sel--;
                }
            } else if (c == DESK_KEY_DOWN) {
                if (br_panel_sel + 1 < br_panel_count()) {
                    br_panel_sel++;
                }
            } else if (c == '\n' || c == '\r') {
                br_panel_activate();
            }
            desktop_redraw();
            return 1;
        }
        if (br_find_mode) {
            if (c == '\n' || c == '\r') {
                br_find_buf[br_find_len] = '\0';
                br_find_run();
            } else if (c == '\b' || c == 0x7F) {
                if (br_find_len > 0) {
                    br_find_len--;
                }
            } else if (c >= 32 && c <= 126 &&
                       br_find_len + 1 < (int)sizeof(br_find_buf)) {
                br_find_buf[br_find_len++] = (char)c;
            }
            desktop_refresh_console();
            return 1;
        }
        if (br_ctrl_focus >= 0 && br_ctrl_focus < br_ctrl_count &&
            browser_state == 1) {
            /* フォーム入力欄がキーを受け取る。特殊キーは
             * ここでは消費せず後段 (スクロール等) に回す。 */
            br_ctrl *ct = &br_ctrls[br_ctrl_focus];
            if (c == '\b' || c == 0x7F) {
                size_t l = strlen(ct->value);
                if (l > 0) {
                    l--;
                    while (l > 0 &&
                           (ct->value[l] & 0xC0) == 0x80) {
                        l--;
                    }
                    ct->value[l] = '\0';
                }
                desktop_redraw();
                return 1;
            }
            if (c == '\n' || c == '\r') {
                br_form_submit(br_ctrl_focus);
                return 1;
            }
            if (c == 0x1B) {
                br_ctrl_focus = -1;
                desktop_redraw();
                return 1;
            }
            if (c >= 32 && c <= 126) {
                size_t l = strlen(ct->value);
                if (l + 1 < sizeof(ct->value)) {
                    ct->value[l] = (char)c;
                    ct->value[l + 1] = '\0';
                }
                desktop_redraw();
                return 1;
            }
        }
        if (c == 0xB5) { /* Ctrl+F: ページ内検索 */
            if (browser_state == 1) {
                br_find_mode = 1;
                br_find_len = 0;
                br_find_buf[0] = '\0';
                br_find_last = browser_scroll - 1;
                serial_write_line("browser: find opened");
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == 0xC2) { /* Ctrl+S: ページを保存 */
            if (browser_state == 1) {
                br_save_page();
            }
            desktop_redraw();
            return 1;
        }
        if (c == DESK_KEY_ZOOM_IN || c == DESK_KEY_ZOOM_OUT) {
            if (browser_state == 1) {
                browser_zoom += (c == DESK_KEY_ZOOM_IN) ? 1 : -1;
                if (browser_zoom > 3) {
                    browser_zoom = 3;
                }
                if (browser_zoom < 1) {
                    browser_zoom = 1;
                }
                br_render_current();
                serial_write("browser: zoom ");
                serial_write_num(browser_zoom);
                serial_write_line("");
            }
            desktop_redraw();
            return 1;
        }
        if (c == '\t') {
            /* Tab cycles links and form controls in
             * document order. */
            if (browser_state == 1 && br_fseq_count > 0) {
                br_fseq_pos = (br_fseq_pos + 1) % br_fseq_count;
                int kind = br_fseq_kind[br_fseq_pos];
                int idx = br_fseq_idx[br_fseq_pos];
                if (kind == 0) {
                    br_focus = idx;
                    br_ctrl_focus = -1;
                    serial_write("browser: focus ");
                    serial_write_line(br_links[idx]);
                } else {
                    br_ctrl_focus = idx;
                    br_focus = -1;
                    serial_write("browser: input focus ");
                    serial_write_line(br_ctrls[idx].name);
                }
                int target = -1;
                for (int li = 0;
                     li < br_line_count && target < 0; li++) {
                    if (kind == 0 && br_lines[li].link == idx) {
                        target = li;
                        break;
                    }
                    for (int si = 0; si < br_lines[li].nsegs;
                         si++) {
                        br_seg *s = &br_lines[li].segs[si];
                        if ((kind == 0 && s->link == idx) ||
                            (kind == 1 && s->ctrl == idx)) {
                            target = li;
                            break;
                        }
                    }
                }
                if (target >= 0 &&
                    (target < browser_scroll ||
                     target > browser_scroll + 12)) {
                    browser_scroll = target;
                }
                desktop_redraw();
            }
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (browser_state == 1 && br_focus >= 0 &&
                br_focus < br_link_count) {
                br_navigate(br_links[br_focus]);
            } else if (browser_url_len > 0) {
                if (br_is_download_url(browser_url)) {
                    br_download(browser_url);
                } else {
                    browser_load();
                    desktop_redraw();
                }
            }
            return 1;
        }
        if (c == DESK_KEY_UP) {
            if (browser_scroll > 0) {
                browser_scroll--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            browser_scroll++;
            desktop_refresh_console();
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            if (browser_url_len > 0) {
                browser_url_len--;
                browser_url[browser_url_len] = '\0';
                browser_state = 0;
                browser_scroll = 0;
                br_focus = -1;
                desktop_redraw();
            }
            return 1;
        }
        if (c >= 32 && c <= 126) {
            if (browser_url_len + 1 < (int)sizeof(browser_url)) {
                browser_url[browser_url_len++] = (char)c;
                browser_url[browser_url_len] = '\0';
                browser_state = 0;
                browser_scroll = 0;
                br_focus = -1;
                desktop_redraw();
            }
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_NOTES) {
        notes_load();
        if (notes_buf == NULL) {
            return 1;
        }
        if (c == 0xC9) { /* Ctrl+Z: 取り消し */
            notes_undo_apply();
            return 1;
        }
        if (c == 0xC8) { /* Ctrl+Y: やり直し */
            notes_redo_apply();
            return 1;
        }
        if (c == 0xB5) { /* Ctrl+F: 検索 */
            notes_find_stage = 1;
            notes_find_replace = 0;
            notes_find_len = 0;
            notes_find_buf[0] = '\0';
            desktop_refresh_console();
            return 1;
        }
        if (c == 0xB7) { /* Ctrl+H: 置換 */
            notes_find_stage = 1;
            notes_find_replace = 1;
            notes_find_len = 0;
            notes_find_buf[0] = '\0';
            desktop_refresh_console();
            return 1;
        }
        if (notes_find_stage > 0) {
            char *buf = notes_find_stage == 1 ? notes_find_buf
                                              : notes_repl_buf;
            size_t *blen = notes_find_stage == 1
                               ? &notes_find_len
                               : &notes_repl_len;
            if (c == '\n' || c == '\r') {
                buf[*blen] = '\0';
                if (notes_find_stage == 1) {
                    inst_copy(notes_find_term,
                              sizeof(notes_find_term),
                              notes_find_buf);
                    if (notes_find_replace) {
                        notes_find_stage = 2;
                        notes_repl_len = 0;
                        notes_repl_buf[0] = '\0';
                    } else {
                        notes_find_stage = 0;
                        if (notes_find_next() >= 0) {
                            serial_write_line("notes: found");
                        } else {
                            desktop_notify(L("Not found",
                                             "見つかりませんでした"));
                        }
                    }
                } else {
                    notes_find_stage = 0;
                    int n = notes_replace_all();
                    serial_write("notes: replaced ");
                    serial_write_num(n);
                    serial_write_line(" occurrence(s)");
                }
                desktop_refresh_console();
            } else if (c == 0x1B) {
                notes_find_stage = 0;
                desktop_refresh_console();
            } else if (c == '\b' || c == 0x7F) {
                if (*blen > 0) {
                    (*blen)--;
                }
                desktop_refresh_console();
            } else if (c >= 32 && c <= 126) {
                if (*blen + 1 < 64) {
                    buf[(*blen)++] = (char)c;
                }
                desktop_refresh_console();
            }
            return 1;
        }
        if (notes_ime_key(c)) {
            return 1;
        }
        if (c == DESK_KEY_LEFT) {
            if (notes_cursor > 0) {
                notes_cursor--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_RIGHT) {
            if (notes_cursor < notes_len) {
                notes_cursor++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_UP) {
            /* Move up one line: back over the current line,
             * then over the previous line to the same column. */
            size_t col = 0;
            size_t i = notes_cursor;
            while (i > 0 && notes_buf[i - 1] != '\n') {
                i--;
                col++;
            }
            if (i == 0) {
                return 1;
            }
            size_t line_start = i;
            i--; /* skip the newline */
            size_t prev_start = i;
            while (prev_start > 0 && notes_buf[prev_start - 1] != '\n') {
                prev_start--;
            }
            (void)line_start;
            size_t prev_len = i - prev_start;
            notes_cursor = prev_start + (col < prev_len ? col : prev_len);
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            size_t i = notes_cursor;
            size_t col = 0;
            size_t line_start = i;
            while (line_start > 0 && notes_buf[line_start - 1] != '\n') {
                line_start--;
            }
            col = i - line_start;
            while (i < notes_len && notes_buf[i] != '\n') {
                i++;
            }
            if (i >= notes_len) {
                return 1;
            }
            i++; /* first char of the next line */
            size_t next_end = i;
            while (next_end < notes_len && notes_buf[next_end] != '\n') {
                next_end++;
            }
            size_t next_len = next_end - i;
            notes_cursor = i + (col < next_len ? col : next_len);
            desktop_refresh_console();
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            if (notes_cursor > 0) {
                notes_undo_push(2);
                for (size_t i = notes_cursor - 1; i < notes_len; i++) {
                    notes_buf[i] = notes_buf[i + 1];
                }
                notes_len--;
                notes_cursor--;
                notes_buf[notes_len] = '\0';
                notes_dirty = 1;
                notes_saved = 0;
                desktop_refresh_console();
            }
            return 1;
        }
        if (c == 0xB2 || c == 0xC7) { /* Ctrl+C / Ctrl+X */
            size_t ls = notes_cursor;
            while (ls > 0 && notes_buf[ls - 1] != '\n') {
                ls--;
            }
            size_t le = notes_cursor;
            while (le < notes_len && notes_buf[le] != '\n') {
                le++;
            }
            desktop_clipboard_set(notes_buf + ls, le - ls);
            if (c == 0xC7) {
                notes_undo_push(2);
                size_t end = le < notes_len ? le + 1 : le;
                for (size_t i = ls; i + (end - ls) <= notes_len; i++) {
                    notes_buf[i] = notes_buf[i + (end - ls)];
                }
                notes_len -= end - ls;
                notes_buf[notes_len] = '\0';
                notes_cursor = ls;
                notes_dirty = 1;
                notes_saved = 0;
            }
            desktop_notify(c == 0xB2 ? L("Line copied", "行をコピーしました")
                              : L("Line cut", "行を切り取りました"));
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (notes_len + 1 < PRISM_VFS_MAX_APP_FILE_SIZE) {
                notes_undo_push(1);
                for (size_t i = notes_len; i > notes_cursor; i--) {
                    notes_buf[i] = notes_buf[i - 1];
                }
                notes_buf[notes_cursor] = '\n';
                notes_len++;
                notes_cursor++;
                notes_buf[notes_len] = '\0';
                notes_dirty = 1;
                notes_saved = 0;
                desktop_refresh_console();
            }
            return 1;
        }
        if (c >= 32 && c <= 126) {
            if (notes_len + 1 < PRISM_VFS_MAX_APP_FILE_SIZE) {
                notes_undo_push(1);
                for (size_t i = notes_len; i > notes_cursor; i--) {
                    notes_buf[i] = notes_buf[i - 1];
                }
                notes_buf[notes_cursor] = (char)c;
                notes_len++;
                notes_cursor++;
                notes_buf[notes_len] = '\0';
                notes_dirty = 1;
                notes_saved = 0;
                desktop_refresh_console();
            }
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_DOCS) {
        docs_load();
        if (docs_fr_stage > 0) {
            return docs_fr_key(c);
        }
        if (c == PRISM_KEY_CTRL_LETTER_BASE + ('f' - 'a')) {
            docs_fr_stage = 1;
            docs_fr_len = 0;
            while (docs_fr_find[docs_fr_len] != '\0') {
                docs_fr_len++;
            }
            docs_fr_show();
            desktop_refresh_console();
            return 1;
        }
        if (c == 0xC9) { /* Ctrl+Z */
            docs_undo_apply();
            return 1;
        }
        if (c == 0xC8) { /* Ctrl+Y */
            docs_redo_apply();
            return 1;
        }
        if (docs_fmt_pending) {
            if (c == '1' || c == '2' || c == '3' || c == '-' ||
                c == '0') {
                doc_line_type kind = DOC_LINE_PLAIN;
                if (c == '1') {
                    kind = DOC_LINE_H1;
                } else if (c == '2') {
                    kind = DOC_LINE_H2;
                } else if (c == '3') {
                    kind = DOC_LINE_H3;
                } else if (c == '-') {
                    kind = DOC_LINE_BULLET;
                }
                docs_history_push();
                doc_set_line_type(&docs_doc, kind);
                docs_dirty = 1;
                docs_saved = 0;
                docs_fmt_pending = 0;
                desktop_refresh_console();
                return 1;
            }
            if (c == '\\') {
                /* Two backslashes: type one literal backslash. */
                docs_fmt_pending = 0;
                docs_history_push();
                doc_insert_char(&docs_doc, '\\');
                docs_dirty = 1;
                docs_saved = 0;
                desktop_refresh_console();
                return 1;
            }
            /* Any other key: cancel the format, type the '\'
             * first, then fall through to the key below. */
            docs_fmt_pending = 0;
            docs_history_push();
            doc_insert_char(&docs_doc, '\\');
            docs_dirty = 1;
            docs_saved = 0;
        }
        if (c == '\\') {
            docs_fmt_pending = 1;
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_LEFT) {
            doc_cursor_left(&docs_doc);
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_RIGHT) {
            doc_cursor_right(&docs_doc);
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_UP) {
            size_t row = doc_cursor_row(&docs_doc);
            if (row == 0) {
                return 1;
            }
            size_t col = doc_cursor_col(&docs_doc);
            size_t s = 0;
            size_t e = 0;
            if (!doc_line_bounds(&docs_doc, row - 1, &s, &e)) {
                return 1;
            }
            size_t len = e - s;
            docs_doc.cursor = s + (col < len ? col : len);
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            size_t row = doc_cursor_row(&docs_doc);
            size_t col = doc_cursor_col(&docs_doc);
            size_t total = doc_line_count(&docs_doc);
            if (row + 1 >= total) {
                return 1;
            }
            size_t s = 0;
            size_t e = 0;
            if (!doc_line_bounds(&docs_doc, row + 1, &s, &e)) {
                return 1;
            }
            size_t len = e - s;
            docs_doc.cursor = s + (col < len ? col : len);
            desktop_refresh_console();
            return 1;
        }
        if (ime_key_common(c, docs_insert_text)) {
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            docs_history_push();
            doc_backspace(&docs_doc);
            docs_dirty = 1;
            docs_saved = 0;
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            docs_history_push();
            doc_insert_newline(&docs_doc);
            docs_dirty = 1;
            docs_saved = 0;
            desktop_refresh_console();
            return 1;
        }
        if (c >= 32 && c <= 126) {
            docs_history_push();
            doc_insert_char(&docs_doc, (char)c);
            docs_dirty = 1;
            docs_saved = 0;
            desktop_refresh_console();
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_SLIDES) {
        slides_load();
        if (!slides_show && c == 0xC9) { /* Ctrl+Z */
            slides_undo_apply();
            return 1;
        }
        if (!slides_show && c == 0xC8) { /* Ctrl+Y */
            slides_redo_apply();
            return 1;
        }
        if (slides_show) {
            if (c == DESK_KEY_LEFT || c == DESK_KEY_UP) {
                if (slides_current > 0) {
                    slides_current--;
                }
                desktop_redraw();
                return 1;
            }
            if (c == DESK_KEY_RIGHT || c == DESK_KEY_DOWN || c == ' ' ||
                c == '\n' || c == '\r') {
                if (slides_current + 1 < slides_deck.count) {
                    slides_current++;
                }
                desktop_redraw();
                return 1;
            }
            return 1;
        }
        if (c == '\t') {
            slides_commit_edit();
            const slide *sl = &slides_deck.slides[slides_current];
            int max_field = sl->line_count + 1;
            if (max_field > SLIDES_LINES_MAX) {
                max_field = SLIDES_LINES_MAX;
            }
            slides_field++;
            if (slides_field > max_field) {
                slides_field = 0;
            }
            slides_edit_start();
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_UP) {
            slides_commit_edit();
            if (slides_field > 0) {
                slides_field--;
            }
            slides_edit_start();
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            slides_commit_edit();
            const slide *sl = &slides_deck.slides[slides_current];
            int max_field = sl->line_count + 1;
            if (max_field > SLIDES_LINES_MAX) {
                max_field = SLIDES_LINES_MAX;
            }
            if (slides_field < max_field) {
                slides_field++;
            }
            slides_edit_start();
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            int was_field = slides_field;
            slides_commit_edit();
            const slide *sl = &slides_deck.slides[slides_current];
            if (was_field == 0) {
                slides_field = 1;
            } else {
                slides_field = was_field + 1;
                if (slides_field > sl->line_count + 1) {
                    slides_field = sl->line_count + 1;
                }
                if (slides_field > SLIDES_LINES_MAX) {
                    slides_field = SLIDES_LINES_MAX;
                }
            }
            slides_edit_start();
            desktop_refresh_console();
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            if (!slides_editing) {
                slides_edit_start();
            }
            if (slides_edit_len > 0) {
                slides_edit[--slides_edit_len] = '\0';
                slides_dirty = 1;
                slides_saved = 0;
            } else if (slides_field > 0 &&
                       slides_field - 1 <
                           slides_deck.slides[slides_current]
                               .line_count) {
                /* Empty bullet field: remove the line. */
                slides_commit_edit();
                slides_remove_line(&slides_deck, slides_current,
                                   slides_field - 1);
                if (slides_field > 1) {
                    slides_field--;
                }
                slides_dirty = 1;
                slides_saved = 0;
                slides_edit_start();
            }
            desktop_refresh_console();
            return 1;
        }
        if (c >= 32 && c <= 126) {
            if (!slides_editing) {
                slides_edit_start();
            }
            if (slides_edit_len + 1 < (int)sizeof(slides_edit)) {
                slides_edit[slides_edit_len++] = (char)c;
                slides_edit[slides_edit_len] = '\0';
                slides_dirty = 1;
                slides_saved = 0;
            }
            desktop_refresh_console();
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_CALENDAR) {
        if (c == DESK_KEY_LEFT) {
            cal_offset--;
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_RIGHT) {
            cal_offset++;
            desktop_refresh_console();
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_PHOTOS) {
        int list[PRISM_VFS_MAX_FILES];
        int count = photos_list(list, PRISM_VFS_MAX_FILES);
        if (photos_viewing >= 0) {
            if (c == 'w' || c == 'W') {
                photos_set_wallpaper();
                desktop_redraw();
            } else if (c == DESK_KEY_LEFT || c == DESK_KEY_RIGHT) {
                /* 前 / 次の写真へ (端では反対側へ回る)。 */
                if (count > 0) {
                    photos_viewing =
                        (photos_viewing +
                         (c == DESK_KEY_RIGHT ? 1 : count - 1)) %
                        count;
                    photos_selected = photos_viewing;
                    photos_zoom = 0;
                    photos_rot = 0;
                    photos_status[0] = '\0';
                    serial_write("photos: viewing ");
                    serial_write_num(photos_viewing);
                    serial_write_line("");
                }
                desktop_redraw();
            } else if (c == '+' || c == '-') {
                photos_zoom += (c == '+') ? 1 : -1;
                if (photos_zoom > 2) {
                    photos_zoom = 2;
                }
                if (photos_zoom < 0) {
                    photos_zoom = 0;
                }
                serial_write("photos: zoom ");
                serial_write_num(photos_zoom);
                serial_write_line("");
                desktop_redraw();
            } else if (c == 'r' || c == 'R') {
                photos_rot = (photos_rot + 1) % 4;
                serial_write("photos: rotate ");
                serial_write_num(photos_rot * 90);
                serial_write_line("");
                desktop_redraw();
            } else if (c == 's' || c == 'S') {
                photos_slideshow = !photos_slideshow;
                serial_write_line(photos_slideshow
                                      ? "photos: slideshow on"
                                      : "photos: slideshow off");
                desktop_redraw();
            }
            return 1; /* Viewing: only Esc (handled above) leaves. */
        }
        if (c == DESK_KEY_UP || c == DESK_KEY_DOWN ||
            c == DESK_KEY_LEFT || c == DESK_KEY_RIGHT) {
            /* グリッド移動 (C7): 左右は隣、上下は列数分。 */
            int cols = (int)((win_w() - 16) / 128);
            if (cols < 1) {
                cols = 1;
            }
            int d = c == DESK_KEY_LEFT ? -1
                    : c == DESK_KEY_RIGHT ? 1
                    : c == DESK_KEY_UP ? -cols
                                       : cols;
            int ns = photos_selected + d;
            if (ns >= 0 && ns < count) {
                photos_selected = ns;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (count > 0) {
                photos_viewing = photos_selected;
                desktop_refresh_console();
            }
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_MUSIC) {
        int list[PRISM_VFS_MAX_FILES];
        int count = music_list(list, PRISM_VFS_MAX_FILES);
        if (c == DESK_KEY_UP) {
            if (music_selected > 0) {
                music_selected--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            if (music_selected + 1 < count) {
                music_selected++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (count > 0) {
                music_play_selected();
                desktop_refresh_console();
            }
            return 1;
        }
        if (c == '+' || c == '-') {
            volume_adjust(c == '+' ? 10 : -10);
            desktop_redraw();
            return 1;
        }
        if (c == ' ') {
            music_pause_toggle();
            desktop_redraw();
            return 1;
        }
        if (c == 's' || c == 'S') {
            music_stop();
            desktop_redraw();
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_CARDS) {
        return cards_handle_key(c);
    }
    if (desk_mode == DESK_SHOOTER) {
        if (c == 'n' || c == 'N') {
            shooter_new_game(&shooter_game_state);
            shooter_hitmark = 0;
            serial_write_line("shooter: new game");
            desktop_redraw();
            return 1;
        }
        if (c == ' ') {
            shooter_fire();
            desktop_redraw();
            return 1;
        }
        if (c == 'w' || c == 'W' || c == DESK_KEY_UP) {
            if (shooter_game_state.phase == 1) {
                shooter_try_move(&shooter_game_state.px,
                                 &shooter_game_state.py,
                                 shooter_game_state.angle,
                                 SHOOTER_FX_ONE * 15 / 100);
                desktop_redraw();
            }
            return 1;
        }
        if (c == 's' || c == 'S' || c == DESK_KEY_DOWN) {
            if (shooter_game_state.phase == 1) {
                shooter_try_move(&shooter_game_state.px,
                                 &shooter_game_state.py,
                                 (shooter_game_state.angle + 512) & 1023,
                                 SHOOTER_FX_ONE * 15 / 100);
                desktop_redraw();
            }
            return 1;
        }
        if (c == 'a' || c == 'A' || c == DESK_KEY_LEFT) {
            if (shooter_game_state.phase == 1) {
                shooter_turn(&shooter_game_state, -8);
                desktop_redraw();
            }
            return 1;
        }
        if (c == 'd' || c == 'D' || c == DESK_KEY_RIGHT) {
            if (shooter_game_state.phase == 1) {
                shooter_turn(&shooter_game_state, 8);
                desktop_redraw();
            }
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_SHEET) {
        if (sheet_fr_stage > 0) {
            return sheet_fr_key(c);
        }
        if (c == PRISM_KEY_CTRL_LETTER_BASE + ('f' - 'a')) {
            sheet_commit_edit();
            sheet_fr_stage = 1;
            sheet_fr_len = 0;
            while (sheet_fr_find[sheet_fr_len] != '\0') {
                sheet_fr_len++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == 0xC9) { /* Ctrl+Z */
            sheet_commit_edit();
            sheet_undo_apply();
            return 1;
        }
        if (c == 0xC8) { /* Ctrl+Y */
            sheet_redo_apply();
            return 1;
        }
        if (c == DESK_KEY_UP) {
            sheet_commit_edit();
            if (sheet_sel_row > 0) {
                sheet_sel_row--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_DOWN) {
            sheet_commit_edit();
            if (sheet_sel_row + 1 < SHEET_ROWS) {
                sheet_sel_row++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_LEFT) {
            sheet_commit_edit();
            if (sheet_sel_col > 0) {
                sheet_sel_col--;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == DESK_KEY_RIGHT) {
            sheet_commit_edit();
            if (sheet_sel_col + 1 < SHEET_COLS) {
                sheet_sel_col++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\t') {
            sheet_commit_edit();
            if (sheet_sel_col + 1 < SHEET_COLS) {
                sheet_sel_col++;
            } else if (sheet_sel_row + 1 < SHEET_ROWS) {
                sheet_sel_col = 0;
                sheet_sel_row++;
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\n' || c == '\r') {
            if (sheet_editing) {
                sheet_commit_edit();
            } else {
                sheet_editing = 1;
                sheet_edit_len = 0;
                sheet_edit[0] = '\0';
            }
            desktop_refresh_console();
            return 1;
        }
        if (c == '\b' || c == 0x7F) {
            if (sheet_editing && sheet_edit_len > 0) {
                sheet_edit_len--;
                sheet_edit[sheet_edit_len] = '\0';
                desktop_refresh_console();
            }
            return 1;
        }
        if (!sheet_editing && (c == 'g' || c == 'G')) {
            sheet_chart = !sheet_chart;
            serial_write_line(sheet_chart ? "sheet: chart on"
                                          : "sheet: chart off");
            desktop_redraw();
            return 1;
        }
        if (sheet_chart) {
            return 1; /* グラフ表示中は他のキーを受けない */
        }
        if (!sheet_editing && (c == 'o' || c == 'O')) {
            sheet_commit_edit();
            sheet_sort(sheet_sel_col, c == 'O');
            desktop_refresh_console();
            return 1;
        }
        if (!sheet_editing && (c == 's' || c == 'S')) {
            sheet_save();
            desktop_refresh_console();
            return 1;
        }
        if (!sheet_editing && (c == 'l' || c == 'L')) {
            sheet_load();
            desktop_refresh_console();
            return 1;
        }
        if (c >= 32 && c <= 126) {
            if (!sheet_editing) {
                sheet_editing = 1;
                sheet_edit_len = 0;
                sheet_edit[0] = '\0';
            }
            if (sheet_edit_len < SHEET_CELL_MAX) {
                sheet_edit[sheet_edit_len++] = (char)c;
                sheet_edit[sheet_edit_len] = '\0';
            }
            desktop_refresh_console();
            return 1;
        }
        return 1;
    }
    if (desk_mode == DESK_VIDEO) {
        if (c == ' ') {
            if (video_frame_count <= 0) {
                return 1;
            }
            video_player_state.playing = !video_player_state.playing;
            if (video_player_state.playing) {
                video_arm_next_tick();
                serial_write_line("video: play");
            } else {
                serial_write_line("video: pause");
            }
            desktop_redraw();
            if (video_player_state.playing &&
                video_play_frame_audio()) {
                /* 最初のフレームの音声も鳴らし、次のフレームは
                 * 音声が終わり次第進める。 */
                video_next_tick = (int64_t)tick_counter;
            }
            return 1;
        }
        if (c == DESK_KEY_LEFT || c == 'p' || c == 'P') {
            video_seek(&video_player_state, -1);
            video_arm_next_tick();
            desktop_redraw();
            return 1;
        }
        if (c == DESK_KEY_RIGHT || c == 'n' || c == 'N') {
            video_seek(&video_player_state, 1);
            video_arm_next_tick();
            desktop_redraw();
            return 1;
        }
        if (c == 'r' || c == 'R') {
            video_player_state.frame = 0;
            video_arm_next_tick();
            desktop_redraw();
            return 1;
        }
        if (c == '+' || c == '-') {
            volume_adjust(c == '+' ? 10 : -10);
            desktop_redraw();
            return 1;
        }
        return 1;
    }
    /* Terminal のスクロールバック (項目16)。 */
    if (desk_mode == DESK_TERMINAL &&
        (c == DESK_KEY_PGUP || c == DESK_KEY_PGDN)) {
        int avail = console_hist_count < CONSOLE_HIST_LINES
                        ? console_hist_count
                        : CONSOLE_HIST_LINES;
        if (c == DESK_KEY_PGUP) {
            console_view_offset += console_rows - 2;
            if (console_view_offset > avail) {
                console_view_offset = avail;
            }
            serial_write("terminal: scrollback ");
            serial_write_num(console_view_offset);
            serial_write_line("");
        } else {
            console_view_offset -= console_rows - 2;
            if (console_view_offset < 0) {
                console_view_offset = 0;
            }
        }
        desktop_refresh_console();
        return 1;
    }
    /* Terminal mode: arrows and other special keys are ignored. */
    if (c >= 0x80) {
        return 1;
    }
    return 0;
}
